INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ce1f0a-705f-44c9-9e1c-db211c181238', '和令狐相公入潼關', '和令狐相公入潼关', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寒光照旌節，關路曉無塵。","吏謁前丞相，山迎舊主人。","東瞻軍府靜，西望敕書頻。","心共黃河水，同昇天漢津。"]', '["寒光照旌節，关路晓無塵。","吏謁前丞相，山迎旧主人。","东瞻軍府静，西望敕书頻。","心共黄河水，同昇天漢津。"]', '诗', 'shi', '', NULL, '和令狐相公入潼關 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb59324-2136-41f0-82a7-a517efa537b2', '和令狐相公尋白閣老見留小飲因贈', '和令狐相公尋白閣老见留小饮因贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["傲士更逢酒，樂天仍對花。","文章管星曆，情興占年華。","宦達翻思退，名高却不誇。","惟存浩然氣，相共賞煙霞。"]', '["傲士更逢酒，乐天仍对花。","文章管星曆，情兴占年华。","宦達翻思退，名高却不誇。","惟存浩然氣，相共賞煙霞。"]', '诗', 'shi', '', NULL, '和令狐相公尋白閣老見留小飲因贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aeb8ff1-73e4-49a5-b67c-e91b98a5d350', '酬令狐相公雪中遊玄都見憶', '酬令狐相公雪中游玄都见憶', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["好雪動高情，心期在玉京。","人披鶴氅出，馬踏象筵行。","照耀樓臺變，淋漓松桂清。","玄都留五字，使入步虛聲。"]', '["好雪动高情，心期在玉京。","人披鹤氅出，马踏象筵行。","照耀楼台变，淋漓松桂清。","玄都留五字，使入步虛声。"]', '诗', 'shi', '', NULL, '酬令狐相公雪中遊玄都見憶 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ee9fcf-9538-4402-9fe5-14f63b7e4016', '和令狐相公以司空裴相見招南亭看雪四韻', '和令狐相公以司空裴相见招南亭看雪四韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["重門不下關，樞務有餘閑。","上客同看雪，高亭盡見山。","瑞呈霄漢外，興入笑言間。","知是平陽會，人人帶酒還。"]', '["重门不下关，樞務有餘闲。","上客同看雪，高亭尽见山。","瑞呈霄漢外，兴入笑言间。","知是平陽會，人人带酒還。"]', '诗', 'shi', '', NULL, '和令狐相公以司空裴相見招南亭看雪四韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3449103e-496f-47f2-aa5b-b81e3c7fd38b', '和鄆州令狐相公春晚對花', '和鄆州令狐相公春晚对花', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朱門退公後，高興對花枝。","望闕無窮思，看書欲盡時。","含芳朝競發，凝豔晚相宜。","人意殷勤惜，狂風豈得知。"]', '["朱门退公後，高兴对花枝。","望闕無窮思，看书欲尽时。","含芳朝競發，凝豔晚相宜。","人意殷勤惜，狂风豈得知。"]', '诗', 'shi', '', NULL, '和鄆州令狐相公春晚對花 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c880958c-a496-4906-bce3-fb6d1960e0d7', '酬令狐相公春日言懷見寄', '酬令狐相公春日言懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前陪看花處，鄰里近王昌。","今想臨戎地，旌旗出汶陽。","營飛柳絮雪，門耀戟枝霜。","東望清河水，心隨艑上郎。"]', '["前陪看花处，鄰里近王昌。","今想臨戎地，旌旗出汶陽。","營飞柳絮雪，门耀戟枝霜。","东望清河水，心隨艑上郎。"]', '诗', 'shi', '', NULL, '酬令狐相公春日言懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2ca839-a75e-419b-b10b-48aa5b39df86', '途次大梁雪中奉天平令狐相公書問兼示新什因思曩歲從此拜辭形於短篇以申仰謝', '途次大梁雪中奉天平令狐相公书问兼示新什因思曩歲從此拜辞形於短篇以申仰謝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["遠守宦情薄，故人書信來。","共曾花下別，今獨雪中回。","紙尾得新什，眉頭還暫開。","此時同鴈鶩，池上一徘徊。"]', '["远守宦情薄，故人书信来。","共曾花下別，今独雪中回。","紙尾得新什，眉头還暫开。","此时同鴈鶩，池上一徘徊。"]', '诗', 'shi', '', NULL, '途次大梁雪中奉天平令狐相公書問兼示新什因思曩歲從此拜辭形於短篇以申仰謝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc3a7980-f399-4fa0-af1e-a5adc1d5b7a1', '酬令狐相公秋懷見寄', '酬令狐相公秋懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寂寞蟬聲靜，差池燕羽回。","秋風憐越絕，朔氣想臺駘。","相去數千里，無因同一杯。","殷勤望飛鴈，新自塞垣來。"]', '["寂寞蟬声静，差池燕羽回。","秋风怜越絕，朔氣想台駘。","相去數千里，無因同一杯。","殷勤望飞鴈，新自塞垣来。"]', '诗', 'shi', '', NULL, '酬令狐相公秋懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db3cfe0-60e9-4dd0-82fc-32046acb82a0', '酬[太]原令狐相公見寄', '酬[太]原令狐相公见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["書信來天外，瓊瑤滿匣中。","衣冠南渡遠，旌節北門雄。","鶴唳華亭月，馬嘶榆塞風。","山川幾千里，惟有兩心同。"]', '["书信来天外，瓊瑤满匣中。","衣冠南渡远，旌節北门雄。","鹤唳华亭月，马嘶榆塞风。","山川幾千里，惟有兩心同。"]', '诗', 'shi', '', NULL, '酬[太]原令狐相公見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0614f11-4d88-4c60-ac6c-82a31f577cca', '酬令狐相公歲暮遠懷見寄', '酬令狐相公歲暮远懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["別侶孤鶴怨，沖天威鳳歸。","容光一以間，夢想是耶非。","芳訊遠彌重，知音老更稀。","不如湖上鴈，北向整毛衣。"]', '["別侶孤鹤怨，沖天威鳳归。","容光一以间，梦想是耶非。","芳訊远彌重，知音老更稀。","不如湖上鴈，北向整毛衣。"]', '诗', 'shi', '', NULL, '酬令狐相公歲暮遠懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea7fe90-dc97-4928-bccb-93cbf47eb991', '酬令狐相公親仁郭家花下即事見寄', '酬令狐相公親仁郭家花下即事见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["荀令園林好，山公遊賞頻。","豈無花下侶，遠望眼中人。","斜日漸移影，落英紛委塵。","一吟相思曲，惆悵江南春。"]', '["荀令园林好，山公游賞頻。","豈無花下侶，远望眼中人。","斜日漸移影，落英紛委塵。","一吟相思曲，惆悵江南春。"]', '诗', 'shi', '', NULL, '酬令狐相公親仁郭家花下即事見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2bc6a4c-5762-41fb-823c-8ef063558d4a', '酬令狐相公首夏閑居書懷見寄', '酬令狐相公首夏闲居书懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蕙草芳未歇，綠槐陰已成。","金罍唯獨酌，瑤瑟有離聲。","翔泳各殊勢，篇章空寄情。","應憐三十載，未變使君名。"]', '["蕙草芳未歇，綠槐陰已成。","金罍唯独酌，瑤瑟有離声。","翔泳各殊勢，篇章空寄情。","應怜三十載，未变使君名。"]', '诗', 'shi', '', NULL, '酬令狐相公首夏閑居書懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4417fb7-c663-4f78-a4c5-ff279a5a5579', '酬令狐相公庭前白菊花謝偶書所懷見寄', '酬令狐相公庭前白菊花謝偶书所懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["數叢如雪色，一旦冒霜開。","寒蘂差池落，清香斷續來。","思深含別怨，芳謝惜年催。","千里難同賞，看看又早梅。"]', '["數叢如雪色，一旦冒霜开。","寒蘂差池落，清香斷續来。","思深含別怨，芳謝惜年催。","千里难同賞，看看又早梅。"]', '诗', 'shi', '', NULL, '酬令狐相公庭前白菊花謝偶書所懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa51844-e14e-4b31-9f86-d56b660b009c', '酬令狐相公季冬南郊宿齋見寄', '酬令狐相公季冬南郊宿斋见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["壇下雪初霽，南城凍欲生。","齋心祠上帝，高步領名卿。","沐浴含芳澤，周旋聽佩聲。","猶憐廣平守，寂寞竟何成。"]', '["壇下雪初霽，南城凍欲生。","斋心祠上帝，高步領名卿。","沐浴含芳澤，周旋听佩声。","猶怜廣平守，寂寞竟何成。"]', '诗', 'shi', '', NULL, '酬令狐相公季冬南郊宿齋見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c13747-6de4-4110-92dc-114999ae6cae', '貞元中侍郎舅氏牧華州時余再忝科第前後由華覲謁陪登伏毒寺屢焉亦曾賦詩題於梁棟今典馮詡暇日登樓南望三峰浩然生思追想昔年之事因成篇題舊寺', '貞元中侍郎舅氏牧华州时余再忝科第前後由华覲謁陪登伏毒寺屢焉亦曾賦诗題於梁棟今典馮詡暇日登楼南望三峰浩然生思追想昔年之事因成篇題旧寺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾作關中客，頻經伏毒巖。","晴煙沙苑樹，晚日渭川帆。","昔是青春貌，今悲白雪髯。","郡樓空一望，含意卷高簾。"]', '["曾作关中客，頻經伏毒巖。","晴煙沙苑樹，晚日渭川帆。","昔是青春貌，今悲白雪髯。","郡楼空一望，含意卷高簾。"]', '诗', 'shi', '', NULL, '貞元中侍郎舅氏牧華州時余再忝科第前後由華覲謁陪登伏毒寺屢焉亦曾賦詩題於梁棟今典馮詡暇日登樓南望三峰浩然生思追想昔年之事因成篇題舊寺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201c5d1c-900e-4772-950b-7462b0927cdf', '酬令狐相公杏園花下飲有懷見寄', '酬令狐相公杏园花下饮有懷见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["年年曲江望，花發即經過。","未飲心先醉，臨風思倍多。","三春看又盡，兩地欲如何。","日望長安道，空成勞者歌。"]', '["年年曲江望，花發即經過。","未饮心先醉，臨风思倍多。","三春看又尽，兩地欲如何。","日望长安道，空成勞者歌。"]', '诗', 'shi', '', NULL, '酬令狐相公杏園花下飲有懷見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4613fb0-ddac-4218-8e28-73ff327fee9d', '令狐相公見示題洋州崔侍郎宅雙木瓜花頃接侍郎同舍陪宴樹下吟翫來什輒成和章', '令狐相公见示題洋州崔侍郎宅雙木瓜花頃接侍郎同舍陪宴樹下吟翫来什輒成和章', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金牛蜀樓遠，玉樹帝城春。","榮耀生華館，逢迎欠主人。","簾前疑小雪，牆外麗行塵。","來去皆回首，情深是德鄰。"]', '["金牛蜀楼远，玉樹帝城春。","榮耀生华館，逢迎欠主人。","簾前疑小雪，牆外丽行塵。","来去皆回首，情深是德鄰。"]', '诗', 'shi', '', NULL, '令狐相公見示題洋州崔侍郎宅雙木瓜花頃接侍郎同舍陪宴樹下吟翫來什輒成和章 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c3f011-7cbc-4ff2-a87c-95486d6b391a', '和令狐相公春早朝回鹽鐵使院中作', '和令狐相公春早朝回鹽鐵使院中作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["柳動御溝清，威遲堤上行。","城隅日未過，山色雨初晴。","鶯避傳呼起，花臨府署明。","簿書盈几案，要自有高情。"]', '["柳动御溝清，威遲堤上行。","城隅日未過，山色雨初晴。","鶯避傳呼起，花臨府署明。","簿书盈几案，要自有高情。"]', '诗', 'shi', '', NULL, '和令狐相公春早朝回鹽鐵使院中作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3d32bb-da81-4169-b71f-62f9c2144551', '和令狐僕射相公題龍回寺', '和令狐僕射相公題龙回寺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["茲地回鑾日，皇家禪聖時。","路無胡馬跡，人識漢官儀。","天子旌旗度，法王龍象隨。","知懷去家歎，經此益遲遲。"]', '["茲地回鑾日，皇家禪聖时。","路無胡马跡，人識漢官儀。","天子旌旗度，法王龙象隨。","知懷去家歎，經此益遲遲。"]', '诗', 'shi', '', NULL, '和令狐僕射相公題龍回寺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9d35f7-b9dc-44cd-9a31-30d7fabfab49', '令狐相公頻示新什早春南望遐想漢中因抒短章以寄情愫', '令狐相公頻示新什早春南望遐想漢中因抒短章以寄情愫', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["軍城臨漢水，旌斾起春風。","遠思見江草，歸心看塞鴻。","野花沿古道，新葉映行宮。","惟有詩兼酒，朝朝兩不同。"]', '["軍城臨漢水，旌斾起春风。","远思见江草，归心看塞鴻。","野花沿古道，新葉映行宮。","惟有诗兼酒，朝朝兩不同。"]', '诗', 'shi', '', NULL, '令狐相公頻示新什早春南望遐想漢中因抒短章以寄情愫 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7b793a-4237-41b6-b357-b3448d6f37ac', '和令狐相公詠梔子花', '和令狐相公詠梔子花', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蜀國花已盡，越桃今已開。","色疑瓊樹倚，香似玉京來。","且賞同心處，那憂別葉催。","佳人如擬詠，何必待寒梅。"]', '["蜀国花已尽，越桃今已开。","色疑瓊樹倚，香似玉京来。","且賞同心处，那憂別葉催。","佳人如擬詠，何必待寒梅。"]', '诗', 'shi', '', NULL, '和令狐相公詠梔子花 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918f6ea4-5bec-49fb-ab5d-5ff4b8971153', '詶令狐相公新蟬見寄', '詶令狐相公新蟬见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["相去三千里，聞蟬同此時。","清吟曉露葉，愁噪夕陽枝。","忽爾弦斷絕，俄聞管參差。","洛橋碧雲晚，西望佳人期。"]', '["相去三千里，闻蟬同此时。","清吟晓露葉，愁噪夕陽枝。","忽爾弦斷絕，俄闻管參差。","洛橋碧云晚，西望佳人期。"]', '诗', 'shi', '', NULL, '詶令狐相公新蟬見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df15aeb6-d2f4-47a9-a294-fc080f860c03', '詶樂天閑臥見寄', '詶乐天闲臥见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["散誕向陽眠，將閑敵地仙。","詩情茶助爽，藥力酒能宣。","風碎竹間日，露明池底天。","同年未同隱，緣欠買山錢。"]', '["散誕向陽眠，將闲敵地仙。","诗情茶助爽，藥力酒能宣。","风碎竹间日，露明池底天。","同年未同隐，緣欠買山錢。"]', '诗', 'shi', '', NULL, '詶樂天閑臥見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fae33d9-b8de-436c-a742-b769de12af9a', '詶樂天小亭寒夜有懷', '詶乐天小亭寒夜有懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寒夜陰雲起，疎林宿鳥驚。","斜風閃燈影，迸雪打窗聲。","竟夕不能寐，同年知此情。","漢皇無奈老，何況本書生。"]', '["寒夜陰云起，疎林宿鸟驚。","斜风閃灯影，迸雪打窗声。","竟夕不能寐，同年知此情。","漢皇無奈老，何況本书生。"]', '诗', 'shi', '', NULL, '詶樂天小亭寒夜有懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929aa3d8-e82f-4905-81fa-2842256e9863', '將之官留辭裴令公留守', '將之官留辞裴令公留守', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["祖帳臨伊水，前旌指渭河。","風煙里數少，雲雨別情多。","重疊受恩久，邅回如命何。","東山與東閣，終異再經過。"]', '["祖帳臨伊水，前旌指渭河。","风煙里數少，云雨別情多。","重叠受恩久，邅回如命何。","东山與东閣，終異再經過。"]', '诗', 'shi', '', NULL, '將之官留辭裴令公留守 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('946dc59e-313f-4094-80e1-4edd39a8215f', '詶喜相遇同州與樂天替代', '詶喜相遇同州與乐天替代', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["舊託松心契，新交竹使符。","行年同甲子，筋力羨丁夫。","別後詩成帙，攜來酒滿壺。","今朝停五馬，不獨爲羅敷。"]', '["旧託松心契，新交竹使符。","行年同甲子，筋力羨丁夫。","別後诗成帙，携来酒满壺。","今朝停五马，不独爲羅敷。"]', '诗', 'shi', '', NULL, '詶喜相遇同州與樂天替代 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664a1587-6f6d-4d23-aa2b-14193018d5a3', '閒坐憶樂天以詩問酒熟未', '閒坐憶乐天以诗问酒熟未', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["案頭開縹帙，肘後檢青囊。","唯有達生理，應無治老方。","減書存眼力，省事養心王。","君酒何時熟，相攜入醉鄉。"]', '["案头开縹帙，肘後檢青囊。","唯有達生理，應無治老方。","減书存眼力，省事養心王。","君酒何时熟，相携入醉乡。"]', '诗', 'shi', '', NULL, '閒坐憶樂天以詩問酒熟未 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7037f3d3-652f-48d9-ba29-dd44893ea77e', '秋中暑退贈樂天', '秋中暑退贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暑服宜秋著，清琴入夜彈。","人情皆向菊，風意欲摧蘭。","歲稔貧心泰，天涼病體安。","相逢取次第，却甚少年歡。"]', '["暑服宜秋著，清琴入夜彈。","人情皆向菊，风意欲摧蘭。","歲稔貧心泰，天涼病體安。","相逢取次第，却甚少年歡。"]', '诗', 'shi', '', NULL, '秋中暑退贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a96850c-2e49-4c26-879d-a84eae5d8b9e', '樂天池館夏景方妍白蓮初開綵舟空泊唯邀緇侶因以戲之', '乐天池館夏景方妍白蓮初开綵舟空泊唯邀緇侶因以戲之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["池館今正好，主人何寂然。","白蓮方出水，碧樹未鳴蟬。","靜室宵聞磬，齋廚晚絕煙。","蕃僧如共載，應不是神仙。"]', '["池館今正好，主人何寂然。","白蓮方出水，碧樹未鳴蟬。","静室宵闻磬，斋廚晚絕煙。","蕃僧如共載，應不是神仙。"]', '诗', 'shi', '', NULL, '樂天池館夏景方妍白蓮初開綵舟空泊唯邀緇侶因以戲之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('207b8904-f16a-48db-84db-6659d74aa2f7', '詶樂天感秋涼見寄', '詶乐天感秋涼见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["庭晚初辨色，林秋微有聲。","槿衰猶強笑，蓮逈却多情。","簷燕歸心動，韝鷹俊氣生。","閑人占閑景，酒熟且同傾。"]', '["庭晚初辨色，林秋微有声。","槿衰猶強笑，蓮逈却多情。","簷燕归心动，韝鷹俊氣生。","闲人占闲景，酒熟且同傾。"]', '诗', 'shi', '', NULL, '詶樂天感秋涼見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e34f769-0796-4076-a958-9a10f3962202', '秋晚新晴夜月如練有懷樂天', '秋晚新晴夜月如練有懷乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雨歇晚霞明，風調夜景清。","月高微暈散，雲薄細鱗生。","露草百蟲思，秋林千葉聲。","相望一步地，脉脉萬重情。"]', '["雨歇晚霞明，风調夜景清。","月高微暈散，云薄細鱗生。","露草百蟲思，秋林千葉声。","相望一步地，脉脉万重情。"]', '诗', 'shi', '', NULL, '秋晚新晴夜月如練有懷樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3848e473-6f18-469a-be75-1b1cc4dfc9fb', '新秋對月寄樂天', '新秋对月寄乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["月露發光彩，此時方見秋。","夜涼金氣應，天靜火星流。","蛩響偏依井，螢飛直過樓。","相知盡白首，清景復追遊。"]', '["月露發光彩，此时方见秋。","夜涼金氣應，天静火星流。","蛩响偏依井，螢飞直過楼。","相知尽白首，清景复追游。"]', '诗', 'shi', '', NULL, '新秋對月寄樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3934e725-f7e9-4639-9677-0e9abd8fbd0d', '詶樂天小臺晚坐見憶', '詶乐天小台晚坐见憶', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["小臺堪遠望，獨上清秋時。","有酒無人勸，看山秖自知。","幽禽囀新竹，孤蓮落靜池。","高門勿遽掩，好客無前期。"]', '["小台堪远望，独上清秋时。","有酒無人勸，看山秖自知。","幽禽囀新竹，孤蓮落静池。","高门勿遽掩，好客無前期。"]', '诗', 'shi', '', NULL, '詶樂天小臺晚坐見憶 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7108fd3d-d932-4c04-b672-95a23970fee8', '早秋雨後寄樂天', '早秋雨後寄乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["夜雲起河漢，朝雨灑高林。","梧葉先風落，草蟲迎濕吟。","簟涼扇恩薄，室靜琴思深。","且喜炎前別，安能懷寸陰。"]', '["夜云起河漢，朝雨灑高林。","梧葉先风落，草蟲迎濕吟。","簟涼扇恩薄，室静琴思深。","且喜炎前別，安能懷寸陰。"]', '诗', 'shi', '', NULL, '早秋雨後寄樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030c6a82-4216-4e52-b1b8-15b91b764680', '秋晚病中樂天以詩見問力疾奉酬', '秋晚病中乐天以诗见问力疾奉酬', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["耳虛多聽遠，展傳晨雞鳴。","一室背燈臥，中宵掃葉聲。","蘭芳經雨敗，鶴病得秋輕。","肯踏衡門草，唯應是友生。"]', '["耳虛多听远，展傳晨雞鳴。","一室背灯臥，中宵掃葉声。","蘭芳經雨敗，鹤病得秋轻。","肯踏衡门草，唯應是友生。"]', '诗', 'shi', '', NULL, '秋晚病中樂天以詩見問力疾奉酬 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d784de3-ecc1-42d9-889c-404ff5302614', '和樂天燒藥不成命酒獨醉', '和乐天燒藥不成命酒独醉', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九轉欲成就，百神應主持。","嬰啼鼎上去，老貌鏡前悲。","却顧空丹竈，回心向酒巵。","醺然耳熱後，暫似少年時。"]', '["九轉欲成就，百神應主持。","嬰啼鼎上去，老貌镜前悲。","却顧空丹竈，回心向酒巵。","醺然耳熱後，暫似少年时。"]', '诗', 'shi', '', NULL, '和樂天燒藥不成命酒獨醉 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e45aca-6a1a-4cdb-a334-f95d7cbfe76e', '元日樂天見過因舉酒爲賀', '元日乐天见過因舉酒爲賀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漸入有年數，喜逢新歲來。","震方天籟動，寅位帝車回。","門巷掃殘雪，林園驚早梅。","與君同甲子，壽酒讓先杯。"]', '["漸入有年數，喜逢新歲来。","震方天籟动，寅位帝车回。","门巷掃殘雪，林园驚早梅。","與君同甲子，壽酒讓先杯。"]', '诗', 'shi', '', NULL, '元日樂天見過因舉酒爲賀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550bc038-417f-4cb7-b36f-9583aa468185', '詶馬大夫以愚獻通草茇葜酒感通拔二字因而寄別之作', '詶马大夫以愚獻通草茇葜酒感通拔二字因而寄別之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["泥沙難振拔，誰復問窮通。","莫訝提壺贈，家傳枕麴風。","成謠獨酌後，深意片言中。","不進終無已，應須荀令公。"]', '["泥沙难振拔，誰复问窮通。","莫訝提壺贈，家傳枕麴风。","成謠独酌後，深意片言中。","不進終無已，應須荀令公。"]', '诗', 'shi', '', NULL, '詶馬大夫以愚獻通草茇葜酒感通拔二字因而寄別之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc26a82f-14b4-4928-89ed-cc9b47c5b173', '奉和司空裴相公中書即事通簡舊僚之作', '奉和司空裴相公中书即事通簡旧僚之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["譚笑在巖廊，人人盡所長。","儀形見山立，文字動星光。","日運丹青筆，時看赤白囊。","佇聞戎馬息，入賀領鴛行。"]', '["譚笑在巖廊，人人尽所长。","儀形见山立，文字动星光。","日運丹青笔，时看赤白囊。","佇闻戎马息，入賀領鴛行。"]', '诗', 'shi', '', NULL, '奉和司空裴相公中書即事通簡舊僚之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7630b188-5b47-4f80-83cd-7f1066c4b876', '微之鎮武昌中路見寄藍橋懷舊之作悽然繼和兼寄安平', '微之鎮武昌中路见寄藍橋懷旧之作悽然繼和兼寄安平', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日油幢引，他年黃紙追。","同爲三楚客，獨有九霄期。","宿草恨長在，傷禽飛尚遲。","武昌應已到，新柳映紅旗。"]', '["今日油幢引，他年黄紙追。","同爲三楚客，独有九霄期。","宿草恨长在，傷禽飞尚遲。","武昌應已到，新柳映紅旗。"]', '诗', 'shi', '', NULL, '微之鎮武昌中路見寄藍橋懷舊之作悽然繼和兼寄安平 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb83070-1196-4468-8e88-f7076973c04e', '將赴蘇州途出洛陽留守李相公累申宴餞寵行話舊形於篇章謹抒下情以申仰謝', '將赴蘇州途出洛陽留守李相公累申宴餞寵行話旧形於篇章謹抒下情以申仰謝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["歲杪風物動，雪餘宮苑晴。","兔園賓客至，金谷管弦聲。","洛水故人別，吳宮新燕迎。","越郎憂不淺，懷袖有瓊英。"]', '["歲杪风物动，雪餘宮苑晴。","兔园賓客至，金谷管弦声。","洛水故人別，吳宮新燕迎。","越郎憂不淺，懷袖有瓊英。"]', '诗', 'shi', '', NULL, '將赴蘇州途出洛陽留守李相公累申宴餞寵行話舊形於篇章謹抒下情以申仰謝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc87011-6c1e-4b95-9c3b-d905d6210560', '牛相公留守見示城外新墅有溪竹秋月親情多往宿遊恨不得去因成四韻兼簡洛中親故之什兼命同作', '牛相公留守见示城外新墅有溪竹秋月親情多往宿游恨不得去因成四韻兼簡洛中親故之什兼命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["別墅洛城外，月明村野通。","光輝滿地上，絲管發舟中。","堤豔菊花露，島涼松葉風。","高情限清禁，寒漏滴深宮。"]', '["別墅洛城外，月明村野通。","光輝满地上，絲管發舟中。","堤豔菊花露，島涼松葉风。","高情限清禁，寒漏滴深宮。"]', '诗', 'shi', '', NULL, '牛相公留守見示城外新墅有溪竹秋月親情多往宿遊恨不得去因成四韻兼簡洛中親故之什兼命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08df5bb-2624-4182-907c-90bca0177c84', '牛相公林亭雨後偶成', '牛相公林亭雨後偶成', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["飛雨過池閣，浮光生草樹。","新竹開粉奩，初蓮爇香注。","野花無時節，水鳥自來去。","若問知境人，人間第一處。"]', '["飞雨過池閣，浮光生草樹。","新竹开粉奩，初蓮爇香注。","野花無时節，水鸟自来去。","若问知境人，人间第一处。"]', '诗', 'shi', '', NULL, '牛相公林亭雨後偶成 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648e9ce0-1c9e-4fc0-8139-b6284232ae34', '詶滑州李尚書秋日見寄', '詶滑州李尚书秋日见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一入石渠署，三聞宮樹蟬。","丹霄未得路，白髮又添年。","雙節外臺貴，孤簫中禁傳。","徵黃在旦夕，早晚發南燕。"]', '["一入石渠署，三闻宮樹蟬。","丹霄未得路，白髮又添年。","雙節外台貴，孤簫中禁傳。","徵黄在旦夕，早晚發南燕。"]', '诗', 'shi', '', NULL, '詶滑州李尚書秋日見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad03d65-0953-4326-8d85-9e69bb02b4de', '和西川李尚書漢州微月遊房太尉西湖', '和西川李尚书漢州微月游房太尉西湖', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["木落漢川夜，西湖懸玉鈎。","旌旗環水次，舟檝泛中流。","目極想前事，神交如共遊。","瑤琴久已絕，松韻自悲秋。"]', '["木落漢川夜，西湖懸玉鈎。","旌旗环水次，舟檝泛中流。","目極想前事，神交如共游。","瑤琴久已絕，松韻自悲秋。"]', '诗', 'shi', '', NULL, '和西川李尚書漢州微月遊房太尉西湖 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea59950-cccb-4045-9d92-68d5fdecbb74', '和重題', '和重題', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["林端落照盡，湖上遠嵐清。","水榭芝蘭室，仙舟魚鳥情。","人琴久寂寞，煙月若平生。","一泛釣璜處，再吟鏘玉聲。"]', '["林端落照尽，湖上远嵐清。","水榭芝蘭室，仙舟鱼鸟情。","人琴久寂寞，煙月若平生。","一泛釣璜处，再吟鏘玉声。"]', '诗', 'shi', '', NULL, '和重題 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c8d216-301d-46e2-b91c-1d660e31f920', '酬李相公喜歸鄉國自鞏縣夜泛洛水見寄', '酬李相公喜归乡国自鞏縣夜泛洛水见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鞏樹煙月上，清光含碧流。","且無三已色，猶泛五湖州。","鵬息風還起，鳳歸林正秋。","雖攀小山桂，此地不淹留。"]', '["鞏樹煙月上，清光含碧流。","且無三已色，猶泛五湖州。","鵬息风還起，鳳归林正秋。","雖攀小山桂，此地不淹留。"]', '诗', 'shi', '', NULL, '酬李相公喜歸鄉國自鞏縣夜泛洛水見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea737f1-64a6-450b-9fec-1e8dc45a551a', '和李相公平泉潭上喜見初月', '和李相公平泉潭上喜见初月', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["家山見初月，林壑悄無塵。","幽境此何夕，清光如爲人。","潭空破鏡入，風動翠蛾嚬。","會向瑣窗望，追思伊洛濱。"]', '["家山见初月，林壑悄無塵。","幽境此何夕，清光如爲人。","潭空破镜入，风动翠蛾嚬。","會向瑣窗望，追思伊洛濱。"]', '诗', 'shi', '', NULL, '和李相公平泉潭上喜見初月 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d616ff7-6752-47e6-913d-b14d7240724c', '和李相公初歸平泉過龍門南嶺遙望山居即事', '和李相公初归平泉過龙门南嶺遙望山居即事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暫別明庭去，初隨優詔還。","曾爲鵬鳥賦，喜過鑿龍山。","新墅煙火起，野程泉石間。","巖廊人望在，只得片時閑。"]', '["暫別明庭去，初隨優詔還。","曾爲鵬鸟賦，喜過鑿龙山。","新墅煙火起，野程泉石间。","巖廊人望在，只得片时闲。"]', '诗', 'shi', '', NULL, '和李相公初歸平泉過龍門南嶺遙望山居即事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc2ef47-7eb6-4a85-90fd-29bf2499b691', '和李相公以平泉新墅獲方外之名因爲詩以報洛中士君子兼見寄之什', '和李相公以平泉新墅獲方外之名因爲诗以報洛中士君子兼见寄之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["業繼韋平後，家依崑閬間。","恩華辭北第，瀟灑愛東山。","滿室圖書在，入門松菊閑。","垂天雖暫息，一舉出人寰。"]', '["業繼韋平後，家依崑閬间。","恩华辞北第，瀟灑愛东山。","满室圖书在，入门松菊闲。","垂天雖暫息，一舉出人寰。"]', '诗', 'shi', '', NULL, '和李相公以平泉新墅獲方外之名因爲詩以報洛中士君子兼見寄之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e33f2321-34c7-4328-99cc-99e0ad299663', '發蘇州後登武丘寺望海樓', '發蘇州後登武丘寺望海楼', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["獨宿望海樓，夜深珍木冷。","僧房已閉戶，山月方出嶺。","碧池涵劒彩，寶剎搖星影。","却憶郡齋中，虛眠此時景。"]', '["独宿望海楼，夜深珍木冷。","僧房已閉戶，山月方出嶺。","碧池涵劒彩，寶剎搖星影。","却憶郡斋中，虛眠此时景。"]', '诗', 'shi', '', NULL, '發蘇州後登武丘寺望海樓 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ae1987-b0e2-4b19-a5c0-4357d11b1d4b', '松江送處州奚使君', '松江送处州奚使君', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吳越古今路，滄波朝夕流。","從來別離地，能使管弦愁。","江草帶煙暮，海雲含雨秋。","知君五陵客，不樂石門遊。"]', '["吳越古今路，滄波朝夕流。","從来別離地，能使管弦愁。","江草带煙暮，海云含雨秋。","知君五陵客，不乐石门游。"]', '诗', 'shi', '', NULL, '松江送處州奚使君 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7532cc0-cfc6-45f3-bc59-19fd20dae9fa', '題報恩寺', '題報恩寺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雲外支硎寺，名聲敵虎丘。","石文留馬跡，峰勢聳牛頭。","泉眼潛通海，松門預帶秋。","遲回好風景，王謝昔曾遊。"]', '["云外支硎寺，名声敵虎丘。","石文留马跡，峰勢聳牛头。","泉眼潛通海，松门預带秋。","遲回好风景，王謝昔曾游。"]', '诗', 'shi', '', NULL, '題報恩寺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc554bf-3f39-417a-8dfc-13df26ea897d', '罷郡姑蘇北歸渡楊子津 一', '罷郡姑蘇北归渡楊子津 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["幾歲悲南國，今朝賦北征。","歸心渡江勇，病體得秋輕。","海闊石門小，城高粉堞明。","金山舊遊寺，過岸聽鐘聲。"]', '["幾歲悲南国，今朝賦北征。","归心渡江勇，病體得秋轻。","海闊石门小，城高粉堞明。","金山旧游寺，過岸听鐘声。"]', '诗', 'shi', '', NULL, '罷郡姑蘇北歸渡楊子津 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504c8b34-934f-4cf4-825e-7c21367cc600', '罷郡姑蘇北歸渡楊子津 二', '罷郡姑蘇北归渡楊子津 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["故國荒臺在，前臨震澤波。","綺羅隨世盡，麋鹿古時多。","築用金鎚力，摧因石鼠窠。","昔年雕輦路，唯有采樵歌。"]', '["故国荒台在，前臨震澤波。","綺羅隨世尽，麋鹿古时多。","築用金鎚力，摧因石鼠窠。","昔年雕輦路，唯有采樵歌。"]', '诗', 'shi', '', NULL, '罷郡姑蘇北歸渡楊子津 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b14970ed-be35-4978-a51a-2d7b2d2b1e0f', '尋汪道士不遇', '尋汪道士不遇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["仙子東南秀，泠然善馭風。","笙歌五雲裏，天地一壺中。","受籙金華洞，焚香玉帝宮。","我來君閉戶，應是向崆峒。"]', '["仙子东南秀，泠然善馭风。","笙歌五云裏，天地一壺中。","受籙金华洞，焚香玉帝宮。","我来君閉戶，應是向崆峒。"]', '诗', 'shi', '', NULL, '尋汪道士不遇 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbcc4fc7-4bd6-4797-8c43-9fecb5e3d344', '謝柳子厚寄疊石硯', '謝柳子厚寄叠石硯', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["常時同硯席，寄硯感離羣。","清越敲寒玉，參差疊碧雲。","烟嵐馀斐亹，水墨兩氛氳。","好與陶貞白，松窻寫紫文。"]', '["常时同硯席，寄硯感離羣。","清越敲寒玉，參差叠碧云。","烟嵐馀斐亹，水墨兩氛氳。","好與陶貞白，松窻寫紫文。"]', '诗', 'shi', '', NULL, '謝柳子厚寄疊石硯 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612e9207-ea91-44c1-aa45-1eeae0285734', '元日感懷', '元日感懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["振蟄春潛至，湘南人未歸。","身加一日長，心覺去年非。","燎火委虛燼，兒童衒彩衣。","異鄉無舊識，車馬到門稀。"]', '["振蟄春潛至，湘南人未归。","身加一日长，心覺去年非。","燎火委虛燼，兒童衒彩衣。","異乡無旧識，车马到门稀。"]', '诗', 'shi', '', NULL, '元日感懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960c39b7-c199-40df-8d25-e782c8a7b85b', '謝宣州崔相公賜馬', '謝宣州崔相公賜马', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["浮雲金絡膝，昨日別朱輪。","銜草如懷戀，嘶風尚意頻。","曾將此君子，不是換佳人。","從此西歸路，應容躡後塵。"]', '["浮云金絡膝，昨日別朱輪。","銜草如懷戀，嘶风尚意頻。","曾將此君子，不是換佳人。","從此西归路，應容躡後塵。"]', '诗', 'shi', '', NULL, '謝宣州崔相公賜馬 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc74e687-ef60-4bba-a32c-2563eb75dab6', '南中書來', '南中书来', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["君書問風俗，此地接炎州。","淫祀多青鬼，居人少白頭。","旅情偏在夜，鄉思豈唯秋。","每羨朝宗水，門前盡日流。"]', '["君书问风俗，此地接炎州。","淫祀多青鬼，居人少白头。","旅情偏在夜，乡思豈唯秋。","每羨朝宗水，门前尽日流。"]', '诗', 'shi', '', NULL, '南中書來 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e89e85-382e-46c4-9fa8-f7e49bd13d8f', '題招隱寺', '題招隐寺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["隱士遺塵在，高僧精舍開。","地形臨渚斷，江勢觸山回。","楚野花多思，南禽聲例哀。","殷勤最高頂，閑即望鄉來。"]', '["隐士遺塵在，高僧精舍开。","地形臨渚斷，江勢觸山回。","楚野花多思，南禽声例哀。","殷勤最高頂，闲即望乡来。"]', '诗', 'shi', '', NULL, '題招隱寺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae3b53e-bcc3-4734-b9d1-3db497fff9c7', '思歸寄山中友人', '思归寄山中友人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蕭條對秋色，相憶在雲泉。","木落病身死，潮平歸思懸。","涼鐘山頂寺，暝火渡頭船。","此地非吾土，閑留又一年。"]', '["蕭條对秋色，相憶在云泉。","木落病身死，潮平归思懸。","涼鐘山頂寺，暝火渡头船。","此地非吾土，闲留又一年。"]', '诗', 'shi', '', NULL, '思歸寄山中友人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee01859-bb0e-4169-8606-97d76c221205', '有感', '有感', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["死且不自覺，其餘安可論。","昨宵鳳池客，今日雀羅門。","騎吏塵未息，銘旌風已翻。","平生紅粉愛，惟解哭黃昏。"]', '["死且不自覺，其餘安可論。","昨宵鳳池客，今日雀羅门。","騎吏塵未息，銘旌风已翻。","平生紅粉愛，惟解哭黄昏。"]', '诗', 'shi', '', NULL, '有感 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('439a098e-5c3d-4b0d-a1d1-c1805d631c28', '途次敷水驛伏覩華州舅氏昔日行縣題詩處潸然有感', '途次敷水驛伏覩华州舅氏昔日行縣題诗处潸然有感', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔日股肱守，朱輪茲地遊。","繁華日已謝，章句此空留。","蔓草佳城閉，故林棠樹秋。","今來重垂淚，不忍過西州。"]', '["昔日股肱守，朱輪茲地游。","繁华日已謝，章句此空留。","蔓草佳城閉，故林棠樹秋。","今来重垂泪，不忍過西州。"]', '诗', 'shi', '', NULL, '途次敷水驛伏覩華州舅氏昔日行縣題詩處潸然有感 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b24c2da-6ef2-4bd7-860f-73eace37d8be', '奉和鄭相公以考功十弟山薑花俯賜篇詠', '奉和鄭相公以考功十弟山薑花俯賜篇詠', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["採擷黃薑蘂，封題青瑣闈。","共聞調膳日，正是退朝歸。","響爲纖筵發，情隨綵翰飛。","故將天下寶，萬里與光輝。"]', '["採擷黄薑蘂，封題青瑣闈。","共闻調膳日，正是退朝归。","响爲纖筵發，情隨綵翰飞。","故將天下寶，万里與光輝。"]', '诗', 'shi', '', NULL, '奉和鄭相公以考功十弟山薑花俯賜篇詠 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7364c048-390a-4738-8531-784ad5f1214e', '題淳于髠墓', '題淳于髠墓', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["生爲齊贅壻，死作楚先賢。","應以客卿葬，故臨官道邊。","寓言本多興，放意能合權。","我有一石酒，置君墳樹前。"]', '["生爲齊贅壻，死作楚先賢。","應以客卿葬，故臨官道邊。","寓言本多兴，放意能合權。","我有一石酒，置君墳樹前。"]', '诗', 'shi', '', NULL, '題淳于髠墓 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67c329e-9b04-4df6-8da3-e1dcdcf0a7df', '送春詞', '送春词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昨來樓上迎春處，今日登樓又送歸。","蘭蘂殘妝含露泣，柳條長袖向風揮。","佳人對鏡容顏改，楚客臨江心事違。","萬古至今同此恨，無如一醉盡忘機。"]', '["昨来楼上迎春处，今日登楼又送归。","蘭蘂殘妝含露泣，柳條长袖向风揮。","佳人对镜容顏改，楚客臨江心事違。","万古至今同此恨，無如一醉尽忘機。"]', '诗', 'shi', '', NULL, '送春詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c193c7-8a99-4873-a2a6-7511c329a47c', '送李尚書鎮滑州', '送李尚书鎮滑州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南徐報政入文昌，東郡須才別建章。","視草名高同蜀客，擁旄年少勝荀郎。","黃河一曲當城下，緹騎千重照路傍。","自古相門還出相，如今人望在巖廊。"]', '["南徐報政入文昌，东郡須才別建章。","視草名高同蜀客，擁旄年少勝荀郎。","黄河一曲當城下，緹騎千重照路傍。","自古相门還出相，如今人望在巖廊。"]', '诗', 'shi', '', NULL, '送李尚書鎮滑州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98df5092-0327-4427-a188-19cc9decf46a', '送渾大夫赴豐州', '送渾大夫赴豐州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳銜新詔降恩華，又見旌旗出渾家。","故吏來辭辛屬國，精兵願逐李輕車。","氈裘君長迎風馭，錦帶酋豪踏雪衙。","其奈明年好春日，無人喚看牡丹花。"]', '["鳳銜新詔降恩华，又见旌旗出渾家。","故吏来辞辛屬国，精兵願逐李轻车。","氈裘君长迎风馭，錦带酋豪踏雪衙。","其奈明年好春日，無人喚看牡丹花。"]', '诗', 'shi', '', NULL, '送渾大夫赴豐州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebfb8a6-9d9f-4150-bd83-ee21e72141c4', '送源中丞充新羅冊立使', '送源中丞充新羅冊立使', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["相門才子稱華簪，持節東行捧德音。","身帶霜威辭鳳闕，口傳天語到雞林。","煙開鰲背千尋碧，日浴鯨波萬頃金。","想見扶桑受恩處，一時西拜盡傾心。"]', '["相门才子稱华簪，持節东行捧德音。","身带霜威辞鳳闕，口傳天語到雞林。","煙开鰲背千尋碧，日浴鯨波万頃金。","想见扶桑受恩处，一时西拜尽傾心。"]', '诗', 'shi', '', NULL, '送源中丞充新羅冊立使 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77c5ac8-e977-4729-b491-8399d1702c86', '送王司馬之陝州', '送王司马之陝州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暫輟清齋出太常，空攜詩卷赴甘棠。","府公既有朝中舊，司馬應容酒後狂。","案牘來時唯署字，風煙入興便成章。","兩京大道多遊客，每遇詞人戰一場。"]', '["暫輟清斋出太常，空携诗卷赴甘棠。","府公既有朝中旧，司马應容酒後狂。","案牘来时唯署字，风煙入兴便成章。","兩京大道多游客，每遇词人戰一場。"]', '诗', 'shi', '', NULL, '送王司馬之陝州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a848fe-755b-4938-81e5-9fa442d45d35', '洛中送楊處厚入關便遊蜀', '洛中送楊处厚入关便游蜀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛陽秋日正淒淒，君去西秦更向西。","舊學三冬今轉富，曾傷六翮養初齊。","王城曉入窺丹鳳，蜀路晴來見碧雞。","早識臥龍應有分，不妨從此躡丹梯。"]', '["洛陽秋日正淒淒，君去西秦更向西。","旧学三冬今轉富，曾傷六翮養初齊。","王城晓入窺丹鳳，蜀路晴来见碧雞。","早識臥龙應有分，不妨從此躡丹梯。"]', '诗', 'shi', '', NULL, '洛中送楊處厚入關便遊蜀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6806f014-1b0c-45a7-a647-684b3a42a7ab', '送周使君罷渝州歸郢州別墅', '送周使君罷渝州归郢州別墅', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["君思郢上吟歸去，故自渝南擲郡章。","野戍岸邊留畫舸，綠蘿陰下到山莊。","池荷雨後依香起，庭草春深綬帶長。","只恐鳴騶催上道，不容待得晚菘嘗。"]', '["君思郢上吟归去，故自渝南擲郡章。","野戍岸邊留畫舸，綠蘿陰下到山莊。","池荷雨後依香起，庭草春深綬带长。","只恐鳴騶催上道，不容待得晚菘嘗。"]', '诗', 'shi', '', NULL, '送周使君罷渝州歸郢州別墅 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68febad0-9314-4bea-b54b-45487325eba4', '奉送浙西李僕射相公赴鎮', '奉送浙西李僕射相公赴鎮', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["建節東行是舊遊，歡聲喜氣滿吳州。","郡人重得黃丞相，童子爭迎郭細侯。","詔下初辭溫室樹，夢中先到景陽樓。","自憐不識平津閣，遙望旌旗汝水頭。"]', '["建節东行是旧游，歡声喜氣满吳州。","郡人重得黄丞相，童子爭迎郭細侯。","詔下初辞溫室樹，梦中先到景陽楼。","自怜不識平津閣，遙望旌旗汝水头。"]', '诗', 'shi', '', NULL, '奉送浙西李僕射相公赴鎮 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77827c6e-9ac8-4050-8a45-0bfcfe22948d', '重送浙西李相公頃廉問江南已經七載後歴滑臺劍南兩鎮遂入相今復領舊地新加旌旄', '重送浙西李相公頃廉问江南已經七載後歴滑台劍南兩鎮遂入相今复領旧地新加旌旄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江北萬人看玉節，江南千騎引金鐃。","鳳從池上遊滄海，鶴到遼東識舊巢。","城下清波含百谷，窻中遠岫列三茅。","碧雞白馬回翔久，却憶朱方是樂郊。"]', '["江北万人看玉節，江南千騎引金鐃。","鳳從池上游滄海，鹤到遼东識旧巢。","城下清波含百谷，窻中远岫列三茅。","碧雞白马回翔久，却憶朱方是乐郊。"]', '诗', 'shi', '', NULL, '重送浙西李相公頃廉問江南已經七載後歴滑臺劍南兩鎮遂入相今復領舊地新加旌旄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad9f94e9-3bfc-4ef1-912c-efd6fe4b7567', '送前進士蔡京赴學究科', '送前進士蔡京赴学究科', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["耳聞戰鼓帶經鋤，振發聲名自里閭。","已是世間能賦客，更攻窻下絕編書。","朱門達者誰能識，絳帳書生盡不如。","幸遇天官舊丞相，知君無翼上空虛。"]', '["耳闻戰鼓带經鋤，振發声名自里閭。","已是世间能賦客，更攻窻下絕編书。","朱门達者誰能識，絳帳书生尽不如。","幸遇天官旧丞相，知君無翼上空虛。"]', '诗', 'shi', '', NULL, '送前進士蔡京赴學究科 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246a2fc7-2c76-4d6d-93ba-86e6ff082352', '送唐舍人出鎮閩中', '送唐舍人出鎮閩中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暫辭鴛鷺出蓬瀛，忽擁貔貅鎮粤城。","閩嶺夏雲迎皂蓋，建溪秋樹映紅旌。","山川遠地由來好，富貴當年別有情。","了却人間婚嫁事，復歸朝右作公卿。"]', '["暫辞鴛鷺出蓬瀛，忽擁貔貅鎮粤城。","閩嶺夏云迎皂蓋，建溪秋樹映紅旌。","山川远地由来好，富貴當年別有情。","了却人间婚嫁事，复归朝右作公卿。"]', '诗', 'shi', '', NULL, '送唐舍人出鎮閩中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be954dd8-282b-4452-8240-6869382e5008', '送李中丞赴楚州', '送李中丞赴楚州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["緹騎朱旗入楚城，士林皆賀振家聲。","兒童但喜迎賓守，故吏猶應記姓名。","萬頃水田連郭秀，四時烟月映淮清。","憶君初得崑山玉，同向揚州攜手行。"]', '["緹騎朱旗入楚城，士林皆賀振家声。","兒童但喜迎賓守，故吏猶應記姓名。","万頃水田連郭秀，四时烟月映淮清。","憶君初得崑山玉，同向揚州携手行。"]', '诗', 'shi', '', NULL, '送李中丞赴楚州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf11f65-5c4a-43d7-96e1-8e48646e9475', '奉送李戶部侍郎自河南尹再除本官歸闕', '奉送李戶部侍郎自河南尹再除本官归闕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔年內署振雄詞，今日東都結去思。","宮女猶傳洞簫賦，國人先詠衮衣詩。","華星却復文昌位，別鶴重歸太乙池。","想到金閨待通籍，一時驚喜見風儀。"]', '["昔年內署振雄词，今日东都結去思。","宮女猶傳洞簫賦，国人先詠衮衣诗。","华星却复文昌位，別鹤重归太乙池。","想到金閨待通籍，一时驚喜见风儀。"]', '诗', 'shi', '', NULL, '奉送李戶部侍郎自河南尹再除本官歸闕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10e5d9aa-2a60-41f7-897a-1e4fd193492e', '送蘄州李郎中赴任', '送蘄州李郎中赴任', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚關蘄水路非賒，東望雲山日夕佳。","薤葉照人呈夏簟，松花滿盌試新茶。","樓中飲興因明月，江上詩情爲晚霞。","北地交親長引領，早將玄鬢到京華。"]', '["楚关蘄水路非賒，东望云山日夕佳。","薤葉照人呈夏簟，松花满盌試新茶。","楼中饮兴因明月，江上诗情爲晚霞。","北地交親长引領，早將玄鬢到京华。"]', '诗', 'shi', '', NULL, '送蘄州李郎中赴任 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c50738-bff4-41a3-b593-f22cc276a159', '送國子令狐博士赴興元覲省', '送国子令狐博士赴兴元覲省', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["相門才子高陽族，學省清資五品官。","諫院過時榮棣萼，謝庭歸去踏芝蘭。","山中花帶煙嵐晚，棧底江涵雪水寒。","伯仲到家人盡賀，柳營蓮府遞相歡。"]', '["相门才子高陽族，学省清資五品官。","諫院過时榮棣萼，謝庭归去踏芝蘭。","山中花带煙嵐晚，棧底江涵雪水寒。","伯仲到家人尽賀，柳營蓮府遞相歡。"]', '诗', 'shi', '', NULL, '送國子令狐博士赴興元覲省 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e364378d-e457-45b4-80c5-e76d755915a7', '送李二十九兄員外赴邠寧使幕', '送李二十九兄員外赴邠寧使幕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["家襲韋平身業文，素風清白至今貧。","南宮通籍新郎吏，西候從戎舊主人。","城外草黃秋有雪，烽頭煙靜虜無塵。","鼎門爲別霜天曉，賸把離殤三五巡。"]', '["家襲韋平身業文，素风清白至今貧。","南宮通籍新郎吏，西候從戎旧主人。","城外草黄秋有雪，烽头煙静虜無塵。","鼎门爲別霜天晓，賸把離殤三五巡。"]', '诗', 'shi', '', NULL, '送李二十九兄員外赴邠寧使幕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1e406b-2674-4099-8478-d8e9ac756c6c', '送分司陳郎中秖召直史館重修三聖實録', '送分司陳郎中秖召直史館重修三聖實録', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蟬鳴官樹引行車，言自成周赴玉除。","遠取南朝貴公子，重修東觀帝王書。","常時載筆窺金匱，暇日登樓到石渠。","若問舊人劉子政，如今白首在南徐。"]', '["蟬鳴官樹引行车，言自成周赴玉除。","远取南朝貴公子，重修东观帝王书。","常时載笔窺金匱，暇日登楼到石渠。","若问旧人劉子政，如今白首在南徐。"]', '诗', 'shi', '', NULL, '送分司陳郎中秖召直史館重修三聖實録 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd10dd8-c113-4f6f-a304-bcb500230553', '送慧則法師歸上都因呈廣宣上人', '送慧則法師归上都因呈廣宣上人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昨日東林看講時，都人象馬蹋琉璃。","雪山童子應前世，金粟如來是本師。","一錫言歸九城路，三衣曾拂萬年枝。","休公久別如相問，楚客逢秋心更悲。"]', '["昨日东林看講时，都人象马蹋琉璃。","雪山童子應前世，金粟如来是本師。","一錫言归九城路，三衣曾拂万年枝。","休公久別如相问，楚客逢秋心更悲。"]', '诗', 'shi', '', NULL, '送慧則法師歸上都因呈廣宣上人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef50bf2-b4d2-4dce-b23a-188cd3b1d920', '送義舟師却還黔南', '送義舟師却還黔南', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["黔江秋水浸雲霓，獨泛慈航路不迷。","猨狖窺齋林葉動，蛟龍聞咒浪花低。","如蓮半偈心常悟，問菊新詩手自攜。","常說摩圍似靈鷲，却將山屐上丹梯。"]', '["黔江秋水浸云霓，独泛慈航路不迷。","猨狖窺斋林葉动，蛟龙闻咒浪花低。","如蓮半偈心常悟，问菊新诗手自携。","常说摩圍似靈鷲，却將山屐上丹梯。"]', '诗', 'shi', '', NULL, '送義舟師却還黔南 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616a784a-d942-4cf1-b0b3-9a2f98cfad8f', '送景玄師東歸', '送景玄師东归', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["東林寺裏一沙彌，心愛當時才子詩。","山下偶隨流水出，秋來却赴白雲期。","灘頭躡屐挑沙菜，路上停舟讀古碑。","想到舊房拋錫杖，小松應有過簷枝。"]', '["东林寺裏一沙彌，心愛當时才子诗。","山下偶隨流水出，秋来却赴白云期。","灘头躡屐挑沙菜，路上停舟读古碑。","想到旧房拋錫杖，小松應有過簷枝。"]', '诗', 'shi', '', NULL, '送景玄師東歸 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b7f6d9-8bac-4d85-a9bc-ddf7045fa9e7', '漢壽城春望', '漢壽城春望', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢壽城邊野草春，荒祠古墓對荆榛。","田中牧豎燒芻狗，陌上行人看石麟。","華表半空經霹靂，碑文纔見滿埃塵。","不知何日東瀛變，此地還成要路津。"]', '["漢壽城邊野草春，荒祠古墓对荆榛。","田中牧豎燒芻狗，陌上行人看石麟。","华表半空經霹靂，碑文纔见满埃塵。","不知何日东瀛变，此地還成要路津。"]', '诗', 'shi', '', NULL, '漢壽城春望 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e143e7-b869-498b-a5ad-a667674afa5d', '荆門道懷古', '荆门道懷古', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南國山川舊帝畿，宋臺梁館尚依稀。","馬嘶古道行人歇，麥秀空城野雉飛。","風吹落葉填宮井，火入荒陵化寶衣。","徒使詞臣庾開府，咸陽終日苦思歸。"]', '["南国山川旧帝畿，宋台梁館尚依稀。","马嘶古道行人歇，麦秀空城野雉飞。","风吹落葉填宮井，火入荒陵化寶衣。","徒使词臣庾开府，咸陽終日苦思归。"]', '诗', 'shi', '', NULL, '荆門道懷古 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29053389-2e59-46f7-b7c2-5ff91010224b', '朗州竇員外見示與澧州元郎中郡齋贈答長句二篇因以繼和', '朗州竇員外见示與澧州元郎中郡斋贈答长句二篇因以繼和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鴛鷺差池出建章，綵旗朱戶蔚相望。","新恩共理犬牙地，昨日同含雞舌香。","白芷江邊分驛路，山桃蹊外接甘棠。","應憐一罷金閨籍，枉渚逢春十度傷。"]', '["鴛鷺差池出建章，綵旗朱戶蔚相望。","新恩共理犬牙地，昨日同含雞舌香。","白芷江邊分驛路，山桃蹊外接甘棠。","應怜一罷金閨籍，枉渚逢春十度傷。"]', '诗', 'shi', '', NULL, '朗州竇員外見示與澧州元郎中郡齋贈答長句二篇因以繼和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519a0538-e33a-48a5-bb44-85000b3a5c5f', '早春對雪奉寄澧州元郎中', '早春对雪奉寄澧州元郎中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新賜魚書墨未乾，賢人暫出遠人安。","朝驅旌斾行時令，夜見星辰憶舊官。","梅蘂覆堦鈴閣暖，雪峰當戶戟枝寒。","寧知楚客思公子，北望長吟澧有蘭。"]', '["新賜鱼书墨未乾，賢人暫出远人安。","朝驱旌斾行时令，夜见星辰憶旧官。","梅蘂覆堦鈴閣暖，雪峰當戶戟枝寒。","寧知楚客思公子，北望长吟澧有蘭。"]', '诗', 'shi', '', NULL, '早春對雪奉寄澧州元郎中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc8c4c3-b3a0-459b-a497-3b0f2ecfed57', '竇朗州見示與澧州元郎中早秋贈荅命同作', '竇朗州见示與澧州元郎中早秋贈荅命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鄰境諸侯同舍郎，芷江蘭浦恨無梁。","秋風門外旌旗動，曉露庭中橘柚香。","玉簟微涼宜白晝，金笳入暮應清商。","騷人昨夜聞鶗鴂，不歎流年惜衆芳。"]', '["鄰境諸侯同舍郎，芷江蘭浦恨無梁。","秋风门外旌旗动，晓露庭中橘柚香。","玉簟微涼宜白晝，金笳入暮應清商。","騷人昨夜闻鶗鴂，不歎流年惜衆芳。"]', '诗', 'shi', '', NULL, '竇朗州見示與澧州元郎中早秋贈荅命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b235d33a-c1c9-4009-b479-1491a607d9ab', '松滋渡望峽中', '松滋渡望峽中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["渡頭輕雨灑寒梅，雲際溶溶雪水來。","夢渚草長迷楚望，夷陵土黑有秦灰。","巴人淚應猿聲落，蜀客船從鳥道回。","十二碧峰何處所，永安宮外是荒臺。"]', '["渡头轻雨灑寒梅，云際溶溶雪水来。","梦渚草长迷楚望，夷陵土黑有秦灰。","巴人泪應猿声落，蜀客船從鸟道回。","十二碧峰何处所，永安宮外是荒台。"]', '诗', 'shi', '', NULL, '松滋渡望峽中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70bbc60-e7da-4754-b41f-35a8f9582596', '衢州徐員外使君遺以縞紵兼竹書箱因成一篇用答佳貺', '衢州徐員外使君遺以縞紵兼竹书箱因成一篇用答佳貺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["爛柯山下舊仙郎，列宿來添婺女光。","遠放歌聲分白紵，知傳家學與青箱。","水朝滄海何時去，蘭在幽林亦自芳。","聞說天台有遺愛，人將琪樹比甘棠。"]', '["爛柯山下旧仙郎，列宿来添婺女光。","远放歌声分白紵，知傳家学與青箱。","水朝滄海何时去，蘭在幽林亦自芳。","闻说天台有遺愛，人將琪樹比甘棠。"]', '诗', 'shi', '', NULL, '衢州徐員外使君遺以縞紵兼竹書箱因成一篇用答佳貺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db3331a-9825-49c5-8400-ea554a91180e', '唐秀才贈端州紫石硯以詩答之', '唐秀才贈端州紫石硯以诗答之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["端州石硯人間重，贈我因知正草玄。","闕里廟堂空舊物，開方竈下豈天然。","玉蜍吐水霞光靜，綵翰搖風絳錦鮮。","此日傭工記名姓，因君數到墨池前。"]', '["端州石硯人间重，贈我因知正草玄。","闕里廟堂空旧物，开方竈下豈天然。","玉蜍吐水霞光静，綵翰搖风絳錦鲜。","此日傭工記名姓，因君數到墨池前。"]', '诗', 'shi', '', NULL, '唐秀才贈端州紫石硯以詩答之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33c6012b-f14a-46e8-a869-8ed41271c3a1', '覽董評事思歸之什因以詩贈', '覽董評事思归之什因以诗贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["幾年油幕佐征東，却泛滄浪狎釣童。","欹枕醉眠成戲蝶，抱琴閑望送歸鴻。","文儒自襲膠西相，倚伏能齊塞上翁。","更說扁舟動鄉思，青菰已熟奈秋風。"]', '["幾年油幕佐征东，却泛滄浪狎釣童。","欹枕醉眠成戲蝶，抱琴闲望送归鴻。","文儒自襲膠西相，倚伏能齊塞上翁。","更说扁舟动乡思，青菰已熟奈秋风。"]', '诗', 'shi', '', NULL, '覽董評事思歸之什因以詩贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1b6fde-6b08-458a-89d9-81676dcd6adb', '謝寺雙檜', '謝寺雙檜', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雙檜蒼然古貌奇，含煙吐霧鬱參差。","晚依禪客當金殿，初對將軍映畫旗。","龍象界中成寶蓋，鴛鴦瓦上出高枝。","長明燈是前朝焰，曾照青青年少時。"]', '["雙檜蒼然古貌奇，含煙吐霧鬱參差。","晚依禪客當金殿，初对將軍映畫旗。","龙象界中成寶蓋，鴛鴦瓦上出高枝。","长明灯是前朝焰，曾照青青年少时。"]', '诗', 'shi', '', NULL, '謝寺雙檜 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9957348f-3e45-48cb-ac2e-f159fc56a9ba', '寄楊八壽州', '寄楊八壽州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["風獵紅旗入壽春，滿城歌舞向朱輪。","八公山下清淮水，千騎塵中白面人。","桂嶺雨餘多鶴迹，茗園晴望似龍鱗。","聖朝方用敢言者，次第應須舊諫臣。"]', '["风獵紅旗入壽春，满城歌舞向朱輪。","八公山下清淮水，千騎塵中白面人。","桂嶺雨餘多鹤迹，茗园晴望似龙鱗。","聖朝方用敢言者，次第應須旧諫臣。"]', '诗', 'shi', '', NULL, '寄楊八壽州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce9f281-cd32-4689-beb4-5357c715bf54', '洛中寺北樓見賀監草書題詩', '洛中寺北楼见賀監草书題诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高樓賀監昔曾登，壁上筆蹤龍虎騰。","中國書流尚皇象，北朝文士重徐陵。","偶因獨見空驚目，恨不同時便伏膺。","唯恐塵埃轉磨滅，再三珍重囑山僧。"]', '["高楼賀監昔曾登，壁上笔蹤龙虎腾。","中国书流尚皇象，北朝文士重徐陵。","偶因独见空驚目，恨不同时便伏膺。","唯恐塵埃轉磨滅，再三珍重囑山僧。"]', '诗', 'shi', '', NULL, '洛中寺北樓見賀監草書題詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299c9713-fcdd-489e-93b0-24891e497314', '聞韓賓擢第歸覲以詩美之兼賀韓十五曹長時韓牧永州', '闻韓賓擢第归覲以诗美之兼賀韓十五曹长时韓牧永州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["零陵香草滿郊坰，丹穴雛飛入翠屏。","孝若歸來成畫讚，孟陽別後有山銘。","蘭陔舊地花纔結，桂樹新枝色更青。","爲報儒林丈人道，如今從此鬢星星。"]', '["零陵香草满郊坰，丹穴雛飞入翠屏。","孝若归来成畫讚，孟陽別後有山銘。","蘭陔旧地花纔結，桂樹新枝色更青。","爲報儒林丈人道，如今從此鬢星星。"]', '诗', 'shi', '', NULL, '聞韓賓擢第歸覲以詩美之兼賀韓十五曹長時韓牧永州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a3e9fe-ed3b-4150-8d31-cda06d9bfae2', '宣上人遠寄和禮部王侍郎放榜後詩因而繼和', '宣上人远寄和禮部王侍郎放榜後诗因而繼和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["禮闈新榜動長安，九陌人人走馬看。","一日聲名遍天下，滿城桃李屬春官。","自吟白雪詮詞賦，指示青雲借羽翰。","借問至公誰印可，支郎天眼定中觀。"]', '["禮闈新榜动长安，九陌人人走马看。","一日声名遍天下，满城桃李屬春官。","自吟白雪詮词賦，指示青云借羽翰。","借问至公誰印可，支郎天眼定中观。"]', '诗', 'shi', '', NULL, '宣上人遠寄和禮部王侍郎放榜後詩因而繼和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7d146f-7fa2-4507-a7d8-420cdee2aaf2', '贈東嶽張鍊師', '贈东嶽張鍊師', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["東嶽真人張鍊師，高情雅淡世間稀。","堪爲列女書青簡，久事元君住翠微。","金縷機中拋錦字，玉清臺上著霓衣。","雲衢不要吹簫伴，只擬乘鸞獨自飛。"]', '["东嶽真人張鍊師，高情雅淡世间稀。","堪爲列女书青簡，久事元君住翠微。","金縷機中拋錦字，玉清台上著霓衣。","云衢不要吹簫伴，只擬乘鸾独自飞。"]', '诗', 'shi', '', NULL, '贈東嶽張鍊師 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13ae539-59e5-41b2-9271-96901b39efad', '秘書山崔少監見示墜馬長句因而和之', '秘书山崔少監见示墜马长句因而和之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["麟臺少[監]舊仙郎，洛水橋邊墜馬傷。","塵污腰間青襞綬，風飄掌上紫遊韁。","上車著作應來問，折臂三公定送方。","猶賴德全如醉者，不妨吟詠入篇章。"]', '["麟台少[監]旧仙郎，洛水橋邊墜马傷。","塵污腰间青襞綬，风飄掌上紫游韁。","上车著作應来问，折臂三公定送方。","猶賴德全如醉者，不妨吟詠入篇章。"]', '诗', 'shi', '', NULL, '秘書山崔少監見示墜馬長句因而和之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002063b6-841e-48b8-a1d8-292bb68860b0', '寄楊虢州與之舊姻', '寄楊虢州與之旧姻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["避地江湖知幾春，今來本郡擁朱輪。","阮郎無復里中舊，楊僕却爲關外人。","各繫一官難命駕，每懷前好易沾巾。","玉城山裏多靈藥，擺落功名且養神。"]', '["避地江湖知幾春，今来本郡擁朱輪。","阮郎無复里中旧，楊僕却爲关外人。","各繫一官难命駕，每懷前好易沾巾。","玉城山裏多靈藥，擺落功名且養神。"]', '诗', 'shi', '', NULL, '寄楊虢州與之舊姻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2dd846-576c-4d6d-9222-95b21061da58', '秋日題竇員外崇德里新居', '秋日題竇員外崇德里新居', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長愛街西風景閑，到君居處暫開顏。","清光門外一渠水，秋色牆頭數點山。","疎種碧松通月朗，多栽紅藥待春還。","莫言堆案無餘地，認得詩人在此間。"]', '["长愛街西风景闲，到君居处暫开顏。","清光门外一渠水，秋色牆头數点山。","疎種碧松通月朗，多栽紅藥待春還。","莫言堆案無餘地，認得诗人在此间。"]', '诗', 'shi', '', NULL, '秋日題竇員外崇德里新居 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f2c1c8-8a89-46c2-a969-1a140915a270', '蒙恩轉儀曹郎依前充集賢學士舉韓潮州自代因寄七言', '蒙恩轉儀曹郎依前充集賢学士舉韓潮州自代因寄七言', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["翔鸞闕下謝恩初，通籍由來在石渠。","暫入南宮判祥瑞，還歸內殿閱圖書。","故人猶在三江外，同病凡經二紀餘。","今日薦君嗟久滯，不惟文體似相如。"]', '["翔鸾闕下謝恩初，通籍由来在石渠。","暫入南宮判祥瑞，還归內殿閱圖书。","故人猶在三江外，同病凡經二紀餘。","今日薦君嗟久滯，不惟文體似相如。"]', '诗', 'shi', '', NULL, '蒙恩轉儀曹郎依前充集賢學士舉韓潮州自代因寄七言 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f171af4-d334-4709-ae5e-8c4dff073dd7', '途次華州陪錢大夫登城北樓春望因覩李崔令狐三相國唱和之什翰林舊侶繼踵華城山水清高鸞鳳翔集皆忝宿眷遂題此詩', '途次华州陪錢大夫登城北楼春望因覩李崔令狐三相国唱和之什翰林旧侶繼踵华城山水清高鸾鳳翔集皆忝宿眷遂題此诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城樓四望出風塵，見盡關西渭北春。","百二山河雄上國，一雙旌斾委名臣。","壁中今日題詩處，天上同時草詔人。","莫怪老郎呈濫吹，宦途雖別舊情親。"]', '["城楼四望出风塵，见尽关西渭北春。","百二山河雄上国，一雙旌斾委名臣。","壁中今日題诗处，天上同时草詔人。","莫怪老郎呈濫吹，宦途雖別旧情親。"]', '诗', 'shi', '', NULL, '途次華州陪錢大夫登城北樓春望因覩李崔令狐三相國唱和之什翰林舊侶繼踵華城山水清高鸞鳳翔集皆忝宿眷遂題此詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8250a2b0-8b01-477c-b2ec-741ab9639f07', '始聞秋風', '始闻秋风', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔看黃菊與君別，今聽玄蟬我却回。","五夜颼飀枕前覺，一年顏狀鏡中來。","馬思邊草拳毛動，雕眄青雲睡眼開。","天地肅清堪四望，爲君扶病上高臺。"]', '["昔看黄菊與君別，今听玄蟬我却回。","五夜颼飀枕前覺，一年顏狀镜中来。","马思邊草拳毛动，雕眄青云睡眼开。","天地肅清堪四望，爲君扶病上高台。"]', '诗', 'shi', '', NULL, '始聞秋風 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a00cce8-1114-4504-ada3-659321e53036', '洛中初冬拜表有懷上京故人', '洛中初冬拜表有懷上京故人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳樓南面控三條，拜表郎官早渡橋。","清洛曉光鋪碧簟，上陽霜葉剪紅綃。","省門簪組初成列，雲路鴛鸞想退朝。","寄謝慇懃九天侶，搶榆水擊各逍遙。"]', '["鳳楼南面控三條，拜表郎官早渡橋。","清洛晓光鋪碧簟，上陽霜葉剪紅綃。","省门簪組初成列，云路鴛鸾想退朝。","寄謝慇懃九天侶，搶榆水擊各逍遙。"]', '诗', 'shi', '', NULL, '洛中初冬拜表有懷上京故人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7a16f4-2af8-4e2f-b961-c0fb97cea449', '尉遲郎中見示自南遷牽復却至洛城東舊居之作因以和之', '尉遲郎中见示自南遷牽复却至洛城东旧居之作因以和之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾遭飛語十年謫，新受恩光萬里還。","朝服不妨遊洛浦，郊園依舊看嵩山。","竹含天籟清商樂，水遶庭臺碧玉環。","留作功成退身地，如今只是暫時閑。"]', '["曾遭飞語十年謫，新受恩光万里還。","朝服不妨游洛浦，郊园依旧看嵩山。","竹含天籟清商乐，水遶庭台碧玉环。","留作功成退身地，如今只是暫时闲。"]', '诗', 'shi', '', NULL, '尉遲郎中見示自南遷牽復却至洛城東舊居之作因以和之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb62f6d-a038-4cc9-bfad-209e350bc553', '洛中詶福建陳判官見贈', '洛中詶福建陳判官见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["潦倒聲名擁腫材，一生多故苦邅迴。","南宮舊籍遙相管，東洛閑門晝未開。","靜對道流論藥石，偶逢詞客與瓊瑰。","怪君近日文鋒利，新向延平看劒來。"]', '["潦倒声名擁腫材，一生多故苦邅迴。","南宮旧籍遙相管，东洛闲门晝未开。","静对道流論藥石，偶逢词客與瓊瑰。","怪君近日文鋒利，新向延平看劒来。"]', '诗', 'shi', '', NULL, '洛中詶福建陳判官見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b0526c-45fb-4932-b4a7-ebfbc8641ed8', '和蘇十郎中謝病閑居時嚴常侍蕭給事同過訪歎初有二毛之作', '和蘇十郎中謝病闲居时嚴常侍蕭給事同過訪歎初有二毛之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["清羸隱几望雲空，左掖鴛鸞到室中。","一卷素書消永日，數莖斑髪對秋風。","菱花照後容雖改，蓍草占來命已通。","莫怪人人驚早白，緣君尚是黑頭翁。"]', '["清羸隐几望云空，左掖鴛鸾到室中。","一卷素书消永日，數莖斑髪对秋风。","菱花照後容雖改，蓍草占来命已通。","莫怪人人驚早白，緣君尚是黑头翁。"]', '诗', 'shi', '', NULL, '和蘇十郎中謝病閑居時嚴常侍蕭給事同過訪歎初有二毛之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b333c7c-9d52-40ee-bb01-92b0835a5d41', '酬淮南廖參謀秋夕見過之作', '酬淮南廖參謀秋夕见過之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["揚州從事夜相尋，無限新詩月下吟。","初服已驚玄髪長，高情猶向碧雲深。","語餘時舉一杯酒，坐久方聞四處砧。","不逐繁華訪閑散，知君擺落俗人心。"]', '["揚州從事夜相尋，無限新诗月下吟。","初服已驚玄髪长，高情猶向碧云深。","語餘时舉一杯酒，坐久方闻四处砧。","不逐繁华訪闲散，知君擺落俗人心。"]', '诗', 'shi', '', NULL, '酬淮南廖參謀秋夕見過之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec78a65-18c4-42cb-9f6c-2529c1488e20', '題王郎中宣義里新居', '題王郎中宣義里新居', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["愛君新買街西宅，客到如遊鄠杜間。","雨後退朝貪種樹，申時出省趂看山。","門前巷陌三條近，牆內池亭萬境閑。","見擬移居作鄰里，不論時節請開關。"]', '["愛君新買街西宅，客到如游鄠杜间。","雨後退朝貪種樹，申时出省趂看山。","门前巷陌三條近，牆內池亭万境闲。","见擬移居作鄰里，不論时節請开关。"]', '诗', 'shi', '', NULL, '題王郎中宣義里新居 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('969c4162-0ee7-494f-a621-e077143fa371', '酬朗州崔員外與任十四兄侍御同過鄙人舊居見懷之什時守吳郡', '酬朗州崔員外與任十四兄侍御同過鄙人旧居见懷之什时守吳郡', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔日居鄰招屈亭，楓林橘樹鷓鴣聲。","一辭御苑青門去，十見蠻江白芷生。","自此曾沾宣室召，如今又守闔閭城。","何人萬里能相憶，同舍仙郎與外兄。"]', '["昔日居鄰招屈亭，楓林橘樹鷓鴣声。","一辞御苑青门去，十见蠻江白芷生。","自此曾沾宣室召，如今又守闔閭城。","何人万里能相憶，同舍仙郎與外兄。"]', '诗', 'shi', '', NULL, '酬朗州崔員外與任十四兄侍御同過鄙人舊居見懷之什時守吳郡 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef5cd66-b496-4c17-b95a-af9b40cfe940', '劉駙馬水亭避暑', '劉駙马水亭避暑', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["千竿竹翠數蓮紅，水閣虛涼玉簟空。","琥珀琖紅疑漏酒，水晶簾瑩更通風。","賜冰滿盌沈朱實，法饌盈盤覆碧籠。","盡日逍遙避煩暑，再三珍重主人翁。"]', '["千竿竹翠數蓮紅，水閣虛涼玉簟空。","琥珀琖紅疑漏酒，水晶簾瑩更通风。","賜冰满盌沈朱實，法饌盈盤覆碧籠。","尽日逍遙避煩暑，再三珍重主人翁。"]', '诗', 'shi', '', NULL, '劉駙馬水亭避暑 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e289182-9ae3-4f90-ba93-4334c439f2cd', '述舊賀遷寄陝虢孫常侍', '述旧賀遷寄陝虢孫常侍', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南宮幸襲芝蘭後，左輔曾交印綬來。","多病未離清洛苑，新恩已歷望仙臺。","關頭古塞桃林靜，城下長河竹箭回。","聞說隨車有零雨，此時偏動子荆才。"]', '["南宮幸襲芝蘭後，左輔曾交印綬来。","多病未離清洛苑，新恩已歷望仙台。","关头古塞桃林静，城下长河竹箭回。","闻说隨车有零雨，此时偏动子荆才。"]', '诗', 'shi', '', NULL, '述舊賀遷寄陝虢孫常侍 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5403f872-7e74-4c22-b39a-7a94196e9839', '江陵嚴司空見示與成都武相公唱和因命同作', '江陵嚴司空见示與成都武相公唱和因命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南荆西蜀大行臺，幕府旌門相對開。","名重三司平水土，威雄八陣役風雷。","彩雲朝望青城起，錦浪秋經白帝來。","不是郢中清唱發，誰當丞相掞天才。"]', '["南荆西蜀大行台，幕府旌门相对开。","名重三司平水土，威雄八陣役风雷。","彩云朝望青城起，錦浪秋經白帝来。","不是郢中清唱發，誰當丞相掞天才。"]', '诗', 'shi', '', NULL, '江陵嚴司空見示與成都武相公唱和因命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1121aee0-197f-40eb-8046-5c60ab4ac301', '廟庭偃松詩', '廟庭偃松诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["勢軋枝偏根已危，高情一見與扶持。","忽從顦顇有生意，却爲離披無俗姿。","影入巖廊行樂處，韻含天籟宿齋時。","謝公莫道東山去，待取陰成滿鳳池。"]', '["勢軋枝偏根已危，高情一见與扶持。","忽從顦顇有生意，却爲離披無俗姿。","影入巖廊行乐处，韻含天籟宿斋时。","謝公莫道东山去，待取陰成满鳳池。"]', '诗', 'shi', '', NULL, '廟庭偃松詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ccd052-5e40-4a04-9ddc-aaad79a695e0', '贈致仕滕庶子先輩', '贈致仕滕庶子先輩', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朝服歸來晝錦榮，登科記上更無兄。","壽觴每使曾孫獻，勝境長攜衆妓行。","[矍]鑠據鞍時騁健，殷勤把酒尚多情。","凌寒却向山陰去，衣繡郎君雪裏行。"]', '["朝服归来晝錦榮，登科記上更無兄。","壽觴每使曾孫獻，勝境长携衆妓行。","[矍]鑠據鞍时騁健，殷勤把酒尚多情。","凌寒却向山陰去，衣繡郎君雪裏行。"]', '诗', 'shi', '', NULL, '贈致仕滕庶子先輩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e94fa5-3a8a-4b2b-abbb-50d1755ee354', '哭呂衡州時予方謫居', '哭呂衡州时予方謫居', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一夜霜風凋玉芝，蒼生望絕士林悲。","空懷濟世安人略，不見男婚女嫁時。","遺草一函歸太史，旅墳三尺近要離。","朔方徙歲行當滿，欲爲君刊第二碑。"]', '["一夜霜风凋玉芝，蒼生望絕士林悲。","空懷濟世安人略，不见男婚女嫁时。","遺草一函归太史，旅墳三尺近要離。","朔方徙歲行當满，欲爲君刊第二碑。"]', '诗', 'shi', '', NULL, '哭呂衡州時予方謫居 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('080d5239-4ac7-4c20-95b9-b60f78669025', '夔州竇員外使君見示悼妓詩顧余嘗識之因命同作', '夔州竇員外使君见示悼妓诗顧余嘗識之因命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前年曾見兩鬟時，今日驚吟悼妓詩。","鳳管學成知有籍，龍媒欲換歎無期。","空廊月照常行地，後院花開舊折枝。","寂寞魚山青草裏，何人更立智瓊祠。"]', '["前年曾见兩鬟时，今日驚吟悼妓诗。","鳳管学成知有籍，龙媒欲換歎無期。","空廊月照常行地，後院花开旧折枝。","寂寞鱼山青草裏，何人更立智瓊祠。"]', '诗', 'shi', '', NULL, '夔州竇員外使君見示悼妓詩顧余嘗識之因命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085886a9-c80b-4405-87c3-7b95fac67561', '竇夔州見寄寒食日憶故姬小紅吹笙因和之', '竇夔州见寄寒食日憶故姬小紅吹笙因和之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鸞聲窈眇管參差，清韻初調衆樂隨。","幽院妝成花下弄，高樓月好夜深吹。","忽驚暮雨飄零盡，唯有朝雲夢想期。","聞道今年寒食日，東山舊路獨行遲。"]', '["鸾声窈眇管參差，清韻初調衆乐隨。","幽院妝成花下弄，高楼月好夜深吹。","忽驚暮雨飄零尽，唯有朝云梦想期。","闻道今年寒食日，东山旧路独行遲。"]', '诗', 'shi', '', NULL, '竇夔州見寄寒食日憶故姬小紅吹笙因和之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1551eb29-69d8-4057-8238-541627f551b4', '哭龐京兆', '哭龐京兆', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["俊骨英才氣褎然，策名飛步冠羣賢。","逢時已自致高位，得疾還因倚少年。","天上別歸京兆府，人間空數茂陵阡。","今朝穗帳哭君處，前日見鋪歌舞筵。"]', '["俊骨英才氣褎然，策名飞步冠羣賢。","逢时已自致高位，得疾還因倚少年。","天上別归京兆府，人间空數茂陵阡。","今朝穗帳哭君处，前日见鋪歌舞筵。"]', '诗', 'shi', '', NULL, '哭龐京兆 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71536ef1-bcdf-4637-9536-47c2467dfdfa', '送李庚先輩赴選', '送李庚先輩赴選', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一家何啻十朱輪，諸父雙飛秉大鈞。","曾脫素衣參幕客，却爲精舍讀書人。","離筵雒水侵杯色，征路函關向晚塵。","今日山公舊賓主，知君不負帝城春。"]', '["一家何啻十朱輪，諸父雙飞秉大鈞。","曾脫素衣參幕客，却爲精舍读书人。","離筵雒水侵杯色，征路函关向晚塵。","今日山公旧賓主，知君不負帝城春。"]', '诗', 'shi', '', NULL, '送李庚先輩赴選 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e361b2-ef5d-4c55-908b-bccca46c33cc', '陽山廟觀賽神', '陽山廟观賽神', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢家都尉舊征蠻，血食如今配此山。","曲蓋幽深蒼檜下，洞簫愁絕翠屏間。","荆巫脉脉傳神語，野老娑娑起醉顏。","日落風生廟門外，幾人連蹋竹歌還。"]', '["漢家都尉旧征蠻，血食如今配此山。","曲蓋幽深蒼檜下，洞簫愁絕翠屏间。","荆巫脉脉傳神語，野老娑娑起醉顏。","日落风生廟门外，幾人連蹋竹歌還。"]', '诗', 'shi', '', NULL, '陽山廟觀賽神 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c784bb2-ed8b-4421-9b8d-21075fafd808', '送僧元暠東遊', '送僧元暠东游', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寶書翻譯學初成，振錫如飛白足輕。","彭澤因家凡幾世，靈山預會是前生。","傳燈已悟無爲理，濡露猶懷罔極情。","從此多逢大居士，何人不願解珠瓔。"]', '["寶书翻譯学初成，振錫如飞白足轻。","彭澤因家凡幾世，靈山預會是前生。","傳灯已悟無爲理，濡露猶懷罔極情。","從此多逢大居士，何人不願解珠瓔。"]', '诗', 'shi', '', NULL, '送僧元暠東遊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c6019d-59f8-49fe-aaf0-6180c3eced96', '赠日本僧智藏', '赠日本僧智藏', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["浮杯萬里過滄溟，遍禮名山適性靈。","深夜降龍潭水黑，新秋放鶴野田青。","身無彼我那懷土，心會真如不讀經。","爲問中華學道者，幾人雄猛得寧馨。"]', '["浮杯万里過滄溟，遍禮名山適性靈。","深夜降龙潭水黑，新秋放鹤野田青。","身無彼我那懷土，心會真如不读經。","爲问中华学道者，幾人雄猛得寧馨。"]', '诗', 'shi', '', NULL, '赠日本僧智藏 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9f9643-c363-413f-8b97-868a4dd77bdd', '送元簡上人適越', '送元簡上人適越', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["孤雲出岫本無依，勝境名山即是歸。","久向吳門遊好寺，還思越水洗塵機。","浙江濤驚獅子吼，稽嶺峰疑靈鷲飛。","更入天台石橋去，垂珠璀璨拂三衣。"]', '["孤云出岫本無依，勝境名山即是归。","久向吳门游好寺，還思越水洗塵機。","浙江濤驚獅子吼，稽嶺峰疑靈鷲飞。","更入天台石橋去，垂珠璀璨拂三衣。"]', '诗', 'shi', '', NULL, '送元簡上人適越 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9abf8f00-28ba-467b-8a5d-735b11898f55', '送宗密上人歸南山草堂寺因謁河南尹白侍郎', '送宗密上人归南山草堂寺因謁河南尹白侍郎', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["宿習修來得慧根，多聞第一却忘言。","自從七祖傳心印，不要三乘入便門。","東泛滄江尋古跡，西歸紫閣出塵喧。","河南白尹大檀越，好把真經相對翻。"]', '["宿習修来得慧根，多闻第一却忘言。","自從七祖傳心印，不要三乘入便门。","东泛滄江尋古跡，西归紫閣出塵喧。","河南白尹大檀越，好把真經相对翻。"]', '诗', 'shi', '', NULL, '送宗密上人歸南山草堂寺因謁河南尹白侍郎 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80beb8cc-8338-44d4-8b96-7f9d32133c97', '西塞山懷古', '西塞山懷古', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["西晉樓船下益州，金陵王氣黯然收。","千尋鐵鎖沈江底，一片降旛出石頭。","人世幾回傷往事，山形依舊枕江流。","今逢四海爲家日，故壘蕭蕭蘆荻秋。"]', '["西晉楼船下益州，金陵王氣黯然收。","千尋鐵鎖沈江底，一片降旛出石头。","人世幾回傷往事，山形依旧枕江流。","今逢四海爲家日，故壘蕭蕭蘆荻秋。"]', '诗', 'shi', '', NULL, '西塞山懷古 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c73555-f579-404f-bdc9-4a2582e2f343', '廣宣上人寄在蜀與韋令公唱和詩卷因以令公手扎荅詩示之', '廣宣上人寄在蜀與韋令公唱和诗卷因以令公手扎荅诗示之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["碧雲佳句久傳芳，曾向成都住草堂。","振錫常過長者宅，披衣猶帶令公香。","一時風景添詩思，八部人天入道塲。","吾家本自有柴桑。"]', '["碧云佳句久傳芳，曾向成都住草堂。","振錫常過长者宅，披衣猶带令公香。","一时风景添诗思，八部人天入道塲。","吾家本自有柴桑。"]', '诗', 'shi', '', NULL, '廣宣上人寄在蜀與韋令公唱和詩卷因以令公手扎荅詩示之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d821b6-2576-467b-a3f0-4578331e11b6', '白舍人自杭州寄新詩有柳色春藏蘇小家之句因而戲酬兼寄浙東元相公', '白舍人自杭州寄新诗有柳色春藏蘇小家之句因而戲酬兼寄浙东元相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["錢塘山水有奇聲，暫謫仙官領百城。","女妓還聞名小小，使君誰許喚卿卿。","鼇驚震海風雷起，蜃鬬噓天樓閣成。","莫道騷人在三楚，文星今向斗牛明。"]', '["錢塘山水有奇声，暫謫仙官領百城。","女妓還闻名小小，使君誰許喚卿卿。","鼇驚震海风雷起，蜃鬬噓天楼閣成。","莫道騷人在三楚，文星今向斗牛明。"]', '诗', 'shi', '', NULL, '白舍人自杭州寄新詩有柳色春藏蘇小家之句因而戲酬兼寄浙東元相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63442237-5430-48e6-a3e6-2efc5e5b1b95', '春日書懷寄東洛白二十二楊八二庶子', '春日书懷寄东洛白二十二楊八二庶子', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾向空門學坐禪，如今萬事盡忘筌。","眼前名利同春夢，醉裏風情敵少年。","野草芳菲紅錦地，遊絲撩亂碧羅天。","心知洛下閑才子，不作詩魔即酒顛。"]', '["曾向空门学坐禪，如今万事尽忘筌。","眼前名利同春梦，醉裏风情敵少年。","野草芳菲紅錦地，游絲撩亂碧羅天。","心知洛下闲才子，不作诗魔即酒顛。"]', '诗', 'shi', '', NULL, '春日書懷寄東洛白二十二楊八二庶子 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70109909-89e3-4aa8-aeca-a6b3a41cb013', '白舍人見酬拙詩因以寄謝', '白舍人见酬拙诗因以寄謝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雖陪三品散班中，資歷從來事不同。","名姓也曾鐫石柱，詩篇未得上屏風。","甘陵舊黨凋零盡，魏闕新知禮數崇。","煙水五湖如有伴，猶應堪作釣魚翁。"]', '["雖陪三品散班中，資歷從来事不同。","名姓也曾鐫石柱，诗篇未得上屏风。","甘陵旧黨凋零尽，魏闕新知禮數崇。","煙水五湖如有伴，猶應堪作釣鱼翁。"]', '诗', 'shi', '', NULL, '白舍人見酬拙詩因以寄謝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d6286a-c1fb-4958-b186-6e862cc8f585', '白舍人曹長寄新詩有遊宴之盛因以戲酬', '白舍人曹长寄新诗有游宴之盛因以戲酬', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蘇州刺史例能詩，西掖今來替左司。","二八城門開道路，五千兵馬引旌旗。","水通山寺笙歌去，騎過虹橋劒戟隨。","若共吳王鬬百草，不如應是欠西施。"]', '["蘇州刺史例能诗，西掖今来替左司。","二八城门开道路，五千兵马引旌旗。","水通山寺笙歌去，騎過虹橋劒戟隨。","若共吳王鬬百草，不如應是欠西施。"]', '诗', 'shi', '', NULL, '白舍人曹長寄新詩有遊宴之盛因以戲酬 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488acecf-66b8-4744-8956-adeeaf875a89', '蘇州白舍人寄新詩有歎早白無兒之句因以贈之', '蘇州白舍人寄新诗有歎早白無兒之句因以贈之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["莫嗟華髪與無兒，却是人間久遠期。","雪裏高山頭白早，海中仙果子生遲。","于公必有高門慶，謝守何煩曉鏡悲。","幸免如新分非淺，祝君長詠夢熊詩。"]', '["莫嗟华髪與無兒，却是人间久远期。","雪裏高山头白早，海中仙果子生遲。","于公必有高门慶，謝守何煩晓镜悲。","幸免如新分非淺，祝君长詠梦熊诗。"]', '诗', 'shi', '', NULL, '蘇州白舍人寄新詩有歎早白無兒之句因以贈之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c955427-5806-4e78-949e-0cff513bc8e7', '酬樂天揚州初逢席上見贈', '酬乐天揚州初逢席上见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巴山楚水淒涼地，二十三年棄置身。","懷舊空吟聞篴賦，到鄉翻似爛柯人。","沈舟側畔千帆過，病樹前頭萬木春。","今日聽君歌一曲，暫憑杯酒長精神。"]', '["巴山楚水淒涼地，二十三年棄置身。","懷旧空吟闻篴賦，到乡翻似爛柯人。","沈舟側畔千帆過，病樹前头万木春。","今日听君歌一曲，暫憑杯酒长精神。"]', '诗', 'shi', '', NULL, '酬樂天揚州初逢席上見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('641ed438-78bc-4b61-a023-7fe34fed2ef4', '罷郡歸洛途次山陽留辭郭中丞使君', '罷郡归洛途次山陽留辞郭中丞使君', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["自到山陽不許辭，高齋日夜有佳期。","管弦正合看書院，語笑方酣各詠詩。","銀漢雪晴褰翠幕，清淮月影落金巵。","洛陽歸客明朝去，容趂城東花發時。"]', '["自到山陽不許辞，高斋日夜有佳期。","管弦正合看书院，語笑方酣各詠诗。","銀漢雪晴褰翠幕，清淮月影落金巵。","洛陽归客明朝去，容趂城东花發时。"]', '诗', 'shi', '', NULL, '罷郡歸洛途次山陽留辭郭中丞使君 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601bbaae-8b53-4ae8-aa24-deec5f03defb', '楚州開元寺北院枸杞臨井繁茂可觀羣賢賦詩因以繼和', '楚州开元寺北院枸杞臨井繁茂可观羣賢賦诗因以繼和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["僧房藥樹依寒井，井有香泉樹有靈。","翠黛葉生籠石甃，殷紅子熟照銅瓶。","枝繁本是仙人杖，根老新成瑞犬形。","上品功能甘露味，還知一勺可延齡。"]', '["僧房藥樹依寒井，井有香泉樹有靈。","翠黛葉生籠石甃，殷紅子熟照銅瓶。","枝繁本是仙人杖，根老新成瑞犬形。","上品功能甘露味，還知一勺可延齡。"]', '诗', 'shi', '', NULL, '楚州開元寺北院枸杞臨井繁茂可觀羣賢賦詩因以繼和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2965e4a0-84db-4909-975e-50a1ef0e0ae4', '和樂天鸚鵡', '和乐天鸚鵡', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["養來鸚鵡觜初紅，宜在朱樓繡戶中。","頻學喚人緣性慧，偏能識主爲情通。","歛毛睡足難銷日，嚲翅愁時願見風。","誰遣聰明好顏色，事須安置入深籠。"]', '["養来鸚鵡觜初紅，宜在朱楼繡戶中。","頻学喚人緣性慧，偏能識主爲情通。","歛毛睡足难銷日，嚲翅愁时願见风。","誰遣聰明好顏色，事須安置入深籠。"]', '诗', 'shi', '', NULL, '和樂天鸚鵡 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94b593ad-722b-4c80-a3a8-3a1d9be89f68', '洛中逢白監同話遊梁之樂因寄宣武令狐相公', '洛中逢白監同話游梁之乐因寄宣武令狐相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾經謝病各遊梁，今日相逢憶孝王。","少有一身兼將相，更能四面占文章。","開顏坐上催飛盞，廻首庭中看舞槍。","借問風前兼月下，不知何客對胡牀。"]', '["曾經謝病各游梁，今日相逢憶孝王。","少有一身兼將相，更能四面占文章。","开顏坐上催飞盞，廻首庭中看舞槍。","借问风前兼月下，不知何客对胡牀。"]', '诗', 'shi', '', NULL, '洛中逢白監同話遊梁之樂因寄宣武令狐相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1397dd-d7fb-4869-bed9-17ea0cfd5014', '河南王少尹宅燕張常侍白舍人兼呈盧郎中李員外二副使', '河南王少尹宅燕張常侍白舍人兼呈盧郎中李員外二副使', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["將星夜落使星來，三省清臣到外臺。","事重各銜天子詔，禮成同把故人盃。","捲簾松竹雪初霽，滿院池塘春欲回。","第一林亭迎好客，殷勤莫惜玉山頹。"]', '["將星夜落使星来，三省清臣到外台。","事重各銜天子詔，禮成同把故人盃。","捲簾松竹雪初霽，满院池塘春欲回。","第一林亭迎好客，殷勤莫惜玉山頹。"]', '诗', 'shi', '', NULL, '河南王少尹宅燕張常侍白舍人兼呈盧郎中李員外二副使 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82dbecf-289e-427b-8f98-26016acc7b1f', '和宣武令狐相公郡齋對新竹', '和宣武令狐相公郡斋对新竹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新竹翛翛韻曉風，隔囱依砌尚蒙籠。","數間素壁初開後，一段清光入坐中。","欹枕閑看知自適，含毫朗詠與誰同。","此君若欲長相見，政事堂東有舊叢。"]', '["新竹翛翛韻晓风，隔囱依砌尚蒙籠。","數间素壁初开後，一段清光入坐中。","欹枕闲看知自適，含毫朗詠與誰同。","此君若欲长相见，政事堂东有旧叢。"]', '诗', 'shi', '', NULL, '和宣武令狐相公郡齋對新竹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f56f54-865b-497a-b0f3-f78f5b863ddf', '和樂天送鶴上裴相公別鶴之作', '和乐天送鹤上裴相公別鹤之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昨日看成送鶴詩，高籠提出白雲司。","朱門乍入應迷路，玉樹容棲莫揀枝。","雙舞庭中花落處，數聲池上月明時。","三山碧海不歸去，且向人間呈羽儀。"]', '["昨日看成送鹤诗，高籠提出白云司。","朱门乍入應迷路，玉樹容棲莫揀枝。","雙舞庭中花落处，數声池上月明时。","三山碧海不归去，且向人间呈羽儀。"]', '诗', 'shi', '', NULL, '和樂天送鶴上裴相公別鶴之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf9fc808-ee9a-464d-ba02-b59163cc8086', '闕下待傳點呈諸同舍', '闕下待傳点呈諸同舍', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["禁漏晨鐘聲欲絕，旌旗組綬影相交。","殿含佳氣當龍首，閣倚晴天見鳳巢。","山色葱籠丹檻外，霞光泛灧翠松梢。","多慙再入金門籍，不敢爲文學解嘲。"]', '["禁漏晨鐘声欲絕，旌旗組綬影相交。","殿含佳氣當龙首，閣倚晴天见鳳巢。","山色葱籠丹檻外，霞光泛灧翠松梢。","多慙再入金门籍，不敢爲文学解嘲。"]', '诗', 'shi', '', NULL, '闕下待傳點呈諸同舍 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ce42a0-d71c-4604-b9bc-90a1f6d73752', '和樂天以鏡換酒', '和乐天以镜換酒', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["把取菱花百鍊鏡，換他竹葉十旬杯。","嚬眉厭老終難去，蘸甲須歡便到來。","妍醜太分迷忌諱，松喬俱傲絕嫌猜。","校量功力相千萬，好去從空白玉臺。"]', '["把取菱花百鍊镜，換他竹葉十旬杯。","嚬眉厭老終难去，蘸甲須歡便到来。","妍醜太分迷忌諱，松喬俱傲絕嫌猜。","校量功力相千万，好去從空白玉台。"]', '诗', 'shi', '', NULL, '和樂天以鏡換酒 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf46c97-4770-4e6b-bd01-b4c4ad49c552', '同樂天送河南馮尹學士', '同乐天送河南馮尹学士', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["可憐五馬風流地，暫輟金貂侍從才。","閣上掩書劉向去，門前修刺孔融來。","崤陵路靜寒無雨，洛水橋長晝起雷。","共羨府中棠棣好，先於城外百花開。"]', '["可怜五马风流地，暫輟金貂侍從才。","閣上掩书劉向去，门前修刺孔融来。","崤陵路静寒無雨，洛水橋长晝起雷。","共羨府中棠棣好，先於城外百花开。"]', '诗', 'shi', '', NULL, '同樂天送河南馮尹學士 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86e1f74-25be-409e-bc40-23c5c588d7db', '同白二十二贈王山人', '同白二十二贈王山人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["愛名之世忘名客，多事之時無事身。","古老相傳見來久，歲年雖變貌常新。","飛章上達三清路，受籙平交五嶽神。","笑聽鼕鼕朝暮鼓，只能催得市朝人。"]', '["愛名之世忘名客，多事之时無事身。","古老相傳见来久，歲年雖变貌常新。","飞章上達三清路，受籙平交五嶽神。","笑听鼕鼕朝暮鼓，只能催得市朝人。"]', '诗', 'shi', '', NULL, '同白二十二贈王山人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('137bed02-ce9e-4354-aa9b-8aa64f003a01', '題集賢閣', '題集賢閣', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳池西畔圖書府，玉樹玲瓏景氣閑。","長聽餘風送天樂，時登高閣望人寰。","青山雲繞欄干外，紫殿香來步武間。","曾是先賢翔集地，每看壁記一慙顏。"]', '["鳳池西畔圖书府，玉樹玲瓏景氣闲。","长听餘风送天乐，时登高閣望人寰。","青山云繞欄干外，紫殿香来步武间。","曾是先賢翔集地，每看壁記一慙顏。"]', '诗', 'shi', '', NULL, '題集賢閣 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280be731-30c8-49ab-bbd1-784133f1ae61', '和令狐相公初歸京國賦詩言懷', '和令狐相公初归京国賦诗言懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["凌雲羽翮掞天才，揚歷中樞與外臺。","相印昔辭東閣去，將星還拱北辰來。","殿庭捧日彯纓入，閣道看山曳履回。","口不言功心自適，吟詩釀酒待花開。"]', '["凌云羽翮掞天才，揚歷中樞與外台。","相印昔辞东閣去，將星還拱北辰来。","殿庭捧日彯纓入，閣道看山曳履回。","口不言功心自適，吟诗釀酒待花开。"]', '诗', 'shi', '', NULL, '和令狐相公初歸京國賦詩言懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad08293-0114-4150-b8dc-b555bcda6d35', '和樂天南園試小樂', '和乐天南园試小乐', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["閑步南園煙雨晴，遙聞絲竹出牆聲。","欲拋丹筆三川去，先教清商一部成。","花木手栽偏有興，歌詞自作別生情。","多才遇景皆能詠，當日人傳滿鳳城。"]', '["闲步南园煙雨晴，遙闻絲竹出牆声。","欲拋丹笔三川去，先教清商一部成。","花木手栽偏有兴，歌词自作別生情。","多才遇景皆能詠，當日人傳满鳳城。"]', '诗', 'shi', '', NULL, '和樂天南園試小樂 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204ea4e4-ee44-4d7a-8466-9530131e9c7c', '答樂天戲贈', '答乐天戲贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["才子聲名白侍郎，風流雖老尚難當。","詩情逸似陶彭澤，齋日多如周太常。","矻矻將心求淨法，時時偷眼看春光。","知君技癢思歡讌，欲倩天魔破道塲。"]', '["才子声名白侍郎，风流雖老尚难當。","诗情逸似陶彭澤，斋日多如周太常。","矻矻將心求淨法，时时偷眼看春光。","知君技癢思歡讌，欲倩天魔破道塲。"]', '诗', 'shi', '', NULL, '答樂天戲贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2713cdb-0b94-4cc2-9673-567c21766154', '同樂天送令狐相公赴東都留守', '同乐天送令狐相公赴东都留守', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["尚書劒履出明光，居守旌旗赴洛陽。","世上功名兼將相，人間聲價是文章。","衙門曉闢分天仗，賓幕初開辟省郎。","從發坡頭向東望，春風處處有甘棠。"]', '["尚书劒履出明光，居守旌旗赴洛陽。","世上功名兼將相，人间声價是文章。","衙门晓闢分天仗，賓幕初开辟省郎。","從發坡头向东望，春风处处有甘棠。"]', '诗', 'shi', '', NULL, '同樂天送令狐相公赴東都留守 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c270ce-4044-47ff-8562-7628ee3711f1', '刑部白侍郎謝病長告改賓客分司以詩贈別', '刑部白侍郎謝病长告改賓客分司以诗贈別', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鼎食華軒到眼前，拂衣高謝豈徒然。","九霄路上辭朝客，四皓叢中作少年。","他日臥龍終得雨，今朝放鶴且沖天。","洛陽舊有衡茆在，亦擬抽身伴地仙。"]', '["鼎食华軒到眼前，拂衣高謝豈徒然。","九霄路上辞朝客，四皓叢中作少年。","他日臥龙終得雨，今朝放鹤且沖天。","洛陽旧有衡茆在，亦擬抽身伴地仙。"]', '诗', 'shi', '', NULL, '刑部白侍郎謝病長告改賓客分司以詩贈別 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ef203f-e582-4ac6-ad7a-2b1c73d1debe', '和留守令狐相公答白賓客', '和留守令狐相公答白賓客', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["麥隴和風吹樹枝，商山逸客出關時。","身無拘束起長晚，路足交親行自遲。","官拂象筵終日待，私將雞黍幾人期。","君來不用飛書報，萬戶先從紙貴知。"]', '["麦隴和风吹樹枝，商山逸客出关时。","身無拘束起长晚，路足交親行自遲。","官拂象筵終日待，私將雞黍幾人期。","君来不用飞书報，万戶先從紙貴知。"]', '诗', 'shi', '', NULL, '和留守令狐相公答白賓客 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0c278e-28be-4192-b9eb-0403efeb7fbf', '酬鄆州令狐相公官舍言懷見寄兼呈樂天', '酬鄆州令狐相公官舍言懷见寄兼呈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["詞人各在一涯居，聲味雖同跡自疎。","佳句傳因多好事，尺題稀爲不便書。","已通戎略逢黃石，仍占星文耀碧虛。","聞說朝天在來歲，霸陵春色待行車。"]', '["词人各在一涯居，声味雖同跡自疎。","佳句傳因多好事，尺題稀爲不便书。","已通戎略逢黄石，仍占星文耀碧虛。","闻说朝天在来歲，霸陵春色待行车。"]', '诗', 'shi', '', NULL, '酬鄆州令狐相公官舍言懷見寄兼呈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f1653d-075b-44a3-b213-feac85e3c0e4', '吟白樂天哭崔兒二篇愴然寄贈', '吟白乐天哭崔兒二篇愴然寄贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吟君苦調我霑纓，能使無情盡有情。","四望車中心未釋，千秋亭下賦初成。","庭梧已有棲雛處，池鶴今無子和聲。","從此期君比瓊樹，一枝吹折一枝生。"]', '["吟君苦調我霑纓，能使無情尽有情。","四望车中心未釋，千秋亭下賦初成。","庭梧已有棲雛处，池鹤今無子和声。","從此期君比瓊樹，一枝吹折一枝生。"]', '诗', 'shi', '', NULL, '吟白樂天哭崔兒二篇愴然寄贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4067dec0-483d-47cc-b14c-db0545be278a', '答樂天所寄詠懷且釋其枯樹之歎', '答乐天所寄詠懷且釋其枯樹之歎', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["衙前有樂饌常精，宅內連池酒任傾。","自是官高無狎客，不論年長少歡情。","驪龍頷被探珠去，老蚌胚還應月生。","莫羨三春桃與李，桂花成實向秋榮。"]', '["衙前有乐饌常精，宅內連池酒任傾。","自是官高無狎客，不論年长少歡情。","驪龙頷被探珠去，老蚌胚還應月生。","莫羨三春桃與李，桂花成實向秋榮。"]', '诗', 'shi', '', NULL, '答樂天所寄詠懷且釋其枯樹之歎 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb122e4-3555-4678-a0ca-e5d43c72e6b7', '赴蘇州酬別樂天', '赴蘇州酬別乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吳郡魚書下紫宸，長安廄吏送朱輪。","二南風化承遺愛，八詠聲名躡後塵。","梁氏夫妻爲寄客，陸家兄弟是州民。","江城春日追遊處，共憶東歸舊主人。"]', '["吳郡鱼书下紫宸，长安廄吏送朱輪。","二南风化承遺愛，八詠声名躡後塵。","梁氏夫妻爲寄客，陸家兄弟是州民。","江城春日追游处，共憶东归旧主人。"]', '诗', 'shi', '', NULL, '赴蘇州酬別樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fabcd3b0-ac3e-4199-9592-cd1d59ba92b0', '福先寺雪中酬別樂天', '福先寺雪中酬別乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["龍門賓客會龍宮，東去旌旗駐上東。","二八笙歌雲幕下，三千世界雪花中。","離堂未暗排紅燭，別曲含淒颺晚風。","才子從今一分散，便將詩詠向吳儂。"]', '["龙门賓客會龙宮，东去旌旗駐上东。","二八笙歌云幕下，三千世界雪花中。","離堂未暗排紅燭，別曲含淒颺晚风。","才子從今一分散，便將诗詠向吳儂。"]', '诗', 'shi', '', NULL, '福先寺雪中酬別樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e488f48-94e4-4141-abb9-04d4d8f8c546', '和樂天耳順吟兼寄敦詩', '和乐天耳順吟兼寄敦诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吟君新什慰蹉跎，屈指同登耳順科。","鄧禹功成三紀事，孔融書就八年多。","已經將相誰能爾，拋却丞郎爭奈何。","獨恨長洲數千里，且隨魚鳥泛煙波。"]', '["吟君新什慰蹉跎，屈指同登耳順科。","鄧禹功成三紀事，孔融书就八年多。","已經將相誰能爾，拋却丞郎爭奈何。","独恨长洲數千里，且隨鱼鸟泛煙波。"]', '诗', 'shi', '', NULL, '和樂天耳順吟兼寄敦詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d460f1e-1f99-418e-be2c-fa8bc51b7e20', '和白侍郎送令狐相公鎮太原', '和白侍郎送令狐相公鎮太原', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["十萬天兵貂錦衣，晉城風日斗生輝。","行臺僕射深恩重，從事中郎舊路歸。","疊鼓蹙成汾水浪，閃旗驚斷塞鴻飛。","邊庭自此無烽火，擁節還來坐紫微。"]', '["十万天兵貂錦衣，晉城风日斗生輝。","行台僕射深恩重，從事中郎旧路归。","叠鼓蹙成汾水浪，閃旗驚斷塞鴻飞。","邊庭自此無烽火，擁節還来坐紫微。"]', '诗', 'shi', '', NULL, '和白侍郎送令狐相公鎮太原 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53e5527-17d7-44c9-b4fb-17cc910ceafe', '酬樂天見寄', '酬乐天见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["元君後輩先零落，崔相同年不少留。","華屋坐來能幾日，夜臺歸去便千秋。","背時猶自居三品，得老終須卜一丘。","若使吾徒還早達，亦應簫鼓入松楸。"]', '["元君後輩先零落，崔相同年不少留。","华屋坐来能幾日，夜台归去便千秋。","背时猶自居三品，得老終須卜一丘。","若使吾徒還早達，亦應簫鼓入松楸。"]', '诗', 'shi', '', NULL, '酬樂天見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df67ae37-52c4-4ada-b878-7d25be62e47a', '樂天寄重和晚達冬青一篇因成再答', '乐天寄重和晚達冬青一篇因成再答', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["風雲變化饒年少，光景蹉跎屬老夫。","秋隼得時凌汗漫，寒龜飲氣受泥塗。","東隅有失誰能免，北叟之言豈便無。","振臂猶堪呼一擲，爭知掌下不成盧。"]', '["风云变化饒年少，光景蹉跎屬老夫。","秋隼得时凌汗漫，寒龟饮氣受泥塗。","东隅有失誰能免，北叟之言豈便無。","振臂猶堪呼一擲，爭知掌下不成盧。"]', '诗', 'shi', '', NULL, '樂天寄重和晚達冬青一篇因成再答 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4dc9fac-1160-45b6-8182-51829ac15f72', '河南白尹有喜崔賓客歸洛兼見懷長句因而繼和', '河南白尹有喜崔賓客归洛兼见懷长句因而繼和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["幾年侍從作名臣，却向青雲索得身。","朝士忽爲方外士，主人仍是眼中人。","雙鸞遊處天京好，五馬行時海嶠春。","遙羨光陰不虛擲，肯令絲竹暫生塵。"]', '["幾年侍從作名臣，却向青云索得身。","朝士忽爲方外士，主人仍是眼中人。","雙鸾游处天京好，五马行时海嶠春。","遙羨光陰不虛擲，肯令絲竹暫生塵。"]', '诗', 'shi', '', NULL, '河南白尹有喜崔賓客歸洛兼見懷長句因而繼和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24c31b7-e6cb-4d9b-9046-02856aa0506c', '和楊師臯給事傷小姬英英', '和楊師臯給事傷小姬英英', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["見學胡琴見藝成，今朝追想幾傷情。","撚弦花下呈新曲，放撥燈前謝改名。","但是好花皆易落，從來尤物不長生。","鸞臺夜直衣衾冷，雲雨無因入禁城。"]', '["见学胡琴见藝成，今朝追想幾傷情。","撚弦花下呈新曲，放撥灯前謝改名。","但是好花皆易落，從来尤物不长生。","鸾台夜直衣衾冷，云雨無因入禁城。"]', '诗', 'shi', '', NULL, '和楊師臯給事傷小姬英英 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('267ee733-10b5-4a73-86da-c9b7f2b9f366', '和樂天洛下醉吟寄太原令狐相公兼見懷長句', '和乐天洛下醉吟寄太原令狐相公兼见懷长句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["舊相臨戎非稱意，詞人作尹本多情。","從容自使邊塵靜，談笑不聞桴鼓聲。","章句新添塞下曲，風流舊占洛陽城。","昨來亦有吳趨詠，惟寄東都與北京。"]', '["旧相臨戎非稱意，词人作尹本多情。","從容自使邊塵静，談笑不闻桴鼓声。","章句新添塞下曲，风流旧占洛陽城。","昨来亦有吳趨詠，惟寄东都與北京。"]', '诗', 'shi', '', NULL, '和樂天洛下醉吟寄太原令狐相公兼見懷長句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5263a0dc-06dc-431c-9cfe-cd9fc6b8dfa1', '郡齋書懷寄江南白尹兼簡分司崔賓客', '郡斋书懷寄江南白尹兼簡分司崔賓客', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["謾讀圖書三十車，年年爲郡老天涯。","一生不得文章力，百口空爲飽煖家。","綺季衣冠稱鬢面，吳公政事副詞華。","還思謝病吟歸去，同醉城東桃李花。"]', '["謾读圖书三十车，年年爲郡老天涯。","一生不得文章力，百口空爲飽煖家。","綺季衣冠稱鬢面，吳公政事副词华。","還思謝病吟归去，同醉城东桃李花。"]', '诗', 'shi', '', NULL, '郡齋書懷寄江南白尹兼簡分司崔賓客 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7adcbc-17c9-4fb4-8bca-b22c64894652', '題于家公主舊宅', '題于家公主旧宅', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["樹繞荒臺葉滿池，簫聲一絕草蟲悲。","鄰家猶學宮人髻，園客爭偷御果枝。","馬埒蓬蒿藏狡兔，鳳樓煙雨嘯愁鴟。","何郎獨在無恩澤，不似當初傅粉時。"]', '["樹繞荒台葉满池，簫声一絕草蟲悲。","鄰家猶学宮人髻，园客爭偷御果枝。","马埒蓬蒿藏狡兔，鳳楼煙雨嘯愁鴟。","何郎独在無恩澤，不似當初傅粉时。"]', '诗', 'shi', '', NULL, '題于家公主舊宅 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5231b666-804b-4db2-a24d-3a6e4e0dfaae', '酬樂天貽賀金紫之什', '酬乐天貽賀金紫之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["久學文章含白鳳，却因政事賜金魚。","郡人未識聞謠詠，天子知名與詔書。","珍重賀詩呈錦繡，願言歸計竝園廬。","舊來詞客多無位，金紫同遊誰得如。"]', '["久学文章含白鳳，却因政事賜金鱼。","郡人未識闻謠詠，天子知名與詔书。","珍重賀诗呈錦繡，願言归計竝园廬。","旧来词客多無位，金紫同游誰得如。"]', '诗', 'shi', '', NULL, '酬樂天貽賀金紫之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad777ea-a470-4adc-9af3-a9f6bb22cc10', '樂天見示傷微之敦詩晦叔三君子皆有深分因成是詩以寄', '乐天见示傷微之敦诗晦叔三君子皆有深分因成是诗以寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吟君歎逝雙絕句，使我傷懷奏短歌。","世上空驚故人少，集中惟覺祭文多。","芳林新葉催陳葉，流水前波讓後波。","萬古到今同此恨，聞琴淚盡欲如何。"]', '["吟君歎逝雙絕句，使我傷懷奏短歌。","世上空驚故人少，集中惟覺祭文多。","芳林新葉催陳葉，流水前波讓後波。","万古到今同此恨，闻琴泪尽欲如何。"]', '诗', 'shi', '', NULL, '樂天見示傷微之敦詩晦叔三君子皆有深分因成是詩以寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271f81bf-71b9-4571-8b98-1fa9f6e82467', '和樂天柘枝', '和乐天柘枝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["柘枝本出楚王家，玉面添嬌舞態奢。","鬆鬢改梳鸞鳳髻，新衫別識鬬雞紗。","鼓催殘拍腰身軟，汗透羅衣雨點花。","畫筵曲罷辭歸去，便隨王母上煙霞。"]', '["柘枝本出楚王家，玉面添嬌舞態奢。","鬆鬢改梳鸾鳳髻，新衫別識鬬雞紗。","鼓催殘拍腰身軟，汗透羅衣雨点花。","畫筵曲罷辞归去，便隨王母上煙霞。"]', '诗', 'shi', '', NULL, '和樂天柘枝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a680d46-3a13-42c1-9e08-83b4b8beea86', '和樂天題真娘墓', '和乐天題真娘墓', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["薝蔔林中黃土堆，羅襦繡黛已成灰。","芳魂雖死人不怕，蔓草逢春花自開。","幡蓋向風疑舞袖，鏡燈臨曉似妝臺。","吳王嬌女墳相近，一片行雲應往來。"]', '["薝蔔林中黄土堆，羅襦繡黛已成灰。","芳魂雖死人不怕，蔓草逢春花自开。","幡蓋向风疑舞袖，镜灯臨晓似妝台。","吳王嬌女墳相近，一片行云應往来。"]', '诗', 'shi', '', NULL, '和樂天題真娘墓 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b6cb900-0574-4d96-a0f9-4b95d87736d6', '客有話汴州新政書事寄令狐相公', '客有話汴州新政书事寄令狐相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天下咽喉今大寧，軍城喜氣徹青冥。","庭前劒戟朝迎日，筆底文章夜應星。","三省壁中題姓字，萬人頭上見儀形。","汴州忽復承平事，正月看燈戶不扃。"]', '["天下咽喉今大寧，軍城喜氣徹青冥。","庭前劒戟朝迎日，笔底文章夜應星。","三省壁中題姓字，万人头上见儀形。","汴州忽复承平事，正月看灯戶不扃。"]', '诗', 'shi', '', NULL, '客有話汴州新政書事寄令狐相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c563fc3a-402f-4955-848e-c344c03b0bcf', '令狐相公見示河中楊少尹贈答兼命繼之', '令狐相公见示河中楊少尹贈答兼命繼之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["兩首新詩百字餘，朱弦玉磬韻難如。","漢家丞相重徵後，梁苑仁風一變初。","四面諸侯瞻節制，八方通貨溢河渠。","自從却縠爲元帥，大將歸來盡把書。"]', '["兩首新诗百字餘，朱弦玉磬韻难如。","漢家丞相重徵後，梁苑仁风一变初。","四面諸侯瞻節制，八方通貨溢河渠。","自從却縠爲元帥，大將归来尽把书。"]', '诗', 'shi', '', NULL, '令狐相公見示河中楊少尹贈答兼命繼之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6710f4-2571-48cb-9be7-7b07744d788e', '和令狐相公送趙常盈鍊師與中貴人同拜嶽及天台投龍畢却赴京', '和令狐相公送趙常盈鍊師與中貴人同拜嶽及天台投龙畢却赴京', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["銀璫謁者引蜺旌，霞帔仙官到赤城。","白鶴迎來天樂動，金龍擲下海神驚。","元君伏奏歸中禁，武帝親齋禮上清。","何事夷門請詩送，梁王文字上聲名。"]', '["銀璫謁者引蜺旌，霞帔仙官到赤城。","白鹤迎来天乐动，金龙擲下海神驚。","元君伏奏归中禁，武帝親斋禮上清。","何事夷门請诗送，梁王文字上声名。"]', '诗', 'shi', '', NULL, '和令狐相公送趙常盈鍊師與中貴人同拜嶽及天台投龍畢却赴京 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0664da46-e8c9-4188-9319-202172487d77', '酬令狐相公贈別', '酬令狐相公贈別', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["越聲長苦有誰聞，老向湘山與楚雲。","海嶠新辭永嘉守，夷門重見信陵君。","田園松菊今迷路，霄漢鴛鴻久絕羣。","幸遇甘泉尚詞賦，不知何客薦雄文。"]', '["越声长苦有誰闻，老向湘山與楚云。","海嶠新辞永嘉守，夷门重见信陵君。","田园松菊今迷路，霄漢鴛鴻久絕羣。","幸遇甘泉尚词賦，不知何客薦雄文。"]', '诗', 'shi', '', NULL, '酬令狐相公贈別 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29a2c26-d43c-498f-bfd2-031fe83c9888', '酬令狐相公寄賀遷拜之什', '酬令狐相公寄賀遷拜之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["邅廻二紀重爲郎，洛下遙分列宿光。","不見當關呼早起，曾無侍史與焚香。","三花秀色通春幌，十字清波遶宅牆。","白髮青衫誰比數，相憐只是有梁王。"]', '["邅廻二紀重爲郎，洛下遙分列宿光。","不见當关呼早起，曾無侍史與焚香。","三花秀色通春幌，十字清波遶宅牆。","白髮青衫誰比數，相怜只是有梁王。"]', '诗', 'shi', '', NULL, '酬令狐相公寄賀遷拜之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b280d97-b3f7-479d-a32f-20af06f06aee', '夏日寄宣武令狐相公', '夏日寄宣武令狐相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長憶梁王逸興多，西園花盡興如何。","近來溽暑侵亭館，應覺清談勝綺羅。","境入篇章高韻發，風穿號令衆心和。","承明欲謁先相報，願拂朝衣逐曉珂。"]', '["长憶梁王逸兴多，西园花尽兴如何。","近来溽暑侵亭館，應覺清談勝綺羅。","境入篇章高韻發，风穿號令衆心和。","承明欲謁先相報，願拂朝衣逐晓珂。"]', '诗', 'shi', '', NULL, '夏日寄宣武令狐相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72b456c-821f-4e84-871a-35f0111fb922', '酬令狐留守巡內至集賢院見寄', '酬令狐留守巡內至集賢院见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["仙院文房隔舊宮，當時盛事盡成空。","墨池半在頹垣下，書帶猶生蔓草中。","巡內因經九重苑，裁詩又繼二南風。","爲兄手寫殷勤句，遍歷三台各一通。"]', '["仙院文房隔旧宮，當时盛事尽成空。","墨池半在頹垣下，书带猶生蔓草中。","巡內因經九重苑，裁诗又繼二南风。","爲兄手寫殷勤句，遍歷三台各一通。"]', '诗', 'shi', '', NULL, '酬令狐留守巡內至集賢院見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71226e9d-622d-4c06-86fc-3c916c9bbe9e', '和令狐相公言懷寄河中楊少尹', '和令狐相公言懷寄河中楊少尹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["章句慙非第一流，世間才子昔陪遊。","吳宮已歎芙蓉死，邊月空悲蘆管秋。","任向洛陽稱傲吏，苦教河上領諸侯。","石渠甘對圖書老，關外楊公安穩不。"]', '["章句慙非第一流，世间才子昔陪游。","吳宮已歎芙蓉死，邊月空悲蘆管秋。","任向洛陽稱傲吏，苦教河上領諸侯。","石渠甘对圖书老，关外楊公安穩不。"]', '诗', 'shi', '', NULL, '和令狐相公言懷寄河中楊少尹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa80cfd3-946e-4c04-adaf-2a6eb47c6da2', '令狐相公自天平移鎮太原以詩申賀', '令狐相公自天平移鎮太原以诗申賀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["北都留守將天兵，出入香街宿禁扃。","鼙鼓夜聞驚朔鴈，旌旗曉動拂參星。","孔璋舊檄家家有，叔度新歌處處聽。","夷落遙知真漢相，爭來屈膝看儀刑。"]', '["北都留守將天兵，出入香街宿禁扃。","鼙鼓夜闻驚朔鴈，旌旗晓动拂參星。","孔璋旧檄家家有，叔度新歌处处听。","夷落遙知真漢相，爭来屈膝看儀刑。"]', '诗', 'shi', '', NULL, '令狐相公自天平移鎮太原以詩申賀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223db032-430d-496f-ae7d-8f67efdcf712', '重酬前寄', '重酬前寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["邊烽寂寂盡收兵。","宮樹蒼蒼靜掩扃，戎羯歸心如內地。","天狼無角比凡星，新成麗句開緘後。","便入清歌滿坐聽，吳苑晉祠遙望處。","可憐南北太相形。"]', '["邊烽寂寂尽收兵。","宮樹蒼蒼静掩扃，戎羯归心如內地。","天狼無角比凡星，新成丽句开緘後。","便入清歌满坐听，吳苑晉祠遙望处。","可怜南北太相形。"]', '诗', 'shi', '', NULL, '重酬前寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9815a1d-03a0-4a0b-bc06-43fe3fd2519b', '令狐相公自太原累示新詩因以酬寄', '令狐相公自太原累示新诗因以酬寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["飛蓬卷盡塞雲寒，戰馬閑嘶漢地寬。","萬里胡天無警急，一籠烽火報平安。","燈前妓樂留賓宴，雪後山河出獵看。","珍重新詩遠相寄，風情不似四登壇。"]', '["飞蓬卷尽塞云寒，戰马闲嘶漢地寬。","万里胡天無警急，一籠烽火報平安。","灯前妓乐留賓宴，雪後山河出獵看。","珍重新诗远相寄，风情不似四登壇。"]', '诗', 'shi', '', NULL, '令狐相公自太原累示新詩因以酬寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ed7633-dcd0-4e67-a738-f866cd945145', '酬令狐相公使宅別齋初栽桂樹見懷之作', '酬令狐相公使宅別斋初栽桂樹见懷之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["清淮南岸家山樹，黑水東邊第一栽。","影近畫梁迎曉日，香隨綠酒入金杯。","根留本土依江潤，葉起寒稜映月開。","早晚陰城比梧竹，九霄還放綵雛來。"]', '["清淮南岸家山樹，黑水东邊第一栽。","影近畫梁迎晓日，香隨綠酒入金杯。","根留本土依江潤，葉起寒稜映月开。","早晚陰城比梧竹，九霄還放綵雛来。"]', '诗', 'shi', '', NULL, '酬令狐相公使宅別齋初栽桂樹見懷之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530fc885-8391-4349-ae49-5e7bb5378c89', '酬令狐相公見寄', '酬令狐相公见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["才兼文武播雄名，遺愛芳塵滿洛城。","身在行臺爲僕射，書來甪里訪先生。","閑遊占得嵩山色，醉臥高聽洛水聲。","千里相思難命駕，七言詩裏寄深情。"]', '["才兼文武播雄名，遺愛芳塵满洛城。","身在行台爲僕射，书来甪里訪先生。","闲游占得嵩山色，醉臥高听洛水声。","千里相思难命駕，七言诗裏寄深情。"]', '诗', 'shi', '', NULL, '酬令狐相公見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28e9e75-5bb1-4058-aec3-e7c63be76a99', '郡內書情獻裴侍中留守', '郡內书情獻裴侍中留守', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["功成頻獻乞身章，擺落襄陽鎮洛陽。","萬乘旌旗分一半，八方風雨會中央。","兵符今奉黃公略，書殿曾隨翠鳳翔。","心寄華亭一雙鶴，曰陪高步繞池塘。"]', '["功成頻獻乞身章，擺落襄陽鎮洛陽。","万乘旌旗分一半，八方风雨會中央。","兵符今奉黄公略，书殿曾隨翠鳳翔。","心寄华亭一雙鹤，曰陪高步繞池塘。"]', '诗', 'shi', '', NULL, '郡內書情獻裴侍中留守 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e6af46-ffa6-477c-a1c5-fa7b9fe5bb7c', '酬樂天衫酒見寄', '酬乐天衫酒见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["酒法衆傳吳米好，舞衣偏尚越羅輕。","動搖浮蟻香濃甚，裝束輕鴻意態生。","閱曲定知能自適，舉杯應歎不同傾。","終朝相憶終年別，對景臨風無限情。"]', '["酒法衆傳吳米好，舞衣偏尚越羅轻。","动搖浮蟻香濃甚，裝束轻鴻意態生。","閱曲定知能自適，舉杯應歎不同傾。","終朝相憶終年別，对景臨风無限情。"]', '诗', 'shi', '', NULL, '酬樂天衫酒見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4908a5-c491-4b93-9704-5f8a18b0d769', '自左馮歸洛下酬樂天兼呈裴令公', '自左馮归洛下酬乐天兼呈裴令公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新恩通籍在龍樓，分務神都近舊丘。","自有園公紫芝侶，仍追少傅赤松遊。","華林霜葉紅霞晚，伊水晴光碧玉秋。","更接東山文酒會，始知江左未風流。"]', '["新恩通籍在龙楼，分務神都近旧丘。","自有园公紫芝侶，仍追少傅赤松游。","华林霜葉紅霞晚，伊水晴光碧玉秋。","更接东山文酒會，始知江左未风流。"]', '诗', 'shi', '', NULL, '自左馮歸洛下酬樂天兼呈裴令公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60c816b-3acb-474b-9be8-c930f14a1ea5', '秋齋獨坐寄樂天兼呈吳方之大夫', '秋斋独坐寄乐天兼呈吳方之大夫', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["空齋寂寂不生塵，藥物方書繞病身。","纖草數莖勝靜地，幽禽忽至似佳賓。","世間憂喜雖無定，釋氏銷磨盡有因。","同向洛陽閑度日，莫教風景屬他人。"]', '["空斋寂寂不生塵，藥物方书繞病身。","纖草數莖勝静地，幽禽忽至似佳賓。","世间憂喜雖無定，釋氏銷磨尽有因。","同向洛陽闲度日，莫教风景屬他人。"]', '诗', 'shi', '', NULL, '秋齋獨坐寄樂天兼呈吳方之大夫 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6eec81-a0c4-4cb7-a777-8840be55be57', '和樂天齋戒月滿夜對道場偶懷詠', '和乐天斋戒月满夜对道場偶懷詠', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["常修清淨去繁華，人識王城長者家。","案上香煙鋪貝葉，佛前燈焰透蓮花。","持齋已滿招閑客，理曲先聞命小娃。","明日若過方丈室，還應問爲法來邪。"]', '["常修清淨去繁华，人識王城长者家。","案上香煙鋪貝葉，佛前灯焰透蓮花。","持斋已满招闲客，理曲先闻命小娃。","明日若過方丈室，還應问爲法来邪。"]', '诗', 'shi', '', NULL, '和樂天齋戒月滿夜對道場偶懷詠 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47eff951-59c2-4c6f-bd0e-d3025cf15ac3', '吳方之見示獨酌小醉首篇樂天續有詶答皆含戲謔極至風流兩篇之中竝蒙見屬輒呈濫吹益美來章', '吳方之见示独酌小醉首篇乐天續有詶答皆含戲謔極至风流兩篇之中竝蒙见屬輒呈濫吹益美来章', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["閑門共寂任張羅，靜室同虛養太和。","塵世歡娛開意少，醉鄉風景獨遊多。","散金疏傅尋常樂，枕麴劉生取次歌。","計會雪中爭挈榼，鹿裘鶴氅遞相過。"]', '["闲门共寂任張羅，静室同虛養太和。","塵世歡娛开意少，醉乡风景独游多。","散金疏傅尋常乐，枕麴劉生取次歌。","計會雪中爭挈榼，鹿裘鹤氅遞相過。"]', '诗', 'shi', '', NULL, '吳方之見示獨酌小醉首篇樂天續有詶答皆含戲謔極至風流兩篇之中竝蒙見屬輒呈濫吹益美來章 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ff17ef-526a-4563-9d76-787965ea4d5f', '酬樂天齋滿日裴令公置宴席上戲贈', '酬乐天斋满日裴令公置宴席上戲贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一月道場齋戒滿，今朝華幄管弦迎。","銜杯本自多狂態，事佛無妨有佞名。","酒力半酣愁已散，文鋒未鈍老猶爭。","平陽不獨容賓醉，聽取喧呼吏舍聲。"]', '["一月道場斋戒满，今朝华幄管弦迎。","銜杯本自多狂態，事佛無妨有佞名。","酒力半酣愁已散，文鋒未鈍老猶爭。","平陽不独容賓醉，听取喧呼吏舍声。"]', '诗', 'shi', '', NULL, '酬樂天齋滿日裴令公置宴席上戲贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc622dc2-bead-4741-a807-dc8640173cff', '酬樂天偶題酒甕見寄', '酬乐天偶題酒甕见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["從君勇斷拋名後，世路榮枯見幾回。","門外紅塵人自走，甕頭清酒我初開。","三冬學任胸中有，萬戶侯須骨上來。","何幸相招同醉處，洛陽城裏好池臺。"]', '["從君勇斷拋名後，世路榮枯见幾回。","门外紅塵人自走，甕头清酒我初开。","三冬学任胸中有，万戶侯須骨上来。","何幸相招同醉处，洛陽城裏好池台。"]', '诗', 'shi', '', NULL, '酬樂天偶題酒甕見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58a0828-9669-4171-ad0c-ce6ae0fad3b1', '酬樂天請裴令公開春加宴', '酬乐天請裴令公开春加宴', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高名大位能兼有，恣意遨遊是特恩。","二室煙霞成步障，三川風物是家園。","晨窺苑樹韶光動，晚度河橋春思繁。","弦管常調客常滿，但逢花處即開樽。"]', '["高名大位能兼有，恣意遨游是特恩。","二室煙霞成步障，三川风物是家园。","晨窺苑樹韶光动，晚度河橋春思繁。","弦管常調客常满，但逢花处即开樽。"]', '诗', 'shi', '', NULL, '酬樂天請裴令公開春加宴 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfed425d-bd3d-438a-86d2-3932ee7bba21', '樂天示過敦詩舊宅有感一篇吟之泫然追想昔事因成繼和以寄苦懷', '乐天示過敦诗旧宅有感一篇吟之泫然追想昔事因成繼和以寄苦懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淒涼同到故人居，門枕寒流古木疎。","向秀心中嗟棟宇，蕭何身後散圖書。","本營歸計非無意，唯算生涯尚有餘。","忽憶前言更惆悵，丁寧相約速懸車。"]', '["淒涼同到故人居，门枕寒流古木疎。","向秀心中嗟棟宇，蕭何身後散圖书。","本營归計非無意，唯算生涯尚有餘。","忽憶前言更惆悵，丁寧相約速懸车。"]', '诗', 'shi', '', NULL, '樂天示過敦詩舊宅有感一篇吟之泫然追想昔事因成繼和以寄苦懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8886c089-8837-4faa-a4ef-ca293307dcc5', '寄和東川楊尚書慕巢兼寄西川繼之二公近從弟兄情分偏睦早忝遊舊因成是詩', '寄和东川楊尚书慕巢兼寄西川繼之二公近從弟兄情分偏睦早忝游旧因成是诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["太華蓮峰降嶽靈，兩川棠樹接郊坰。","政同兄弟人人樂，曲奏塤篪處處聽。","楊葉百穿榮會府，芝泥五色耀天庭。","各拋筆硯誇旄鉞，莫遣文星讓將星。"]', '["太华蓮峰降嶽靈，兩川棠樹接郊坰。","政同兄弟人人乐，曲奏塤篪处处听。","楊葉百穿榮會府，芝泥五色耀天庭。","各拋笔硯誇旄鉞，莫遣文星讓將星。"]', '诗', 'shi', '', NULL, '寄和東川楊尚書慕巢兼寄西川繼之二公近從弟兄情分偏睦早忝遊舊因成是詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50dddeca-2601-4924-8a34-12b1df6931ad', '和樂天洛下雪中宴集寄汴州李尚書', '和乐天洛下雪中宴集寄汴州李尚书', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛城無事足杯盤，風雪相和歲欲蘭。","樹上因依見寒鳥，坐中收拾盡閑官。","笙歌要請頻何爽，笑語忘機拙更歡。","遙想兔園今日會，瓊林滿眼映旂竿。"]', '["洛城無事足杯盤，风雪相和歲欲蘭。","樹上因依见寒鸟，坐中收拾尽闲官。","笙歌要請頻何爽，笑語忘機拙更歡。","遙想兔园今日會，瓊林满眼映旂竿。"]', '诗', 'shi', '', NULL, '和樂天洛下雪中宴集寄汴州李尚書 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad9c4a44-e929-4e25-9680-7099ac93da17', '和牛相公遊南莊醉後寓言戲贈樂天兼見示', '和牛相公游南莊醉後寓言戲贈乐天兼见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城外園林初夏天，就中野趣在西偏。","薔薇亂發多臨水，鸂鶒雙遊不避船。","水底遠山雲似雪，橋邊平岸草如煙。","白家唯有杯觴興，欲把頭盤打少年。"]', '["城外园林初夏天，就中野趣在西偏。","薔薇亂發多臨水，鸂鶒雙游不避船。","水底远山云似雪，橋邊平岸草如煙。","白家唯有杯觴兴，欲把头盤打少年。"]', '诗', 'shi', '', NULL, '和牛相公遊南莊醉後寓言戲贈樂天兼見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc1b3ff-50cc-4767-814f-541e521d38ae', '樂天以愚相訪沽酒致歡因成七言聊以奉答', '乐天以愚相訪沽酒致歡因成七言聊以奉答', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["少年曾醉酒旗下，同輩黃衣頷亦黃。","蹴踏青雲尋入仕，蕭條白髮且飛觴。","令徵古事歡生雅，客喚閑人興任狂。","猶勝獨居荒草院，蟬聲聽盡到寒螿。"]', '["少年曾醉酒旗下，同輩黄衣頷亦黄。","蹴踏青云尋入仕，蕭條白髮且飞觴。","令徵古事歡生雅，客喚闲人兴任狂。","猶勝独居荒草院，蟬声听尽到寒螿。"]', '诗', 'shi', '', NULL, '樂天以愚相訪沽酒致歡因成七言聊以奉答 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138347e2-4451-4bbf-a3da-0abb3194d570', '和思黯憶南莊見示', '和思黯憶南莊见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["丞相新家伊水頭，智囊心匠日增修。","化成池沼無痕跡，奔走清波不自由。","臺上看山徐舉酒，潭中見月慢回舟。","從來天下推尤物，合屬人間第一流。"]', '["丞相新家伊水头，智囊心匠日增修。","化成池沼無痕跡，奔走清波不自由。","台上看山徐舉酒，潭中见月慢回舟。","從来天下推尤物，合屬人间第一流。"]', '诗', 'shi', '', NULL, '和思黯憶南莊見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13210ea-a534-49e0-8f95-f4b2999549dc', '酬思黯見示小飲四韻', '酬思黯见示小饮四韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["拋却人間第一官，俗情驚怪我方安。","兵府相印無心戀，洛水嵩雲恣意看。","三足鼎中知味久，百尋竿上擲身難。","追呼故舊連宵飲，直到天明興未闌。"]', '["拋却人间第一官，俗情驚怪我方安。","兵府相印無心戀，洛水嵩云恣意看。","三足鼎中知味久，百尋竿上擲身难。","追呼故旧連宵饮，直到天明兴未闌。"]', '诗', 'shi', '', NULL, '酬思黯見示小飲四韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7265b1f-1a37-4d58-b6ef-e3396a291aa2', '和僕射牛相公春日閑坐見懷', '和僕射牛相公春日闲坐见懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["官曹崇重難頻入，第宅清閑且獨行。","階蟻相逢如偶語，園蜂速去恐違程。","人於紅藥惟看色，鶯到垂楊不惜聲。","東洛池臺怨拋擲，移文非久會應成。"]', '["官曹崇重难頻入，第宅清闲且独行。","階蟻相逢如偶語，园蜂速去恐違程。","人於紅藥惟看色，鶯到垂楊不惜声。","东洛池台怨拋擲，移文非久會應成。"]', '诗', 'shi', '', NULL, '和僕射牛相公春日閑坐見懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95818c9a-fb02-49b8-a75a-90d4aee426ca', '酬元九侍御贈璧竹鞭長句', '酬元九侍御贈璧竹鞭长句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["碧玉孤根生在林，美人相贈比雙金。","初開郢客緘封後，想見巴山冰雪深。","多節本懷端直性，露青猶有歲寒心。","何時策馬同歸去，關樹扶疎敲鐙吟。"]', '["碧玉孤根生在林，美人相贈比雙金。","初开郢客緘封後，想见巴山冰雪深。","多節本懷端直性，露青猶有歲寒心。","何时策马同归去，关樹扶疎敲鐙吟。"]', '诗', 'shi', '', NULL, '酬元九侍御贈璧竹鞭長句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0617c77-dfcb-41e1-b2eb-ea4402c7d9b5', '酬竇員外使君寒食日途次松滋渡先寄示四韻', '酬竇員外使君寒食日途次松滋渡先寄示四韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚鄉寒食橘花時，野渡臨風駐綵旗。","草色連雲人去住，水紋如縠燕差池。","朱輪尚憶羣飛雉，青綬初縣左顧龜。","非是湓城舊司馬，水曹何事與新詩。"]', '["楚乡寒食橘花时，野渡臨风駐綵旗。","草色連云人去住，水紋如縠燕差池。","朱輪尚憶羣飞雉，青綬初縣左顧龟。","非是湓城旧司马，水曹何事與新诗。"]', '诗', 'shi', '', NULL, '酬竇員外使君寒食日途次松滋渡先寄示四韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd180ce-c455-4411-9886-058b27a93216', '寄楊八拾遺', '寄楊八拾遺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["聞君前日獨庭爭，漢帝偏知白馬生。","忽領簿書遊太學，寧勞侍從厭承明。","洛陽本自宜才子，海內而今有直聲。","爲謝同僚老博士，范雲來歲即公卿。"]', '["闻君前日独庭爭，漢帝偏知白马生。","忽領簿书游太学，寧勞侍從厭承明。","洛陽本自宜才子，海內而今有直声。","爲謝同僚老博士，范云来歲即公卿。"]', '诗', 'shi', '', NULL, '寄楊八拾遺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a4c844-9986-4fff-b071-00d2e154a39f', '酬竇員外郡齋宴客偶命柘枝因見寄兼呈張十一院長元九侍御', '酬竇員外郡斋宴客偶命柘枝因见寄兼呈張十一院长元九侍御', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["分憂餘刃又從公，白羽胡牀嘯詠中。","綵筆諭戎矜倚馬，華堂留客看驚鴻。","渚宮油幕方高步，澧浦甘棠有幾叢。","若問騷人何處所，門臨寒水落江楓。"]', '["分憂餘刃又從公，白羽胡牀嘯詠中。","綵笔諭戎矜倚马，华堂留客看驚鴻。","渚宮油幕方高步，澧浦甘棠有幾叢。","若问騷人何处所，门臨寒水落江楓。"]', '诗', 'shi', '', NULL, '酬竇員外郡齋宴客偶命柘枝因見寄兼呈張十一院長元九侍御 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a439825-ff4c-49ee-866d-84586386b57d', '謝竇員外旬休早涼見示詩', '謝竇員外旬休早涼见示诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新秋十日澣朱衣，鈴閣無聲公吏歸。","風韻漸高梧葉動，露光初重槿花稀。","四時苒苒催容鬢，三爵油油忘是非。","更報明朝池上酌，人知太守字玄暉。"]', '["新秋十日澣朱衣，鈴閣無声公吏归。","风韻漸高梧葉动，露光初重槿花稀。","四时苒苒催容鬢，三爵油油忘是非。","更報明朝池上酌，人知太守字玄暉。"]', '诗', 'shi', '', NULL, '謝竇員外旬休早涼見示詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7da397-197d-437e-9fc7-88fe96d648c4', '南海馬大夫遠示著述兼酬拙詩輒著微誠再有長句時蔡戎未弭故見於篇末', '南海马大夫远示著述兼酬拙诗輒著微誠再有长句时蔡戎未弭故见於篇末', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢家旄節付雄才，百越南溟統外臺。","身在絳紗傳六藝，腰懸青綬亞三臺。","連天浪靜長鯨息，映日帆多寶舶來。","聞道楚氛猶未滅，終須旌斾掃雲雷。"]', '["漢家旄節付雄才，百越南溟統外台。","身在絳紗傳六藝，腰懸青綬亞三台。","連天浪静长鯨息，映日帆多寶舶来。","闻道楚氛猶未滅，終須旌斾掃云雷。"]', '诗', 'shi', '', NULL, '南海馬大夫遠示著述兼酬拙詩輒著微誠再有長句時蔡戎未弭故見於篇末 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55f56eb-431d-4e73-97ec-8f067a5ef5c7', '和南海馬大夫聞楊侍郎出守郴州因有寄上之作', '和南海马大夫闻楊侍郎出守郴州因有寄上之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["忽驚金印駕枝轓，遂別鳴珂聽曉猿。","碧落仙來雖暫謫，赤泉侯在是深恩。","玉環慶遠瞻台坐，銅柱勳高壓海門。","一詠瓊瑤百憂散，何勞更樹北堂萱。"]', '["忽驚金印駕枝轓，遂別鳴珂听晓猿。","碧落仙来雖暫謫，赤泉侯在是深恩。","玉环慶远瞻台坐，銅柱勳高壓海门。","一詠瓊瑤百憂散，何勞更樹北堂萱。"]', '诗', 'shi', '', NULL, '和南海馬大夫聞楊侍郎出守郴州因有寄上之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72834f8-270d-419c-92c1-603720ce7d3a', '馬大夫見示浙西王侍御贈答詩因命同作', '马大夫见示浙西王侍御贈答诗因命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["憶逐羊車凡幾時，今來舊府統戎師。","象筵照室會詞客，銅鼓臨軒舞海夷。","百越酋豪稱故吏，十洲風景助新詩。","秣陵從事何年別，一見瓊章如素期。"]', '["憶逐羊车凡幾时，今来旧府統戎師。","象筵照室會词客，銅鼓臨軒舞海夷。","百越酋豪稱故吏，十洲风景助新诗。","秣陵從事何年別，一见瓊章如素期。"]', '诗', 'shi', '', NULL, '馬大夫見示浙西王侍御贈答詩因命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e72e0e6-b329-41f0-a061-f709c5fa3737', '寄唐州楊八歸厚', '寄唐州楊八归厚', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淮安古地擁州師，畫角金鐃旦夕吹。","淺草遙迎鷫鸘馬，春風亂颭辟邪旗。","謫仙年月今應滿，戇諫聲名衆所知。","何況遷喬舊同伴，一雙先入鳳凰池。"]', '["淮安古地擁州師，畫角金鐃旦夕吹。","淺草遙迎鷫鸘马，春风亂颭辟邪旗。","謫仙年月今應满，戇諫声名衆所知。","何況遷喬旧同伴，一雙先入鳳凰池。"]', '诗', 'shi', '', NULL, '寄唐州楊八歸厚 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9665d2-057e-44a6-8f9f-d91b6f3c6552', '寄朗州溫右史曹長', '寄朗州溫右史曹长', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暫別瑤墀鴛鷺行，綵旗雙引到沅湘。","城邊流水桃花過，簾外春風杜若香。","史筆枉將書紙尾，朝纓不稱濯滄浪。","雲臺公業家聲在，徵詔何時出建章。"]', '["暫別瑤墀鴛鷺行，綵旗雙引到沅湘。","城邊流水桃花過，簾外春风杜若香。","史笔枉將书紙尾，朝纓不稱濯滄浪。","云台公業家声在，徵詔何时出建章。"]', '诗', 'shi', '', NULL, '寄朗州溫右史曹長 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d07bec-a51c-4474-b05f-ff7fc018c4f4', '詶楊司業巨源見寄', '詶楊司業巨源见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["辟雍流水近靈臺，中有詩篇絕世才。","渤海歸人將集去，棃園弟子請詞來。","瓊枝未識魂空斷，寶匣初臨手自開。","莫道專城管雲雨，其如心似不然灰。"]', '["辟雍流水近靈台，中有诗篇絕世才。","渤海归人將集去，棃园弟子請词来。","瓊枝未識魂空斷，寶匣初臨手自开。","莫道專城管云雨，其如心似不然灰。"]', '诗', 'shi', '', NULL, '詶楊司業巨源見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25eeaa0b-dad0-4164-bb62-1896bdb82443', '詶國子崔博士立之見寄', '詶国子崔博士立之见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["健筆高科早絕倫，後來無不揖芳塵。","遍看今日乘軒客，多是昔年呈卷人。","胄子執經瞻講坐，郎官共食接華茵。","煩君遠寄相思曲，慰問天南一逐臣。"]', '["健笔高科早絕倫，後来無不揖芳塵。","遍看今日乘軒客，多是昔年呈卷人。","胄子執經瞻講坐，郎官共食接华茵。","煩君远寄相思曲，慰问天南一逐臣。"]', '诗', 'shi', '', NULL, '詶國子崔博士立之見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27f11984-b48d-411c-a8ed-100684a6f731', '張郎中籍遠寄長句開緘之日已及新秋因舉目前仰酬高韻', '張郎中籍远寄长句开緘之日已及新秋因舉目前仰酬高韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南宮詞客寄新篇，清似湘靈促柱弦。","京邑舊遊勞夢想，歷陽秋色正澄鮮。","雲銜日脚成山雨，風駕潮頭入渚田。","對此獨吟還獨酌，知音不見思愴然。"]', '["南宮词客寄新篇，清似湘靈促柱弦。","京邑旧游勞梦想，歷陽秋色正澄鲜。","云銜日脚成山雨，风駕潮头入渚田。","对此独吟還独酌，知音不见思愴然。"]', '诗', 'shi', '', NULL, '張郎中籍遠寄長句開緘之日已及新秋因舉目前仰酬高韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f57b2df-7f47-4600-a68a-a3efb709ff40', '浙東元相公書歎梅雨鬱蒸之候因寄七言', '浙东元相公书歎梅雨鬱蒸之候因寄七言', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["稽山自與岐山別，何事連年鸑鷟飛。","百辟商量舊相入，九天祗候老臣歸。","平湖晚泛窺清鏡，高閣晨開掃翠微。","今日看書最惆悵，爲聞梅雨損朝衣。"]', '["稽山自與岐山別，何事連年鸑鷟飞。","百辟商量旧相入，九天祗候老臣归。","平湖晚泛窺清镜，高閣晨开掃翠微。","今日看书最惆悵，爲闻梅雨損朝衣。"]', '诗', 'shi', '', NULL, '浙東元相公書歎梅雨鬱蒸之候因寄七言 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90a8d61-6303-4c53-b681-db94090369ce', '酬嚴給事賀加五品兼簡同制水部李郎中', '酬嚴給事賀加五品兼簡同制水部李郎中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九天雨露傳青詔，八舍郎官換綠衣。","初佩銀魚隨仗入，宜乘白馬退朝歸。","彫盤賀喜開瑤席，綵筆題詩出鎖闈。","聞道水曹偏得意，霞朝霧夕有光輝。"]', '["九天雨露傳青詔，八舍郎官換綠衣。","初佩銀鱼隨仗入，宜乘白马退朝归。","彫盤賀喜开瑤席，綵笔題诗出鎖闈。","闻道水曹偏得意，霞朝霧夕有光輝。"]', '诗', 'shi', '', NULL, '酬嚴給事賀加五品兼簡同制水部李郎中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e767e376-1ab0-435f-97cc-2479f2e90729', '裴相公大學士見示答張秘書謝馬詩幷羣公屬和因命追作', '裴相公大学士见示答張秘书謝马诗幷羣公屬和因命追作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["草玄門戶少塵埃，丞相幷州寄馬來。","初自寒垣銜苜蓿，忽行幽徑破莓苔。","尋花緩轡威遲去，帶酒垂鞭躞蹀回。","不與王侯與詞客，知輕富貴重清才。"]', '["草玄门戶少塵埃，丞相幷州寄马来。","初自寒垣銜苜蓿，忽行幽徑破莓苔。","尋花緩轡威遲去，带酒垂鞭躞蹀回。","不與王侯與词客，知轻富貴重清才。"]', '诗', 'shi', '', NULL, '裴相公大學士見示答張秘書謝馬詩幷羣公屬和因命追作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d7f4579-c049-4917-8d35-e18b42f9e357', '奉和裴侍中將赴漢南留別座上諸公', '奉和裴侍中將赴漢南留別座上諸公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金貂曉出鳳池頭，玉節前臨南雍州。","暫輟洪鑪觀劍戟，還將大筆注春秋。","管弦席上留高韻，山水途中入勝遊。","峴首風煙看未足，便應重拜富民侯。"]', '["金貂晓出鳳池头，玉節前臨南雍州。","暫輟洪鑪观劍戟，還將大笔注春秋。","管弦席上留高韻，山水途中入勝游。","峴首风煙看未足，便應重拜富民侯。"]', '诗', 'shi', '', NULL, '奉和裴侍中將赴漢南留別座上諸公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7e7ffb-56ef-43fe-a140-b4a7a3d12cef', '和蘇郎中尋豐安里舊居寄主客張郎中', '和蘇郎中尋豐安里旧居寄主客張郎中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漳濱臥起恣閑遊，宣室徵還未白頭。","舊隱來尋通德里，新篇寫出畔牢愁。","池看科斗成文字，鳥聽提壺憶獻酬。","同學同年又同舍，許君雲路並華輈。"]', '["漳濱臥起恣闲游，宣室徵還未白头。","旧隐来尋通德里，新篇寫出畔牢愁。","池看科斗成文字，鸟听提壺憶獻酬。","同学同年又同舍，許君云路並华輈。"]', '诗', 'shi', '', NULL, '和蘇郎中尋豐安里舊居寄主客張郎中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e74ab5-16ae-4acf-b0b1-9329ebce61fe', '詶浙東李侍郎越州春晚即事長句', '詶浙东李侍郎越州春晚即事长句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["越中藹藹繁華地，秦望峰前禹穴西。","湖草初生邊鴈去，山花半謝杜鵑啼。","青油晝卷臨高閣，紅斾晴翻繞古堤。","明日漢庭徵舊德，老人爭出若耶溪。"]', '["越中藹藹繁华地，秦望峰前禹穴西。","湖草初生邊鴈去，山花半謝杜鵑啼。","青油晝卷臨高閣，紅斾晴翻繞古堤。","明日漢庭徵旧德，老人爭出若耶溪。"]', '诗', 'shi', '', NULL, '詶浙東李侍郎越州春晚即事長句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdea5f37-42c5-40e2-ad6c-f4531aaa4cba', '詶淮南牛相公述舊見貽', '詶淮南牛相公述旧见貽', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["少年曾忝漢庭臣，晚歲空餘老病身。","初見相如成賦日，尋爲丞相掃門人。","追思往事咨嗟久，喜奉清光笑語頻。","猶有登朝舊冠冕，待公三入拂埃塵。"]', '["少年曾忝漢庭臣，晚歲空餘老病身。","初见相如成賦日，尋爲丞相掃门人。","追思往事咨嗟久，喜奉清光笑語頻。","猶有登朝旧冠冕，待公三入拂埃塵。"]', '诗', 'shi', '', NULL, '詶淮南牛相公述舊見貽 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6b6e0a-c870-4e53-9f3c-00b4ea5e8129', '和僕射牛相公追感韋裴六相登庸皆四十餘未五十薨歿豈早榮枯之義今年將六十猶粗强健因親故勸酒率然成篇幷見寄之作', '和僕射牛相公追感韋裴六相登庸皆四十餘未五十薨歿豈早榮枯之義今年將六十猶粗强健因親故勸酒率然成篇幷见寄之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["坐鎮清朝獨殷然，閑徵故事數前賢。","用才同踐鈞衡地，稟氣終分大小年。","威鳳本池思泛泳，仙查舊路望回旋。","猶憐綺季深山裏，唯有松風與石田。"]', '["坐鎮清朝独殷然，闲徵故事數前賢。","用才同踐鈞衡地，稟氣終分大小年。","威鳳本池思泛泳，仙查旧路望回旋。","猶怜綺季深山裏，唯有松风與石田。"]', '诗', 'shi', '', NULL, '和僕射牛相公追感韋裴六相登庸皆四十餘未五十薨歿豈早榮枯之義今年將六十猶粗强健因親故勸酒率然成篇幷見寄之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a115d0-fda4-4d59-82d5-61c7735fe2b4', '和僕射牛相公以離闕庭七年班行親故亡歿十無一人再覩龍顏喜慶雖極感歎風燭能不愴然因成四韻幷示集賢中書二相公所和', '和僕射牛相公以離闕庭七年班行親故亡歿十無一人再覩龙顏喜慶雖極感歎风燭能不愴然因成四韻幷示集賢中书二相公所和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["久辭龍闕擁紅旗，喜見天顏拜赤墀。","三省英寮非舊侶，萬年芳樹長新枝。","交朋接武居仙院，幕客追風入鳳池。","雲母屏風即施設，可憐榮耀冠當時。"]', '["久辞龙闕擁紅旗，喜见天顏拜赤墀。","三省英寮非旧侶，万年芳樹长新枝。","交朋接武居仙院，幕客追风入鳳池。","云母屏风即施設，可怜榮耀冠當时。"]', '诗', 'shi', '', NULL, '和僕射牛相公以離闕庭七年班行親故亡歿十無一人再覩龍顏喜慶雖極感歎風燭能不愴然因成四韻幷示集賢中書二相公所和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737a7344-0f92-49ce-8839-52edc58da95a', '和僕射牛相公見示長句', '和僕射牛相公见示长句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["靜得天和興自濃，不緣宦達性靈慵。","大鵬六月有閑意，仙鶴千年無躁容。","流輩盡來多歎息，官班高後少過從。","唯應加築露臺上，賸見終南雲外峰。"]', '["静得天和兴自濃，不緣宦達性靈慵。","大鵬六月有闲意，仙鹤千年無躁容。","流輩尽来多歎息，官班高後少過從。","唯應加築露台上，賸见終南云外峰。"]', '诗', 'shi', '', NULL, '和僕射牛相公見示長句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db4fa5f6-b1b2-4a62-9904-608fe6415473', '和牛相公雨後寓懷見示', '和牛相公雨後寓懷见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金火交爭正抑揚，蕭蕭飛雨助清商。","曉看紈扇恩情薄，夜覺紗燈刻數長。","樹上早蟬才發響，庭中百草已無光。","當年富貴亦惆悵，何況悲翁髮似霜。"]', '["金火交爭正抑揚，蕭蕭飞雨助清商。","晓看紈扇恩情薄，夜覺紗灯刻數长。","樹上早蟬才發响，庭中百草已無光。","當年富貴亦惆悵，何況悲翁髮似霜。"]', '诗', 'shi', '', NULL, '和牛相公雨後寓懷見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05d236a-d968-40de-857e-66615ef6d98b', '和陳許王尚書酬白少傅侍郎長句因通簡汝洛舊遊之什', '和陳許王尚书酬白少傅侍郎长句因通簡汝洛旧游之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寥廓高翔不可追，風雲失路蹔相隨。","方同洛下書生詠，又見軍前大將旗。","雪裏命賓開玉帳，飲中請號駐金巵。","竹林一自王戎去，嵇阮雖貧興未衰。"]', '["寥廓高翔不可追，风云失路蹔相隨。","方同洛下书生詠，又见軍前大將旗。","雪裏命賓开玉帳，饮中請號駐金巵。","竹林一自王戎去，嵇阮雖貧兴未衰。"]', '诗', 'shi', '', NULL, '和陳許王尚書酬白少傅侍郎長句因通簡汝洛舊遊之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea4bb85-cbb9-4cc0-8743-4141422fc5fc', '和僕射牛相公寓言二首 一', '和僕射牛相公寓言二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["兩度竿頭立定誇，回眸舉袖拂青霞。","盡拋今日貴人樣，復振前朝名相家。","御史定來休直宿，尚書依舊趂參衙。","具瞻尊重誠無敵，猶憶洛陽千樹花。"]', '["兩度竿头立定誇，回眸舉袖拂青霞。","尽拋今日貴人樣，复振前朝名相家。","御史定来休直宿，尚书依旧趂參衙。","具瞻尊重誠無敵，猶憶洛陽千樹花。"]', '诗', 'shi', '', NULL, '和僕射牛相公寓言二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b26cbe9-324d-4de8-bc54-4b4beb2e7a3c', '和僕射牛相公寓言二首 二', '和僕射牛相公寓言二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["心如止水鑒常明，見盡人間萬物情。","鵰鶚騰空猶逞俊，驊騮嚙足自無驚。","時來未覺權爲祟，貴了方知退是榮。","只恐重重世緣在，事須三度副蒼生。"]', '["心如止水鑒常明，见尽人间万物情。","鵰鶚腾空猶逞俊，驊騮嚙足自無驚。","时来未覺權爲祟，貴了方知退是榮。","只恐重重世緣在，事須三度副蒼生。"]', '诗', 'shi', '', NULL, '和僕射牛相公寓言二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a7dae5-359f-43b0-a186-ee91402f5b8f', '詶太原狄尚書見寄', '詶太原狄尚书见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["家聲烜赫冠前賢，時無穹崇鎮北邊。","身上官銜如座主，幕中譚笑取同年。","幽幷俠少趨鞭弭，燕趙佳人奉管弦。","仍把天兵書號筆，遠題長句寄山川。"]', '["家声烜赫冠前賢，时無穹崇鎮北邊。","身上官銜如座主，幕中譚笑取同年。","幽幷俠少趨鞭弭，燕趙佳人奉管弦。","仍把天兵书號笔，远題长句寄山川。"]', '诗', 'shi', '', NULL, '詶太原狄尚書見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c986bb0e-352c-4c43-b6b9-762c0736b336', '詶宣州崔大夫見寄', '詶宣州崔大夫见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白衣曾拜漢尚書，今日恩光到敝廬。","再入龍樓稱綺季，應緣狗監說相如。","中郎南鎮權方重，內史高齋興有餘。","遙想敬亭春欲暮，百花飛盡柳花初。"]', '["白衣曾拜漢尚书，今日恩光到敝廬。","再入龙楼稱綺季，應緣狗監说相如。","中郎南鎮權方重，內史高斋兴有餘。","遙想敬亭春欲暮，百花飞尽柳花初。"]', '诗', 'shi', '', NULL, '詶宣州崔大夫見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7d13c2-5405-4500-8b69-7e72e724070a', '詶皇甫十少尹暮秋久雨喜晴有懷見示', '詶皇甫十少尹暮秋久雨喜晴有懷见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雨餘獨坐卷簾帷，便得詩人喜霽詩。","搖落從來長年感，慘舒偏是病身知。","掃開雲霧呈光景，流盡潢汙見路岐。","何況菊香新酒熟，神州司馬好狂時。"]', '["雨餘独坐卷簾帷，便得诗人喜霽诗。","搖落從来长年感，慘舒偏是病身知。","掃开云霧呈光景，流尽潢汙见路岐。","何況菊香新酒熟，神州司马好狂时。"]', '诗', 'shi', '', NULL, '詶皇甫十少尹暮秋久雨喜晴有懷見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a11fbb0-0fa3-436a-a778-a2095d3fb85e', '再授連州至衡陽酬柳柳州贈別', '再授連州至衡陽酬柳柳州贈別', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["去國十年同赴召，渡湘千里又分岐。","重臨事異黃丞相，三黜名慙柳士師。","歸目併隨回鴈盡，愁腸正遇斷猿時。","桂江東過連山下，相望長吟有所思。"]', '["去国十年同赴召，渡湘千里又分岐。","重臨事異黄丞相，三黜名慙柳士師。","归目併隨回鴈尽，愁腸正遇斷猿时。","桂江东過連山下，相望长吟有所思。"]', '诗', 'shi', '', NULL, '再授連州至衡陽酬柳柳州贈別 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8038adf6-235d-4ad7-bec5-ad311f918d66', '望夫山', '望夫山', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何代提戈去不還，獨留形影白雲間。","肌膚銷盡雪霜色，羅綺點成苔蘚斑。","江燕不能傳遠信，野花空解妒愁顏。","近來豈少征人婦，笑採蘼蕪上北山。"]', '["何代提戈去不還，独留形影白云间。","肌膚銷尽雪霜色，羅綺点成苔蘚斑。","江燕不能傳远信，野花空解妒愁顏。","近来豈少征人婦，笑採蘼蕪上北山。"]', '诗', 'shi', '', NULL, '望夫山 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f1cd0f-88d7-42bb-ab45-e3a1acf3bf79', '懷妓 一', '懷妓 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉釵重合兩無緣，魚在深潭鶴在天。","得意紫鸞休舞鏡，能言青鳥罷銜牋。","金盆已覆難收水，玉軫長拋不續弦。","若向蘼蕪山下過，遙將紅淚灑窮泉。"]', '["玉釵重合兩無緣，鱼在深潭鹤在天。","得意紫鸾休舞镜，能言青鸟罷銜牋。","金盆已覆难收水，玉軫长拋不續弦。","若向蘼蕪山下過，遙將紅泪灑窮泉。"]', '诗', 'shi', '', NULL, '懷妓 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77dfc220-7dd8-443d-a125-e7a0358d2631', '懷妓 二', '懷妓 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鸞飛遠樹棲何處，鳳得新巢想稱心。","紅壁尚留香漠漠，碧雲初斷信沈沈。","情知點污投泥玉，猶自經營買笑金。","從此山頭似人石，丈夫形狀淚痕深。"]', '["鸾飞远樹棲何处，鳳得新巢想稱心。","紅壁尚留香漠漠，碧云初斷信沈沈。","情知点污投泥玉，猶自經營買笑金。","從此山头似人石，丈夫形狀泪痕深。"]', '诗', 'shi', '', NULL, '懷妓 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66570a4c-477c-42eb-a646-e01a06b89a5f', '懷妓 三', '懷妓 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["但曾行處遍尋看，雖是生離死一般。","買笑樹邊花已老，畫眉窗下月猶殘。","雲藏巫峽音容斷，路隔星橋過往難。","莫怪詩成無淚滴，盡傾東海也須乾。"]', '["但曾行处遍尋看，雖是生離死一般。","買笑樹邊花已老，畫眉窗下月猶殘。","云藏巫峽音容斷，路隔星橋過往难。","莫怪诗成無泪滴，尽傾东海也須乾。"]', '诗', 'shi', '', NULL, '懷妓 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf3590b-e5ba-4bef-ac00-2e332ddf8069', '懷妓 四', '懷妓 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三山不見海沈沈，豈有仙蹤更可尋。","青鳥去時雲路斷，姮娥歸處月宮深。","紗窗遙想春相憶，書幌誰憐夜獨吟。","料得夜來天上鏡，只應偏照兩人心。"]', '["三山不见海沈沈，豈有仙蹤更可尋。","青鸟去时云路斷，姮娥归处月宮深。","紗窗遙想春相憶，书幌誰怜夜独吟。","料得夜来天上镜，只應偏照兩人心。"]', '诗', 'shi', '', NULL, '懷妓 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22570e9e-e054-45fa-b91f-c383e8df2fba', '荅東陽于令寒碧圖詩', '荅东陽于令寒碧圖诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["東陽本是佳山水，何況曾經沈隱侯。","化得邦人解吟詠，如今縣令亦風流。","新開譚洞疑仙境，遠寫丹青到雍州。","落在尋常畫師手，猶能三伏凜生秋。"]', '["东陽本是佳山水，何況曾經沈隐侯。","化得邦人解吟詠，如今縣令亦风流。","新开譚洞疑仙境，远寫丹青到雍州。","落在尋常畫師手，猶能三伏凜生秋。"]', '诗', 'shi', '', NULL, '荅東陽于令寒碧圖詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1bd43e7-6c89-4d49-a597-4b4fa2bb2ab4', '麻姑山', '麻姑山', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾遊仙蹟見豐碑，除却麻姑更有誰。","雲蓋青山龍臥處，日臨丹洞鶴歸時。","霜凝上界花開晚，月冷中天果熟遲。","人到便須拋世事，稻田還儗種靈芝。"]', '["曾游仙蹟见豐碑，除却麻姑更有誰。","云蓋青山龙臥处，日臨丹洞鹤归时。","霜凝上界花开晚，月冷中天果熟遲。","人到便須拋世事，稻田還儗種靈芝。"]', '诗', 'shi', '', NULL, '麻姑山 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0982c5f-6245-45bb-9a7a-21e07a0c4622', '自江陵沿流道中', '自江陵沿流道中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三千三百西江水，自古如今要路津。","月夜歌謠有漁父，風天氣色屬商人。","沙村好處多逢寺，山葉紅時覺勝春。","行到南朝征戰地，古來名將盡爲神。"]', '["三千三百西江水，自古如今要路津。","月夜歌謠有漁父，风天氣色屬商人。","沙村好处多逢寺，山葉紅时覺勝春。","行到南朝征戰地，古来名將尽爲神。"]', '诗', 'shi', '', NULL, '自江陵沿流道中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8b2289-5900-415a-bf1d-534118dcac56', '別夔州官吏', '別夔州官吏', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三年楚國巴城守，一去揚州揚子津。","青帳聯延喧驛步，白頭俯傴到江濱。","巫山暮色常含雨，峽水秋來不恐人。","惟有九歌詞數首，里中留與賽蠻神。"]', '["三年楚国巴城守，一去揚州揚子津。","青帳聯延喧驛步，白头俯傴到江濱。","巫山暮色常含雨，峽水秋来不恐人。","惟有九歌词數首，里中留與賽蠻神。"]', '诗', 'shi', '', NULL, '別夔州官吏 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950ce4d5-d7b9-47ab-aee8-3a72de4c4143', '魚復江中', '鱼复江中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["扁舟盡室貧相逐，白髮藏冠鑷更加。","遠水自澄終日綠，晴林長落過春花。","客情浩蕩逢鄉語，詩意留連重物華。","風檣好住貪程去，斜日青帘背酒家。"]', '["扁舟尽室貧相逐，白髮藏冠鑷更加。","远水自澄終日綠，晴林长落過春花。","客情浩蕩逢乡語，诗意留連重物华。","风檣好住貪程去，斜日青帘背酒家。"]', '诗', 'shi', '', NULL, '魚復江中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4bf89a1-d3e1-418c-abdd-25129c326348', '巫山神女廟', '巫山神女廟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巫山十二鬱蒼蒼，片石亭亭號女郎。","曉霧乍開疑卷幔，山花欲謝似殘妝。","星河好夜聞清佩，雲雨歸時帶異香。","何事神仙九天上，人間來就楚襄王。"]', '["巫山十二鬱蒼蒼，片石亭亭號女郎。","晓霧乍开疑卷幔，山花欲謝似殘妝。","星河好夜闻清佩，云雨归时带異香。","何事神仙九天上，人间来就楚襄王。"]', '诗', 'shi', '', NULL, '巫山神女廟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3d125a-e9b0-46d1-8d69-a2585824a34e', '柳絮', '柳絮', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["飄颺南陌起東鄰，漠漠濛濛暗度春。","花巷暖隨輕舞蝶，玉樓晴拂豔妝人。","縈迴謝女題詩筆，點綴陶公漉酒巾。","何處好風偏似雪，隋河堤上古江津。"]', '["飄颺南陌起东鄰，漠漠濛濛暗度春。","花巷暖隨轻舞蝶，玉楼晴拂豔妝人。","縈迴謝女題诗笔，点綴陶公漉酒巾。","何处好风偏似雪，隋河堤上古江津。"]', '诗', 'shi', '', NULL, '柳絮 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ad5829-d0c0-43b7-9d35-971dc706e552', '贈同年陳長史員外', '贈同年陳长史員外', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["明州長史外臺郎，憶昔同年翰墨場。","一自分襟多歲月，相逢滿眼是淒涼。","推賢有愧韓安國，論舊唯存盛孝章。","所歎謬遊東閣下，看君無計出恓惶。"]', '["明州长史外台郎，憶昔同年翰墨場。","一自分襟多歲月，相逢满眼是淒涼。","推賢有愧韓安国，論旧唯存盛孝章。","所歎謬游东閣下，看君無計出恓惶。"]', '诗', 'shi', '', NULL, '贈同年陳長史員外 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1b03d2-e68e-4f17-ae92-f1a92f40551e', '送周魯儒赴舉詩', '送周魯儒赴舉诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["宋日營陽內史孫，因家占得九疑村。","童心便有愛書癖，手指今餘把筆痕。","自握蛇珠辭白屋，欲憑雞卜謁金門。","若逢廣坐問羊酪，從此知名在一言。"]', '["宋日營陽內史孫，因家占得九疑村。","童心便有愛书癖，手指今餘把笔痕。","自握蛇珠辞白屋，欲憑雞卜謁金门。","若逢廣坐问羊酪，從此知名在一言。"]', '诗', 'shi', '', NULL, '送周魯儒赴舉詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6914b9-8bf8-49ff-a94a-8e547693c129', '送曹璩歸越中舊隱詩', '送曹璩归越中旧隐诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["行盡瀟湘萬里餘，少逢知己憶吾廬。","數間茅屋閒臨水，一盞秋燈夜讀書。","地遠何當隨計吏，策成終自詣公車。","剡中若問連州事，唯有千山畫不如。"]', '["行尽瀟湘万里餘，少逢知己憶吾廬。","數间茅屋閒臨水，一盞秋灯夜读书。","地远何當隨計吏，策成終自詣公车。","剡中若问連州事，唯有千山畫不如。"]', '诗', 'shi', '', NULL, '送曹璩歸越中舊隱詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2842fcb0-0112-40e3-bdf3-554fd0d310eb', '白鷹', '白鷹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["毛羽斒斕白紵裁，馬前擎出不驚猜。","輕拋一點入雲去，喝殺三聲掠地來。","綠玉觜攢雞腦破，玄金爪擘兔心開。","都緣解搦生靈物，所以人人道俊哉。"]', '["毛羽斒斕白紵裁，马前擎出不驚猜。","轻拋一点入云去，喝殺三声掠地来。","綠玉觜攢雞腦破，玄金爪擘兔心开。","都緣解搦生靈物，所以人人道俊哉。"]', '诗', 'shi', '', NULL, '白鷹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17f0836f-c3eb-470c-bcb1-d906e72592ad', '送工部張侍郎入蕃弔祭', '送工部張侍郎入蕃弔祭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["月窟賓諸夏，雲官降九天。","飾終鄰好重，錫命禮容全。","水咽猶登隴，沙鳴稍極邊。","路因乘驛近，志爲飲冰堅。","毳帳差池見，烏旗搖曳前。","歸來賜金石，榮耀自編年。"]', '["月窟賓諸夏，云官降九天。","飾終鄰好重，錫命禮容全。","水咽猶登隴，沙鳴稍極邊。","路因乘驛近，志爲饮冰堅。","毳帳差池见，烏旗搖曳前。","归来賜金石，榮耀自編年。"]', '诗', 'shi', '', NULL, '送工部張侍郎入蕃弔祭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95b17c8-b7f3-4fd2-ac2e-e23045fe1b5c', '早秋送臺院楊侍御歸朝', '早秋送台院楊侍御归朝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["仙署棣華春，當時已絕倫。","今朝丹闕下，更入白眉人。","重振高陽族，分居要路津。","一門科第足，五府辟書頻。","鷙鳥得秋氣，法星懸火旻。","聖朝寰海靜，所至不埋輪。"]', '["仙署棣华春，當时已絕倫。","今朝丹闕下，更入白眉人。","重振高陽族，分居要路津。","一门科第足，五府辟书頻。","鷙鸟得秋氣，法星懸火旻。","聖朝寰海静，所至不埋輪。"]', '诗', 'shi', '', NULL, '早秋送臺院楊侍御歸朝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a891ddeb-0dd1-486f-9ea1-54682101004c', '送陸侍御歸淮南使府五韻', '送陸侍御归淮南使府五韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江左重詩篇，陸生名久傳。","鳳城來已熟，羊酪不嫌羶。","歸路芙蓉府，離堂玳瑁筵。","泰山呈臘雪，隋柳布新年。","曾忝揚州薦，因君達短牋。"]', '["江左重诗篇，陸生名久傳。","鳳城来已熟，羊酪不嫌羶。","归路芙蓉府，離堂玳瑁筵。","泰山呈臘雪，隋柳布新年。","曾忝揚州薦，因君達短牋。"]', '诗', 'shi', '', NULL, '送陸侍御歸淮南使府五韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0914a95-cdd3-4cec-96b1-6194738960fc', '送令狐相公自僕射出鎮南梁', '送令狐相公自僕射出鎮南梁', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["夏木正陰成，戎裝出帝京。","沾襟辭闕淚，回首別鄉情。","雲樹褒中路，風煙漢上城。","前旌傳谷去，後騎踏橋聲。","久領鴛行重，無嫌虎綬輕。","終提一麾去，再入福蒼生。"]', '["夏木正陰成，戎裝出帝京。","沾襟辞闕泪，回首別乡情。","云樹褒中路，风煙漢上城。","前旌傳谷去，後騎踏橋声。","久領鴛行重，無嫌虎綬轻。","終提一麾去，再入福蒼生。"]', '诗', 'shi', '', NULL, '送令狐相公自僕射出鎮南梁 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7fd02c4-d0a5-4aa0-a74c-c5262963531e', '奉送裴司徒令公自東都留守再命太原', '奉送裴司徒令公自东都留守再命太原', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["星使出關東，兵符賜上公。","山河歸舊國，管籥換離宮。","行色旌旗動，軍聲鼓角雄。","愛棠餘故吏，騎竹見新童。","漢壘三秋靜，胡沙萬里空。","其如天下望，旦夕詠清風。"]', '["星使出关东，兵符賜上公。","山河归旧国，管籥換離宮。","行色旌旗动，軍声鼓角雄。","愛棠餘故吏，騎竹见新童。","漢壘三秋静，胡沙万里空。","其如天下望，旦夕詠清风。"]', '诗', 'shi', '', NULL, '奉送裴司徒令公自東都留守再命太原 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e6b9e1-398b-4105-9039-a9076d0431fc', '海陽湖別浩初師', '海陽湖別浩初師', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["近郭看殊境，獨遊常鮮懽。","逢君駐緇錫，觀貌稱林巒。","湖滿景方霽，野香春未闌。","愛泉移席近，聞石輟棊看。","風止松猶韻，花繁露未乾。","橋形出樹曲，巖影落池寒別路千嶂裏，詩情暮雲端。","他年買山處，似此得隳官。"]', '["近郭看殊境，独游常鲜懽。","逢君駐緇錫，观貌稱林巒。","湖满景方霽，野香春未闌。","愛泉移席近，闻石輟棊看。","风止松猶韻，花繁露未乾。","橋形出樹曲，巖影落池寒別路千嶂裏，诗情暮云端。","他年買山处，似此得隳官。"]', '诗', 'shi', '', NULL, '海陽湖別浩初師 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a901da4c-d0ab-4c7a-a389-1d4ec74d3523', '許給事見示哭工部劉尚書詩因命同作', '許給事见示哭工部劉尚书诗因命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢室賢王後，孔門高第人。","濟時成國器，樂道任天真。","特達圭無玷，堅貞竹有筠。","總戎寬得衆，市義貴能貧。","護塞無南牧，馳心拱北辰。","乞身來闕下，賜告臥漳濱。","榮耀初題劒，清羸已拖紳。","宮星徒列位，隙日不回輪。","自昔追飛侶，今爲侍從臣。","素弦哀已絕，青簡歎猶新。","未遂揮金樂，空悲撤瑟晨。","淒涼竹林下，無復見清塵。"]', '["漢室賢王後，孔门高第人。","濟时成国器，乐道任天真。","特達圭無玷，堅貞竹有筠。","總戎寬得衆，市義貴能貧。","護塞無南牧，驰心拱北辰。","乞身来闕下，賜告臥漳濱。","榮耀初題劒，清羸已拖紳。","宮星徒列位，隙日不回輪。","自昔追飞侶，今爲侍從臣。","素弦哀已絕，青簡歎猶新。","未遂揮金乐，空悲撤瑟晨。","淒涼竹林下，無复见清塵。"]', '诗', 'shi', '', NULL, '許給事見示哭工部劉尚書詩因命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e27c564-356b-4c7b-8594-861f03d55cfc', '武陵書懷五十韻', '武陵书懷五十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["西漢開支郡，南朝號戚藩。","四封當列宿，百雉俯清沅。","高岸朝霞合，驚湍激箭奔。","積陰春暗度，將霽霧先昏。","俗尚東皇祀，謠傳義帝冤。","桃花迷隱跡，楝葉慰忠魂。","戶算資漁獵，鄉豪恃子孫。","照山畬火動，踏月俚歌喧。","擁檝舟爲市，連甍竹覆軒。","披沙金粟見，拾羽翠翹翻。","茗折蒼溪秀，蘋生枉渚暄。","禽驚格磔起，魚戲噞喁繁。","沈約臺榭故，李衡墟落存。","湘靈悲鼓瑟，泉客泣酬恩。","露變蒹葭浦，星懸橘柚村。","虎咆空野震，鼉作滿川渾。","鄰里皆遷客，兒童習左言。","炎天無冽井，霜月見芳蓀。","清白家傳遠，詩書志所敦。","列科叨甲乙，從宦出丘樊。","結友心多契，馳聲氣尚吞。","士安曾重賦，元禮許登門。","草檄嫖姚幕，巡兵戊己屯。","築臺先自隗，送客獨留髠。","遂結王畿綬，來觀衢室罇。","鳶飛入鷹隼，魚目儷璵璠。","曉燭羅馳道，朝陽闢帝閽。","王正會夷夏，月朔盛旗旛。","獨立當瑤闕，傳呵步紫垣。","按章清犴獄，視祭潔蘋蘩。","御曆昌期遠，傳家寶祚蕃。","繇文光夏啓，神教畏軒轅。","內禪因天性，雄圖授化元。","繼明懸日月，出震統乾坤。","大孝三朝備，洪恩九族惇。","百川宗渤澥，五岳輔崑崙。","何幸逢休運，微班識至尊。","校緍資筦榷，復土奉山園。","一失貴人意，徒聞太學論。","直廬辭錦帳，遠守愧朱幡。","巢幕方猶燕，搶榆尚笑鯤。","邅迴過荆楚，流落感涼溫。","旅望花無色，愁心醉不惛。","春江千里草，暮雨一聲猿。","問卜安冥數，看方理病源。","帶賒衣改製，塵澀劒成痕。","三秀悲中散，二毛傷虎賁。","來憂禦魑魅，歸願牧雞豚。","就日秦京遠，臨風楚奏煩。","南登無灞岸，旦夕上高原。"]', '["西漢开支郡，南朝號戚藩。","四封當列宿，百雉俯清沅。","高岸朝霞合，驚湍激箭奔。","積陰春暗度，將霽霧先昏。","俗尚东皇祀，謠傳義帝冤。","桃花迷隐跡，楝葉慰忠魂。","戶算資漁獵，乡豪恃子孫。","照山畬火动，踏月俚歌喧。","擁檝舟爲市，連甍竹覆軒。","披沙金粟见，拾羽翠翹翻。","茗折蒼溪秀，蘋生枉渚暄。","禽驚格磔起，鱼戲噞喁繁。","沈約台榭故，李衡墟落存。","湘靈悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星懸橘柚村。","虎咆空野震，鼉作满川渾。","鄰里皆遷客，兒童習左言。","炎天無冽井，霜月见芳蓀。","清白家傳远，诗书志所敦。","列科叨甲乙，從宦出丘樊。","結友心多契，驰声氣尚吞。","士安曾重賦，元禮許登门。","草檄嫖姚幕，巡兵戊己屯。","築台先自隗，送客独留髠。","遂結王畿綬，来观衢室罇。","鳶飞入鷹隼，鱼目儷璵璠。","晓燭羅驰道，朝陽闢帝閽。","王正會夷夏，月朔盛旗旛。","独立當瑤闕，傳呵步紫垣。","按章清犴獄，視祭潔蘋蘩。","御曆昌期远，傳家寶祚蕃。","繇文光夏啓，神教畏軒轅。","內禪因天性，雄圖授化元。","繼明懸日月，出震統乾坤。","大孝三朝備，洪恩九族惇。","百川宗渤澥，五岳輔崑崙。","何幸逢休運，微班識至尊。","校緍資筦榷，复土奉山园。","一失貴人意，徒闻太学論。","直廬辞錦帳，远守愧朱幡。","巢幕方猶燕，搶榆尚笑鯤。","邅迴過荆楚，流落感涼溫。","旅望花無色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥數，看方理病源。","带賒衣改製，塵澀劒成痕。","三秀悲中散，二毛傷虎賁。","来憂禦魑魅，归願牧雞豚。","就日秦京远，臨风楚奏煩。","南登無灞岸，旦夕上高原。"]', '诗', 'shi', '', NULL, '武陵書懷五十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5805a4c4-b41a-4876-9fe5-7a2f3affa462', '早秋集賢院即事', '早秋集賢院即事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金數已三伏，火星正西流。","樹含秋露曉，閣倚碧天秋。","灰琯應新律，銅壺添夜籌。","商飆從朔塞，爽氣入神州。","蕙草香書殿，槐花點御溝。","山明真色見，水靜濁煙收。","早歲忝華省，再來成白頭。","幸依羣玉府，末路尚瀛洲。"]', '["金數已三伏，火星正西流。","樹含秋露晓，閣倚碧天秋。","灰琯應新律，銅壺添夜籌。","商飆從朔塞，爽氣入神州。","蕙草香书殿，槐花点御溝。","山明真色见，水静濁煙收。","早歲忝华省，再来成白头。","幸依羣玉府，末路尚瀛洲。"]', '诗', 'shi', '', NULL, '早秋集賢院即事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e0a730-a944-41ec-bccd-5c9169cda69a', '奉和吏部楊尚書太常李卿二相公策免後即事述懷贈答十韻', '奉和吏部楊尚书太常李卿二相公策免後即事述懷贈答十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["文雅關西族，衣冠趙北都。","有聲真漢相，無纇勝隋珠。","當軸龍爲友，臨池鳳不孤。","九天開內殿，百辟看晨趨。","誡滿澄欹器，成功別大罏。","餘芳在公論，積慶是神扶。","步武離台席，徊翔集帝梧。","詮材秉秦鏡，典樂去齊竽。","瀟灑風塵外，逢迎詩酒徒。","唯應待華誥，更食萬錢廚。"]', '["文雅关西族，衣冠趙北都。","有声真漢相，無纇勝隋珠。","當軸龙爲友，臨池鳳不孤。","九天开內殿，百辟看晨趨。","誡满澄欹器，成功別大罏。","餘芳在公論，積慶是神扶。","步武離台席，徊翔集帝梧。","詮材秉秦镜，典乐去齊竽。","瀟灑风塵外，逢迎诗酒徒。","唯應待华誥，更食万錢廚。"]', '诗', 'shi', '', NULL, '奉和吏部楊尚書太常李卿二相公策免後即事述懷贈答十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9d9842-af13-4e4a-9973-63799a2ff132', '晚歲登武陵城顧望水陸悵然有作', '晚歲登武陵城顧望水陸悵然有作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["星象承烏翼，蠻陬想犬牙。","俚人祠竹節，仙洞閉桃花。","城基歷漢魏，江源自賨巴。","華表廖王墓，菜地黃瓊家。","霜輕菊秀晚，石淺水紋斜。","樵音繞故壘，汲路明寒沙。","清風稍改葉，盧橘始含葩。","野橋過驛騎，叢祠發逈笳。","跳鱗避舉網，倦鳥寄行楂。","路塵高出樹，山火遠連霞。","夕曛轉赤岸，浮靄起蒼葭。","軋軋渡水槳，連連赴林鴉。","呌閽道非遠，賜環期自賒。","孤臣本危涕，喬木在天涯。"]', '["星象承烏翼，蠻陬想犬牙。","俚人祠竹節，仙洞閉桃花。","城基歷漢魏，江源自賨巴。","华表廖王墓，菜地黄瓊家。","霜轻菊秀晚，石淺水紋斜。","樵音繞故壘，汲路明寒沙。","清风稍改葉，盧橘始含葩。","野橋過驛騎，叢祠發逈笳。","跳鱗避舉網，倦鸟寄行楂。","路塵高出樹，山火远連霞。","夕曛轉赤岸，浮靄起蒼葭。","軋軋渡水槳，連連赴林鴉。","呌閽道非远，賜环期自賒。","孤臣本危涕，喬木在天涯。"]', '诗', 'shi', '', NULL, '晚歲登武陵城顧望水陸悵然有作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6a36c8-34df-416d-bc29-0c07dcf5866f', '罷郡歸洛陽寄友人', '罷郡归洛陽寄友人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["遠謫年猶少，初歸鬢已衰。","門閑故吏去，室靜老僧期。","不見蜘蛛集，頻爲佝僂欺。","穎微囊未出，寒甚谷難吹。","濩落唯心在，平生有己知。","商歌夜深後，聽者竟爲誰。"]', '["远謫年猶少，初归鬢已衰。","门闲故吏去，室静老僧期。","不见蜘蛛集，頻爲佝僂欺。","穎微囊未出，寒甚谷难吹。","濩落唯心在，平生有己知。","商歌夜深後，听者竟爲誰。"]', '诗', 'shi', '', NULL, '罷郡歸洛陽寄友人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f74fe9b-46ed-42fd-9d5c-a2c6ec586409', '經伏波神祠', '經伏波神祠', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蒙蒙篁竹下，有路上壺頭。","漢壘麏鼯鬬，蠻溪霧雨愁。","懷人敬遺像，閱世指東流。","自負霸王略，安知恩澤侯。","鄉園辭石柱，筋力盡炎洲。","一以功名累，飜思馬少游。"]', '["蒙蒙篁竹下，有路上壺头。","漢壘麏鼯鬬，蠻溪霧雨愁。","懷人敬遺像，閱世指东流。","自負霸王略，安知恩澤侯。","乡园辞石柱，筋力尽炎洲。","一以功名累，飜思马少游。"]', '诗', 'shi', '', NULL, '經伏波神祠 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e609f3-eab1-4cc7-84fd-f02aae45291b', '和汴州令狐相公到鎮改月偶書所懷', '和汴州令狐相公到鎮改月偶书所懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["受脤新梁苑，和羹舊傅巖。","援毫動星宿，垂釣取韜鈐。","赫奕三川至，歡呼百姓瞻。","綠油貔虎擁，青紙鳳皇銜。","外壘曾無警，中廚亦罷監。","推誠人自服，去殺令逾嚴。","赳赳容皆飾，幡幡口盡鉗。","爲兄憐庾翼，選壻得蕭咸。","鬱倔咽喉地，駢臻水陸兼。","度橋鳴紺幰，入肆颺雲帆。","端月當中氣，東風應遠占。","管弦喧夜景，燈燭掩寒蟾。","酒每傾三雅，書能發百函。","詞人羞布鼓，遠客獻貂襜。","歌榭白團扇，舞筵金縷衫。","旌旗遙一簇，舄履近相攙。","花樹當朱閣，晴河逼翠簾。","衣風飄靉靆，燭淚滴巉巖。","玉斝虛頻易，金爐暖更添。","映鐶窺豔豔，隔袖見纖纖。","謝傅何由接，桓伊定不凡。","應憐郡齋老，旦夕鑷霜䫇。"]', '["受脤新梁苑，和羹旧傅巖。","援毫动星宿，垂釣取韜鈐。","赫奕三川至，歡呼百姓瞻。","綠油貔虎擁，青紙鳳皇銜。","外壘曾無警，中廚亦罷監。","推誠人自服，去殺令逾嚴。","赳赳容皆飾，幡幡口尽鉗。","爲兄怜庾翼，選壻得蕭咸。","鬱倔咽喉地，駢臻水陸兼。","度橋鳴紺幰，入肆颺云帆。","端月當中氣，东风應远占。","管弦喧夜景，灯燭掩寒蟾。","酒每傾三雅，书能發百函。","词人羞布鼓，远客獻貂襜。","歌榭白團扇，舞筵金縷衫。","旌旗遙一簇，舄履近相攙。","花樹當朱閣，晴河逼翠簾。","衣风飄靉靆，燭泪滴巉巖。","玉斝虛頻易，金爐暖更添。","映鐶窺豔豔，隔袖见纖纖。","謝傅何由接，桓伊定不凡。","應怜郡斋老，旦夕鑷霜䫇。"]', '诗', 'shi', '', NULL, '和汴州令狐相公到鎮改月偶書所懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc15312-ebe5-4141-8679-e2fa6217eeb0', '遙賀白賓客分司初到洛中戲呈馮尹', '遙賀白賓客分司初到洛中戲呈馮尹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["西辭望苑去，東占洛陽才。","度嶺無愁思，看山不懊來。","冥鴻何所慕，遼鶴乍飛廻。","洗竹通新逕，攜琴上舊臺。","塵埃長者撤，風月故人杯。","聞道龍門峻，還因上客開。"]', '["西辞望苑去，东占洛陽才。","度嶺無愁思，看山不懊来。","冥鴻何所慕，遼鹤乍飞廻。","洗竹通新逕，携琴上旧台。","塵埃长者撤，风月故人杯。","闻道龙门峻，還因上客开。"]', '诗', 'shi', '', NULL, '遙賀白賓客分司初到洛中戲呈馮尹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be76d833-412a-44f8-9871-6153103c7b5a', '白侍郎大尹自河南寄示池北新葺水齋即事招賓十四韻兼命同作', '白侍郎大尹自河南寄示池北新葺水斋即事招賓十四韻兼命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["公府有高政，新齋池上開。","再吟佳句後，一似畫圖來。","結搆疎林下，夤緣曲岸隈。","綠波穿戶牖，碧甃疊瓊瓌。","幽異當軒滿，清光繞砌廻。","潭心澄晚鏡，渠口起晴雷。","瑤草緣堤種，松煙上島栽。","遊魚驚撥刺，浴鷺喜毰毸。","爲客烹林笋，因僧採石苔。","酒缾常不罄，書案任成堆。","簷外青雀舫，坐中鸚鵡杯。","蒲根抽九節，蓮萼捧重臺。","芳訊此時到，勝遊何日陪。","共譏吳太守，自占洛陽才。"]', '["公府有高政，新斋池上开。","再吟佳句後，一似畫圖来。","結搆疎林下，夤緣曲岸隈。","綠波穿戶牖，碧甃叠瓊瓌。","幽異當軒满，清光繞砌廻。","潭心澄晚镜，渠口起晴雷。","瑤草緣堤種，松煙上島栽。","游鱼驚撥刺，浴鷺喜毰毸。","爲客烹林笋，因僧採石苔。","酒缾常不罄，书案任成堆。","簷外青雀舫，坐中鸚鵡杯。","蒲根抽九節，蓮萼捧重台。","芳訊此时到，勝游何日陪。","共譏吳太守，自占洛陽才。"]', '诗', 'shi', '', NULL, '白侍郎大尹自河南寄示池北新葺水齋即事招賓十四韻兼命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edca8c83-0380-4c83-af64-371da14c6611', '和令狐相公謝太原李侍中寄蒲桃', '和令狐相公謝太原李侍中寄蒲桃', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["珍果出西域，移根到北方。","昔年隨漢使，今日寄梁王。","上相芳緘至，行臺綺席張。","魚鱗含宿潤，馬乳帶殘霜。","染指鉛粉膩，滿喉甘露香。","醞成十日酒，味敵五雲槳。","咀嚼停金盞，稱嗟響畫堂。","慙非末至客，不得一枝嘗。"]', '["珍果出西域，移根到北方。","昔年隨漢使，今日寄梁王。","上相芳緘至，行台綺席張。","鱼鱗含宿潤，马乳带殘霜。","染指鉛粉膩，满喉甘露香。","醞成十日酒，味敵五云槳。","咀嚼停金盞，稱嗟响畫堂。","慙非末至客，不得一枝嘗。"]', '诗', 'shi', '', NULL, '和令狐相公謝太原李侍中寄蒲桃 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b282727-8bff-446e-8add-a32cfba7671d', '和令狐相公玩白菊', '和令狐相公玩白菊', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["家家菊盡黃，梁國獨如霜。","瑩靜真琪樹，分明對玉堂。","仙人披雪氅，素女不紅妝。","粉蝶來難見，麻衣拂更香。","向風搖羽扇，含露滴瓊槳。","高豔遮銀井，繁枝覆象牀。","桂叢慙竝發，梅蘂妬先芳。","一入瑤華詠，從茲播樂章。"]', '["家家菊尽黄，梁国独如霜。","瑩静真琪樹，分明对玉堂。","仙人披雪氅，素女不紅妝。","粉蝶来难见，麻衣拂更香。","向风搖羽扇，含露滴瓊槳。","高豔遮銀井，繁枝覆象牀。","桂叢慙竝發，梅蘂妬先芳。","一入瑤华詠，從茲播乐章。"]', '诗', 'shi', '', NULL, '和令狐相公玩白菊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('047e6adc-a25f-4d4a-93bc-26d6cb1c21b3', '令狐相公見示新栽蕙蘭二草之什兼命同作', '令狐相公见示新栽蕙蘭二草之什兼命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["上國庭前草，移來漢水潯。","朱門雖易地，玉樹有餘陰。","豔彩凝還泛，清香絕復尋。","光華童子佩，柔軟美人心。","惜晚含遠思，賞幽空獨吟。","寄言知音者，一奏風中琴。"]', '["上国庭前草，移来漢水潯。","朱门雖易地，玉樹有餘陰。","豔彩凝還泛，清香絕复尋。","光华童子佩，柔軟美人心。","惜晚含远思，賞幽空独吟。","寄言知音者，一奏风中琴。"]', '诗', 'shi', '', NULL, '令狐相公見示新栽蕙蘭二草之什兼命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4009be3-4a63-477a-be72-0670f45c6757', '和令狐相公南齋小讌聽阮咸', '和令狐相公南斋小讌听阮咸', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["阮巷久蕪沈，四弦有遺音。","雅聲發蘭室，遠思含竹林。","座絕衆賓語，庭移芳樹陰。","飛觴助真氣，寂聽無流心。","影似白團扇，調諧朱弦琴。","一毫不平意，幽怨古猶今。"]', '["阮巷久蕪沈，四弦有遺音。","雅声發蘭室，远思含竹林。","座絕衆賓語，庭移芳樹陰。","飞觴助真氣，寂听無流心。","影似白團扇，調諧朱弦琴。","一毫不平意，幽怨古猶今。"]', '诗', 'shi', '', NULL, '和令狐相公南齋小讌聽阮咸 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5741ba-0a9b-4a04-9ea8-fed55e797055', '和令狐相公九日對黃白二菊花見懷', '和令狐相公九日对黄白二菊花见懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["素萼迎寒秀，金英帶露香。","繁華照旄鉞，榮盛對銀黃。","琮璧交輝映，衣裳雜彩章。","晴雲遙蓋覆，秋蝶近悠揚。","空想逢九日，何由陪一觴。","滿叢佳色在，未肯委嚴霜。"]', '["素萼迎寒秀，金英带露香。","繁华照旄鉞，榮盛对銀黄。","琮璧交輝映，衣裳杂彩章。","晴云遙蓋覆，秋蝶近悠揚。","空想逢九日，何由陪一觴。","满叢佳色在，未肯委嚴霜。"]', '诗', 'shi', '', NULL, '和令狐相公九日對黃白二菊花見懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64787797-5a57-48aa-8232-01433784e4e7', '令狐僕射與余投分素深縱山川阻修然音問相繼今年十一月僕射疾不起聞予已承訃書寢門長慟後日有使者兩輩持書幷詩計其日時已是臥疾手筆盈幅翰墨尚新律詞一篇音韻彌切收淚握管以成報章雖廣陵之弦於今絕矣而蓋泉之感猶庶聞焉焚之繐帳之前附于舊編之末', '令狐僕射與余投分素深縱山川阻修然音问相繼今年十一月僕射疾不起闻予已承訃书寢门长慟後日有使者兩輩持书幷诗計其日时已是臥疾手笔盈幅翰墨尚新律词一篇音韻彌切收泪握管以成報章雖廣陵之弦於今絕矣而蓋泉之感猶庶闻焉焚之繐帳之前附于旧編之末', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前日寢門慟，至今悲有餘。","已嗟萬化盡，方見八行書。","滿紙傳相憶，裁詩怨索居。","危弦音有絕，哀玉韻[猶]虛。","忽歎幽明異，俄驚歲月除。","文章雖不朽，精魂竟焉如。","零淚霑青簡，傷心見素車。","悽涼從此後，無復望雙魚。"]', '["前日寢门慟，至今悲有餘。","已嗟万化尽，方见八行书。","满紙傳相憶，裁诗怨索居。","危弦音有絕，哀玉韻[猶]虛。","忽歎幽明異，俄驚歲月除。","文章雖不朽，精魂竟焉如。","零泪霑青簡，傷心见素车。","悽涼從此後，無复望雙鱼。"]', '诗', 'shi', '', NULL, '令狐僕射與余投分素深縱山川阻修然音問相繼今年十一月僕射疾不起聞予已承訃書寢門長慟後日有使者兩輩持書幷詩計其日時已是臥疾手筆盈幅翰墨尚新律詞一篇音韻彌切收淚握管以成報章雖廣陵之弦於今絕矣而蓋泉之感猶庶聞焉焚之繐帳之前附于舊編之末 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf727ff-362a-4a5f-8578-5897237bb530', '和樂天閑園獨賞八韻前以蜂鶴拙句寄呈今辱蝸蟻妍詞見答因成小巧以取大咍', '和乐天闲园独賞八韻前以蜂鹤拙句寄呈今辱蝸蟻妍词见答因成小巧以取大咍', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["永日無人事，芳園任興行。","陶廬樹可愛，潘宅雨新晴。","傅粉琅玕節，熏香菡萏莖。","榴花裙色好，桐子藥丸成。","柳蠹枝偏亞，桑空葉再生。","睢盱欲鬬雀，索漠不言鶯。","動植隨四氣，飛沈含五情。","搶榆與水擊，小大強爲名。"]', '["永日無人事，芳园任兴行。","陶廬樹可愛，潘宅雨新晴。","傅粉琅玕節，熏香菡萏莖。","榴花裙色好，桐子藥丸成。","柳蠹枝偏亞，桑空葉再生。","睢盱欲鬬雀，索漠不言鶯。","动植隨四氣，飞沈含五情。","搶榆與水擊，小大強爲名。"]', '诗', 'shi', '', NULL, '和樂天閑園獨賞八韻前以蜂鶴拙句寄呈今辱蝸蟻妍詞見答因成小巧以取大咍 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc6bc89-c0b0-4ac9-8ef2-d0719a035bb4', '奉和裴令公新成綠野堂即書', '奉和裴令公新成綠野堂即书', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["藹藹鼎門外，澄澄洛水灣。","堂皇臨綠野，坐臥看青山。","位極却忘貴，功成欲愛閑。","官名司管籥，心術去機關。","禁苑凌晨出，園花及露攀。","池塘魚拔刺，竹逕鳥綿蠻。","志在安瀟灑，嘗經歷險艱。","高情方造適，衆意望徵還。","好客交珠履，華筵舞玉顏。","無因隨賀燕，翔集畫梁間。"]', '["藹藹鼎门外，澄澄洛水灣。","堂皇臨綠野，坐臥看青山。","位極却忘貴，功成欲愛闲。","官名司管籥，心術去機关。","禁苑凌晨出，园花及露攀。","池塘鱼拔刺，竹逕鸟綿蠻。","志在安瀟灑，嘗經歷險艱。","高情方造適，衆意望徵還。","好客交珠履，华筵舞玉顏。","無因隨賀燕，翔集畫梁间。"]', '诗', 'shi', '', NULL, '奉和裴令公新成綠野堂即書 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a082c4-3aa9-4c23-9104-38aeef957d55', '三月三日與樂天及河南李尹奉陪裴令公泛洛禊飲各賦十二韻', '三月三日與乐天及河南李尹奉陪裴令公泛洛禊饮各賦十二韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛下今修禊，羣賢勝會稽。","盛筵陪玉鉉，通籍盡金閨。","波上神仙妓，岸旁桃李蹊。","水嬉如鷺振，歌響雜鶯啼。","歷覽風光好，沿洄意思迷。","櫂歌能儷曲，墨客競分題。","翠幄連雲起，香車向道齊。","人誇綾步障，馬惜錦障泥。","塵暗宮牆外，霞明苑樹西。","舟形隨鷁轉，橋影與虹低。","川色晴猶遠，烏聲暮欲棲。","唯餘踏青伴，待月魏王堤。"]', '["洛下今修禊，羣賢勝會稽。","盛筵陪玉鉉，通籍尽金閨。","波上神仙妓，岸旁桃李蹊。","水嬉如鷺振，歌响杂鶯啼。","歷覽风光好，沿洄意思迷。","櫂歌能儷曲，墨客競分題。","翠幄連云起，香车向道齊。","人誇綾步障，马惜錦障泥。","塵暗宮牆外，霞明苑樹西。","舟形隨鷁轉，橋影與虹低。","川色晴猶远，烏声暮欲棲。","唯餘踏青伴，待月魏王堤。"]', '诗', 'shi', '', NULL, '三月三日與樂天及河南李尹奉陪裴令公泛洛禊飲各賦十二韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61a7970-2190-49fe-b455-e005f9e90f5a', '樂天少傅五月長齋廣延緇徒謝絕文友坐成睽間因以戲之', '乐天少傅五月长斋廣延緇徒謝絕文友坐成睽间因以戲之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五月長齋戒，深居絕送迎。","不離通德里，便是法王城。","舉目皆僧事，全家少俗情。","精修無上道，結念未來生。","賓閤緇衣占，書堂信鼓鳴。","戲童爲塔象，啼鳥學經聲。","黍用青菰角，葵承玉露烹。","馬家供薏苡，劉氏餉蕪菁。","暗網籠歌扇，流塵晦酒鐺。","不知何次道，作佛幾時成。"]', '["五月长斋戒，深居絕送迎。","不離通德里，便是法王城。","舉目皆僧事，全家少俗情。","精修無上道，結念未来生。","賓閤緇衣占，书堂信鼓鳴。","戲童爲塔象，啼鸟学經声。","黍用青菰角，葵承玉露烹。","马家供薏苡，劉氏餉蕪菁。","暗網籠歌扇，流塵晦酒鐺。","不知何次道，作佛幾时成。"]', '诗', 'shi', '', NULL, '樂天少傅五月長齋廣延緇徒謝絕文友坐成睽間因以戲之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f4cb4c-c56a-4332-9a5d-d7fe611695e4', '酬樂天晚夏閑居欲相訪先詩見貽', '酬乐天晚夏闲居欲相訪先诗见貽', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["池榭堪臨泛，翛然散鬱陶。","步因驅鶴緩，吟爲聽蟬高。","林密添新竹，枝低縋晚桃。","酒醅晴易熟，藥圃夏頻薅。","老是班行舊，閑爲鄉里豪。","經過更何處，風景屬吾曹。"]', '["池榭堪臨泛，翛然散鬱陶。","步因驱鹤緩，吟爲听蟬高。","林密添新竹，枝低縋晚桃。","酒醅晴易熟，藥圃夏頻薅。","老是班行旧，闲爲乡里豪。","經過更何处，风景屬吾曹。"]', '诗', 'shi', '', NULL, '酬樂天晚夏閑居欲相訪先詩見貽 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3c6981-de13-44c7-8ba8-2e0578a5693b', '酬樂天醉後狂吟十韻', '酬乐天醉後狂吟十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["散誕人間樂，逍遙地上仙。","詩家登逸品，釋氏悟真筌。","制誥留臺閣，歌詞入管弦。","處身於木鴈，任世變桑田。","吏隱情兼遂，儒玄道兩全。","八關齋適罷，三雅興尤偏。","文墨中年舊，松筠晚歲堅。","魚書曾替代，香火有因緣。","欲向醉鄉去，猶爲色界牽。","好吹楊柳曲，爲我舞金鈿。"]', '["散誕人间乐，逍遙地上仙。","诗家登逸品，釋氏悟真筌。","制誥留台閣，歌词入管弦。","处身於木鴈，任世变桑田。","吏隐情兼遂，儒玄道兩全。","八关斋適罷，三雅兴尤偏。","文墨中年旧，松筠晚歲堅。","鱼书曾替代，香火有因緣。","欲向醉乡去，猶爲色界牽。","好吹楊柳曲，爲我舞金鈿。"]', '诗', 'shi', '', NULL, '酬樂天醉後狂吟十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd4b349-2ac3-4ac5-aebf-0667f90a082c', '牛相公見示新什謹依本韻次用以抒下情', '牛相公见示新什謹依本韻次用以抒下情', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["劇韻新篇至，因難始見能。","雨天龍變化，晴日鳳騫騰。","遊海驚何極，聞韶素不曾。","愜心時拊髀，擊節日麾肱。","符彩添隃墨，波瀾起剡藤。","揀金光熠熠，累璧勢層層。","珠媚多藏賈，花撩欲定僧。","封來真寶物，寄與媿交朋。","已老無時疾，長貧望歲登。","雀羅秋寂寂，蟲翅曉薨薨。","羸驥方辭絆，虛舟已絕絙。","榮華甘死別，健羨亦生憎。","玉柱琤瑽韻，金觥雹凸棱。","何時良宴會，促膝對華燈。"]', '["劇韻新篇至，因难始见能。","雨天龙变化，晴日鳳騫腾。","游海驚何極，闻韶素不曾。","愜心时拊髀，擊節日麾肱。","符彩添隃墨，波瀾起剡藤。","揀金光熠熠，累璧勢層層。","珠媚多藏賈，花撩欲定僧。","封来真寶物，寄與媿交朋。","已老無时疾，长貧望歲登。","雀羅秋寂寂，蟲翅晓薨薨。","羸驥方辞絆，虛舟已絕絙。","榮华甘死別，健羨亦生憎。","玉柱琤瑽韻，金觥雹凸棱。","何时良宴會，促膝对华灯。"]', '诗', 'shi', '', NULL, '牛相公見示新什謹依本韻次用以抒下情 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a6409a-a879-498e-a47e-3f61119593e6', '奉和中書崔舍人八月十五日夜翫月二十韻', '奉和中书崔舍人八月十五日夜翫月二十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暮景中秋爽，陰靈既望圓。","浮精離碧海，分照接虞淵。","迥見孤輪出，高從倚蓋旋。","二儀含皎澈，萬象共澄鮮。","整御當西陸，舒光麗上玄。","從星變風雨，順日助陶甄。","遠近同時望，晶熒此夜偏。","運行調玉燭，潔白應金天。","曲沼疑瑤鏡，通衢若象筵。","逢人盡冰雪，遇景即神仙。","引素吞銀漢，凝清洗綠煙。","臯禽警露下，鄰杵思風前。","水是還珠浦，山成種玉田。","劒沈三尺影，燈罷九枝然。","象外形無迹，寰中影有遷。","稍當雲闕正，未映斗城懸。","靜對揮宸翰，閑臨襞彩牋。","境同牛渚上，宿在鳳池邊。","興掩尋安道，詞勝命仲宣。","從今紙貴後，不復詠陳篇。"]', '["暮景中秋爽，陰靈既望圓。","浮精離碧海，分照接虞淵。","迥见孤輪出，高從倚蓋旋。","二儀含皎澈，万象共澄鲜。","整御當西陸，舒光丽上玄。","從星变风雨，順日助陶甄。","远近同时望，晶熒此夜偏。","運行調玉燭，潔白應金天。","曲沼疑瑤镜，通衢若象筵。","逢人尽冰雪，遇景即神仙。","引素吞銀漢，凝清洗綠煙。","臯禽警露下，鄰杵思风前。","水是還珠浦，山成種玉田。","劒沈三尺影，灯罷九枝然。","象外形無迹，寰中影有遷。","稍當云闕正，未映斗城懸。","静对揮宸翰，闲臨襞彩牋。","境同牛渚上，宿在鳳池邊。","兴掩尋安道，词勝命仲宣。","從今紙貴後，不复詠陳篇。"]', '诗', 'shi', '', NULL, '奉和中書崔舍人八月十五日夜翫月二十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a46c3e01-2dd9-42d0-8d96-13bae11ea2e0', '奉和淮南李相公早秋即事寄成都武相公', '奉和淮南李相公早秋即事寄成都武相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["八柱共承天，東西別隱然。","遠夷爭慕化，真相故臨邊。","竝進夔龍位，仍齊龜鶴年。","同心舟已濟，造膝璧常聯。","對領專征寄，遙持造物權。","斗牛添氣色，井絡靜氛煙。","獻可通三略，分甘出萬錢。","漢南趨節制，趙北賜山川。","玉帳觀渝舞，虹旌獵楚田。","步嫌雙綬重，夢入九城偏。","秋雨離情動，新詩樂府傳。","聆音還竊抃，不覺撫么弦。"]', '["八柱共承天，东西別隐然。","远夷爭慕化，真相故臨邊。","竝進夔龙位，仍齊龟鹤年。","同心舟已濟，造膝璧常聯。","对領專征寄，遙持造物權。","斗牛添氣色，井絡静氛煙。","獻可通三略，分甘出万錢。","漢南趨節制，趙北賜山川。","玉帳观渝舞，虹旌獵楚田。","步嫌雙綬重，梦入九城偏。","秋雨離情动，新诗乐府傳。","聆音還竊抃，不覺撫么弦。"]', '诗', 'shi', '', NULL, '奉和淮南李相公早秋即事寄成都武相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6658ab-c063-458d-99dc-77ddf76f75ad', '元和癸巳歲仲秋詔發江陵偏師問罪蠻徼後命宣慰釋兵歸降凱旋之辰率爾成詠寄荆南嚴司空', '元和癸巳歲仲秋詔發江陵偏師问罪蠻徼後命宣慰釋兵归降凱旋之辰率爾成詠寄荆南嚴司空', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蠻水阻朝宗，兵符下渚宮。","前籌得上策，無戰已成功。","漢使星飛入，夷心草偃同。","歌謠開竹棧，拜舞戢桑弓。","就日知冰釋，投人念鳥窮。","網羅三面解，章奏九門通。","卉服聯操袂，雕題盡鞠躬。","降幡秋練白，驛騎晝塵紅。","火號休傳警，機橋罷亙空。","登山不見虜，振斾自生風。","江遠煙波靜，軍回氣色雄。","佇看聞喜後，金石賜元戎。"]', '["蠻水阻朝宗，兵符下渚宮。","前籌得上策，無戰已成功。","漢使星飞入，夷心草偃同。","歌謠开竹棧，拜舞戢桑弓。","就日知冰釋，投人念鸟窮。","網羅三面解，章奏九门通。","卉服聯操袂，雕題尽鞠躬。","降幡秋練白，驛騎晝塵紅。","火號休傳警，機橋罷亙空。","登山不见虜，振斾自生风。","江远煙波静，軍回氣色雄。","佇看闻喜後，金石賜元戎。"]', '诗', 'shi', '', NULL, '元和癸巳歲仲秋詔發江陵偏師問罪蠻徼後命宣慰釋兵歸降凱旋之辰率爾成詠寄荆南嚴司空 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc78975-ade9-4fe2-8c2c-c4b46e62539a', '和李六侍御文宣王廟釋奠作', '和李六侍御文宣王廟釋奠作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["歎息魯先師，生逢周室卑。","有心律天道，無位救陵夷。","歷聘不能用，領徒空爾爲。","儒風正禮樂，旅象入蓍龜。","西狩非其應，中都安足施。","世衰由我賤，泣下爲人悲。","遺教光文德，興王叶夢期。","土田封後胤，冕服飾虛儀。","鐘鼓膠庠薦，牲牢郡邑祠。","聞君喟然歎，偏在上丁時。"]', '["歎息魯先師，生逢周室卑。","有心律天道，無位救陵夷。","歷聘不能用，領徒空爾爲。","儒风正禮乐，旅象入蓍龟。","西狩非其應，中都安足施。","世衰由我賤，泣下爲人悲。","遺教光文德，兴王叶梦期。","土田封後胤，冕服飾虛儀。","鐘鼓膠庠薦，牲牢郡邑祠。","闻君喟然歎，偏在上丁时。"]', '诗', 'shi', '', NULL, '和李六侍御文宣王廟釋奠作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3d578d-24c9-4cdf-acf2-8ee5ea6ae584', '和竇中丞晚入容江作', '和竇中丞晚入容江作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢郡三十六，鬱林東南遙。","人倫選清臣，天外頒詔條。","桂水步秋浪，火山凌霧朝。","分圻辨風物，入境聞謳謠。","莎岸見長亭，煙林隔麗譙。","日落舟益駛，川平旗自飄。","珠浦遠明滅，金沙晴動搖。","一吟道中作，離思懸層霄。"]', '["漢郡三十六，鬱林东南遙。","人倫選清臣，天外頒詔條。","桂水步秋浪，火山凌霧朝。","分圻辨风物，入境闻謳謠。","莎岸见长亭，煙林隔丽譙。","日落舟益駛，川平旗自飄。","珠浦远明滅，金沙晴动搖。","一吟道中作，離思懸層霄。"]', '诗', 'shi', '', NULL, '和竇中丞晚入容江作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b849afe9-f7db-4f53-b688-fafa65b264f1', '南海馬大夫見惠著述三通勒成四帙上自邃古達于國朝采其菁華至簡如富欽受嘉貺詩以謝之', '南海马大夫见惠著述三通勒成四帙上自邃古達于国朝采其菁华至簡如富欽受嘉貺诗以謝之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["紅旗閱五兵，絳帳領諸生。","味道輕鼎食，退公猶筆耕。","青箱傳學遠，金匱納書成。","一瞬見前事，九流當抗行。","編蒲曾苦思，垂竹媿無名。","今日承芳訊，誰言贈衮榮。"]', '["紅旗閱五兵，絳帳領諸生。","味道轻鼎食，退公猶笔耕。","青箱傳学远，金匱納书成。","一瞬见前事，九流當抗行。","編蒲曾苦思，垂竹媿無名。","今日承芳訊，誰言贈衮榮。"]', '诗', 'shi', '', NULL, '南海馬大夫見惠著述三通勒成四帙上自邃古達于國朝采其菁華至簡如富欽受嘉貺詩以謝之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e7048c-4997-4a3d-989a-008e2c88733f', '和楊侍郎初至郴州紀事書情題郡齋八韻', '和楊侍郎初至郴州紀事书情題郡斋八韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["旌節下朝臺，分圭從北回。","城頭鶴立處，驛樹鳳栖來。","舊路芳塵在，新恩馹騎催。","里閭風偃草，鼓舞抃成雷。","吏散山禽囀，庭香夏蕊開。","郡齋堪四望，壁記有三台。","人訝徵黃晚，文非弔屈哀。","一吟梁甫曲，知是臥龍才。"]', '["旌節下朝台，分圭從北回。","城头鹤立处，驛樹鳳栖来。","旧路芳塵在，新恩馹騎催。","里閭风偃草，鼓舞抃成雷。","吏散山禽囀，庭香夏蕊开。","郡斋堪四望，壁記有三台。","人訝徵黄晚，文非弔屈哀。","一吟梁甫曲，知是臥龙才。"]', '诗', 'shi', '', NULL, '和楊侍郎初至郴州紀事書情題郡齋八韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fb030e1-a5a9-4892-87e9-37a6e15ec01b', '和東川王相公新漲驛池八韻', '和东川王相公新漲驛池八韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日池塘上，初移造物權。","苞藏成別島，沿濁致清漣。","變化生言下，蓬瀛落眼前。","泛觴驚翠羽，開幕對紅蓮。","遠寫風光入，明含氣象全。","渚煙籠驛樹，波日漾寶筵。","曲岸留緹騎，中流轉綵船。","無因接元禮，共載比神仙。"]', '["今日池塘上，初移造物權。","苞藏成別島，沿濁致清漣。","变化生言下，蓬瀛落眼前。","泛觴驚翠羽，开幕对紅蓮。","远寫风光入，明含氣象全。","渚煙籠驛樹，波日漾寶筵。","曲岸留緹騎，中流轉綵船。","無因接元禮，共載比神仙。"]', '诗', 'shi', '', NULL, '和東川王相公新漲驛池八韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fdf8255-c250-4a77-ad9e-7bdf6bd865f6', '酬楊八庶子喜韓吳興與余同遷見贈', '酬楊八庶子喜韓吳兴與余同遷见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["早遇聖明朝，鴈行登九霄。","文輕傅武仲，酒逼蓋寬饒。","捨矢同瞻鵠，當筵共賽梟。","琢磨三益重，唱和五音調。","臺柏煙常起，池荷香暗飄。","星文辭北極，旗影度東遼。","直道由來黜，浮名豈敢要。","三湘與百越，雨散又雲搖。","遠守慙侯籍，徵還荷詔條。","顇容唯舌在，別恨幾魂銷。","滿眼悲陳事，逢人少舊僚。","煙霞爲老伴，蒲柳任先凋。","虎綬懸新印，龍舼理去橈。","斷腸天北郡，攜手洛陽橋。","幢蓋今雖貴，弓旌會見招。","其如草玄客，空宇久寥寥。"]', '["早遇聖明朝，鴈行登九霄。","文轻傅武仲，酒逼蓋寬饒。","捨矢同瞻鵠，當筵共賽梟。","琢磨三益重，唱和五音調。","台柏煙常起，池荷香暗飄。","星文辞北極，旗影度东遼。","直道由来黜，浮名豈敢要。","三湘與百越，雨散又云搖。","远守慙侯籍，徵還荷詔條。","顇容唯舌在，別恨幾魂銷。","满眼悲陳事，逢人少旧僚。","煙霞爲老伴，蒲柳任先凋。","虎綬懸新印，龙舼理去橈。","斷腸天北郡，携手洛陽橋。","幢蓋今雖貴，弓旌會见招。","其如草玄客，空宇久寥寥。"]', '诗', 'shi', '', NULL, '酬楊八庶子喜韓吳興與余同遷見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a11b0a8-68ea-44f1-ac31-bb371656d4f7', '和兵部鄭侍郎省中四松詩十韻', '和兵部鄭侍郎省中四松诗十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["右相歷中臺，移松武庫栽。","紫茸抽組綬，青實長玫瑰。","便有干霄勢，看成搆廈材。","數分天柱半，影逐日輪回。","舊賞台階去，新知谷口來。","息陰常仰望，翫境幾裴回。","翠粒晴懸露，蒼鱗雨起苔。","凝音助瑤瑟，飄蘂泛金罍。","月桂花遙燭，星榆葉對開。","終須似雞樹，榮茂近昭回。"]', '["右相歷中台，移松武庫栽。","紫茸抽組綬，青實长玫瑰。","便有干霄勢，看成搆廈材。","數分天柱半，影逐日輪回。","旧賞台階去，新知谷口来。","息陰常仰望，翫境幾裴回。","翠粒晴懸露，蒼鱗雨起苔。","凝音助瑤瑟，飄蘂泛金罍。","月桂花遙燭，星榆葉对开。","終須似雞樹，榮茂近昭回。"]', '诗', 'shi', '', NULL, '和兵部鄭侍郎省中四松詩十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a555628-6a30-4939-8803-eafa1d7918de', '酬鄭州權舍人見寄十二韻', '酬鄭州權舍人见寄十二韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朱戶凌晨啓，碧梧含早涼。","人從桔柣至，書到漆沮傍。","抃會因佳句，情深取斷章。","愜心同笑語，入耳勝笙簧。","憶昔三條路，居鄰數仞牆。","學堂青玉案，綵服紫羅囊。","麟角看成就，龍駒見抑揚。","彀中飛一箭，雲際落雙鶬。","甸邑叨前列，天臺媿後行。","鯉庭傳事業，雞樹遂翱翔。","書殿連鳷鵲，神池接鳳凰。","追遊蒙尚齒，惠好結中腸。","鎩翮方擡舉，危根易損傷。","一麾憐棄置，五字借恩光。","汝海崆峒秀，溱流芍藥芳。","風行能偃草，境靜不爭桑。","轉斾趨關右，頒條匝渭陽。","病吟猶有思，老醉已無狂。","塵滿鴻溝道，沙驚白狄鄉。","佇聞黃紙詔，促召紫微郎。"]', '["朱戶凌晨啓，碧梧含早涼。","人從桔柣至，书到漆沮傍。","抃會因佳句，情深取斷章。","愜心同笑語，入耳勝笙簧。","憶昔三條路，居鄰數仞牆。","学堂青玉案，綵服紫羅囊。","麟角看成就，龙駒见抑揚。","彀中飞一箭，云際落雙鶬。","甸邑叨前列，天台媿後行。","鯉庭傳事業，雞樹遂翱翔。","书殿連鳷鵲，神池接鳳凰。","追游蒙尚齒，惠好結中腸。","鎩翮方擡舉，危根易損傷。","一麾怜棄置，五字借恩光。","汝海崆峒秀，溱流芍藥芳。","风行能偃草，境静不爭桑。","轉斾趨关右，頒條匝渭陽。","病吟猶有思，老醉已無狂。","塵满鴻溝道，沙驚白狄乡。","佇闻黄紙詔，促召紫微郎。"]', '诗', 'shi', '', NULL, '酬鄭州權舍人見寄十二韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330863e1-a65d-49ae-a540-191e0293ce67', '和牛相公題姑蘇所寄太湖石兼寄李蘇州', '和牛相公題姑蘇所寄太湖石兼寄李蘇州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["震澤生奇石，沈潛得地靈。","初辭水府出，猶帶龍宮腥。","發自江湖國，來榮卿相庭。","從風夏雲勢，上漢古查形。","拂拭魚鱗見，鏗鏘玉韻聆。","煙波含宿潤，苔蘚助新青。","嵌穴胡雛貌，纖鋩蟲篆銘。","孱顏傲林薄，飛動向雷霆。","煩熱近還散，餘酲見便醒。","凡禽不敢息，浮壒莫能停。","靜稱垂松蓋，鮮宜映鶴翎。","忘憂常目擊，素尚與心冥。","眇小欺湘燕，團圓笑落星。","徒然想融結，安可測年齡。","採取詢鄉耋，搜求按舊經。","垂鉤入空隙，隔浪動晶熒。","有獲人爭賀，歡謠衆共聽。","一州驚閱寶，千里遠揚舲。","覩物洛陽陌，懷人吳御亭。","寄言垂天翼，早晚起滄溟。"]', '["震澤生奇石，沈潛得地靈。","初辞水府出，猶带龙宮腥。","發自江湖国，来榮卿相庭。","從风夏云勢，上漢古查形。","拂拭鱼鱗见，鏗鏘玉韻聆。","煙波含宿潤，苔蘚助新青。","嵌穴胡雛貌，纖鋩蟲篆銘。","孱顏傲林薄，飞动向雷霆。","煩熱近還散，餘酲见便醒。","凡禽不敢息，浮壒莫能停。","静稱垂松蓋，鲜宜映鹤翎。","忘憂常目擊，素尚與心冥。","眇小欺湘燕，團圓笑落星。","徒然想融結，安可測年齡。","採取詢乡耋，搜求按旧經。","垂鉤入空隙，隔浪动晶熒。","有獲人爭賀，歡謠衆共听。","一州驚閱寶，千里远揚舲。","覩物洛陽陌，懷人吳御亭。","寄言垂天翼，早晚起滄溟。"]', '诗', 'shi', '', NULL, '和牛相公題姑蘇所寄太湖石兼寄李蘇州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba571c1a-7567-479c-a7eb-19b7ade65797', '浙西李大夫述夢四十韻幷浙東元相公酬和斐然繼聲', '浙西李大夫述梦四十韻幷浙东元相公酬和斐然繼声', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["位是才能取，時因際會遭。","羽儀呈鸑鷟，鋩刃試豪曹。","洛下推年少，山東許地高。","門承金鉉鼎，家有玉璜韜。","海浪扶鵬翅，天風引驥髦。","便知蓬閣閟，不識魯衣襃。","興發春塘草，魂交益部刀。","形開猶抱膝，燭盡遽揮毫。","昔仕當初筮，逢時詠載橐。","懷鉛辨蟲蠹，染素學鵝毛。","車騎方休汝，歸來欲效陶。","南臺資謇諤，內署選風騷。","羽化如乘鯉，樓居舊冠鼇。","美香焚濕麝，名果賜乾萄。","議赦蠅棲筆，邀歌蟻泛醪。","代言無所戲，謝表自稱叨。","蘭焰凝芳澤，芝泥瑩玉膏。","對頻聲價出，直久夢魂勞。","草詔令歸馬，批章答獻獒。","銀花懸院牓，翠羽映簾條。","諷諫欣然納，奇觚率爾操。","禁中時諤諤，天下免忉忉。","左顧龜成印，雙飛鵠織袍。","謝賓緣地密，潔己是心豪。","五日思歸沐，三春羨衆邀。","茶爐依綠笋，棊局就紅桃。","溟海桑潛變，陰陽炭暗熬。","仙成脫屣去，臣戀捧弓號。","建節辭烏柏，宣風看鷺濤。","土山京口峻，鐵甕郡城牢。","曲島花千樹，官池水一篙。","鶯來和絲管，雁起拂麾旄。","宛轉傾羅扇，回旋墮玉搔。","罰籌長豎纛，觥盞樣如舠。","山是千重障，江爲四面濠。","臥龍曾得雨，孤鶴尚鳴臯。","劍用熊開匣，弓閑蟄受弢。","鳳姿嘗在竹，鷃羽不離蒿。","吳月分雙鎮，東西接萬艘。","今朝比潘陸，江海更滔滔。"]', '["位是才能取，时因際會遭。","羽儀呈鸑鷟，鋩刃試豪曹。","洛下推年少，山东許地高。","门承金鉉鼎，家有玉璜韜。","海浪扶鵬翅，天风引驥髦。","便知蓬閣閟，不識魯衣襃。","兴發春塘草，魂交益部刀。","形开猶抱膝，燭尽遽揮毫。","昔仕當初筮，逢时詠載橐。","懷鉛辨蟲蠹，染素学鵝毛。","车騎方休汝，归来欲效陶。","南台資謇諤，內署選风騷。","羽化如乘鯉，楼居旧冠鼇。","美香焚濕麝，名果賜乾萄。","議赦蠅棲笔，邀歌蟻泛醪。","代言無所戲，謝表自稱叨。","蘭焰凝芳澤，芝泥瑩玉膏。","对頻声價出，直久梦魂勞。","草詔令归马，批章答獻獒。","銀花懸院牓，翠羽映簾條。","諷諫欣然納，奇觚率爾操。","禁中时諤諤，天下免忉忉。","左顧龟成印，雙飞鵠织袍。","謝賓緣地密，潔己是心豪。","五日思归沐，三春羨衆邀。","茶爐依綠笋，棊局就紅桃。","溟海桑潛变，陰陽炭暗熬。","仙成脫屣去，臣戀捧弓號。","建節辞烏柏，宣风看鷺濤。","土山京口峻，鐵甕郡城牢。","曲島花千樹，官池水一篙。","鶯来和絲管，雁起拂麾旄。","宛轉傾羅扇，回旋墮玉搔。","罰籌长豎纛，觥盞樣如舠。","山是千重障，江爲四面濠。","臥龙曾得雨，孤鹤尚鳴臯。","劍用熊开匣，弓闲蟄受弢。","鳳姿嘗在竹，鷃羽不離蒿。","吳月分雙鎮，东西接万艘。","今朝比潘陸，江海更滔滔。"]', '诗', 'shi', '', NULL, '浙西李大夫述夢四十韻幷浙東元相公酬和斐然繼聲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d303a2-b213-4dbe-be84-2d326749da82', '和浙西李大夫伊川卜居', '和浙西李大夫伊川卜居', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["早入八元數，嘗承三接恩。","飛鳴天上路，鎮壓海西門。","清望寰中許，高情物外存。","時來誠不讓，歸去每形言。","洛下思招隱，江干壓作藩。","按經修道具，依樣買山村。","開鑿隨人化，幽陰爲律暄。","遠移難得樹，立變舊荒園。","絕塞通潛徑，平泉占上原。","煙霞遙在想，簿領益爲繁。","丹禁虛東閤，蒼生望北轅。","徒令雙白鶴，五里自翩飜。"]', '["早入八元數，嘗承三接恩。","飞鳴天上路，鎮壓海西门。","清望寰中許，高情物外存。","时来誠不讓，归去每形言。","洛下思招隐，江干壓作藩。","按經修道具，依樣買山村。","开鑿隨人化，幽陰爲律暄。","远移难得樹，立变旧荒园。","絕塞通潛徑，平泉占上原。","煙霞遙在想，簿領益爲繁。","丹禁虛东閤，蒼生望北轅。","徒令雙白鹤，五里自翩飜。"]', '诗', 'shi', '', NULL, '和浙西李大夫伊川卜居 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fcd5fc-e632-4f23-bfb4-635e3efdb94a', '省試風光草際浮', '省試风光草際浮', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["熙熙春景霽，草綠春光麗。","的歷亂相鮮，葳蕤互虧蔽。","乍疑芊綿裏，稍動丰茸際。","影碎翻崇蘭，浮香轉叢蕙。","含煙絢碧綵，帶露如珠綴。","幸因採掇日，況此臨芳歲。"]', '["熙熙春景霽，草綠春光丽。","的歷亂相鲜，葳蕤互虧蔽。","乍疑芊綿裏，稍动丰茸際。","影碎翻崇蘭，浮香轉叢蕙。","含煙絢碧綵，带露如珠綴。","幸因採掇日，況此臨芳歲。"]', '诗', 'shi', '', NULL, '省試風光草際浮 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f95638-e26e-4d37-a829-0d141eea7989', '歷陽書事七十韻', '歷陽书事七十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一夕爲湖地，千年列郡名。","霸王迷路處，亞父所封城。","漢置東南尉，梁分肘腋兵。","本吳風俗剽，兼楚語音傖。","沸井今無湧，烏江舊有名。","土臺遊柱史，石室隱彭鏗。","曹操祠猶在，濡須塢未平。","海潮隨月大，江水應春生。","憶昨深山裏，終朝看火耕。","魚書來北闕，鷁首下南荆。","雲雨巫山暗，蕙蘭湘水清。","章華樹已失，鄂渚草來迎。","廬阜香爐出，湓城粉堞明。","鴈飛彭蠡暮，鴉噪大雷晴。","平野分風使，恬和趁夜程。","貴池登陸峻，舂穀渡橋鳴。","駱驛主人問，悲歡故舊情。","幾年方一面，卜晝便三更。","助喜杯盤盛，忘機笑語訇。","管清疑警鶴，弦巧似嬌鶯。","熾炭烘蹲獸，華茵織鬬鯨。","回裾飄霧雨，急節墮瓊英。","斂黛凝愁色，施鈿耀翠晶。","容華本南國，妝束學西京。","日落方收鼓，天寒更炙笙。","促筵交履舄，痛飲倒簪纓。","謔浪容優孟，嬌憐許智瓊。","蔽明添翠帟，命燭拄金莖。","坐久羅衣皺，盃頻粉面騂。","興來從請曲，意墮即飛觥。","令急重須改，歡馮醉盡呈。","詰朝還選勝，來日又尋盟。","道別殷勤惜，邀筵次第爭。","唯聞嗟短景，不復有餘酲。","衆散扃朱戶，相攜話素誠。","晤言猶亹亹，殘漏自丁丁。","出祖千夫擁，行廚五熟烹。","離亭臨野水，別思入哀箏。","接境人情洽，方冬饌具精。","中流爲界道，隔岸數飛甍。","沙浦王渾鎮，滄洲謝脁城。","望夫人化石，夢帝日環營。","半渡趨津吏，緣堤簇郡甿。","場黃堆晚稻，籬碧見冬菁。","里社爭來獻，壺漿各自擎。","鴟夷傾底寫，[粔籹]鬬成。","采石風傳柝，新林暮擊鉦。","繭綸牽撥刺，犀焰照澄泓。","露冕觀原野，前驅抗斾旌。","分庭展賓主，望闕拜恩榮。","比屋惸嫠輩，連年水旱幷。","遐思常後已，下令必先庚。","遠岫低屏列，支流曲帶縈。","湖魚香勝肉，官酒重於餳。","憶昔泉源變，斯須地軸傾。","雞籠爲石顆，龜眼入泥坑。","事繫人風重，官從物論輕。","江春俄澹蕩，樓月幾虧盈。","柳長千絲宛，田塍一線絣。","遊魚將婢從，野雉見媒驚。","波淨攢鳧鵲，洲香發杜蘅。","一鍾菰葑米，千里水葵羹。","受譴時方久，分憂政未成。","比瓊雖碌碌，於鐵尚錚錚。","早忝登三署，曾聞奏六英。","無能甘負弩，不慎在提衡。","口語成中遘，毛衣阻上征。","時聞關利鈍，智亦有聾盲。","昔媿山東妙，今慙海內兄。","後來登甲乙，早已在蓬瀛。","心托秦明鏡，才非楚白珩。","齒衰親藥物，宦薄傲公卿。","捧日皆元老，宣風盡大彭。","好令朝集使，結束赴新正。"]', '["一夕爲湖地，千年列郡名。","霸王迷路处，亞父所封城。","漢置东南尉，梁分肘腋兵。","本吳风俗剽，兼楚語音傖。","沸井今無湧，烏江旧有名。","土台游柱史，石室隐彭鏗。","曹操祠猶在，濡須塢未平。","海潮隨月大，江水應春生。","憶昨深山裏，終朝看火耕。","鱼书来北闕，鷁首下南荆。","云雨巫山暗，蕙蘭湘水清。","章华樹已失，鄂渚草来迎。","廬阜香爐出，湓城粉堞明。","鴈飞彭蠡暮，鴉噪大雷晴。","平野分风使，恬和趁夜程。","貴池登陸峻，舂穀渡橋鳴。","駱驛主人问，悲歡故旧情。","幾年方一面，卜晝便三更。","助喜杯盤盛，忘機笑語訇。","管清疑警鹤，弦巧似嬌鶯。","熾炭烘蹲獸，华茵织鬬鯨。","回裾飄霧雨，急節墮瓊英。","斂黛凝愁色，施鈿耀翠晶。","容华本南国，妝束学西京。","日落方收鼓，天寒更炙笙。","促筵交履舄，痛饮倒簪纓。","謔浪容優孟，嬌怜許智瓊。","蔽明添翠帟，命燭拄金莖。","坐久羅衣皺，盃頻粉面騂。","兴来從請曲，意墮即飞觥。","令急重須改，歡馮醉尽呈。","詰朝還選勝，来日又尋盟。","道別殷勤惜，邀筵次第爭。","唯闻嗟短景，不复有餘酲。","衆散扃朱戶，相携話素誠。","晤言猶亹亹，殘漏自丁丁。","出祖千夫擁，行廚五熟烹。","離亭臨野水，別思入哀箏。","接境人情洽，方冬饌具精。","中流爲界道，隔岸數飞甍。","沙浦王渾鎮，滄洲謝脁城。","望夫人化石，梦帝日环營。","半渡趨津吏，緣堤簇郡甿。","場黄堆晚稻，籬碧见冬菁。","里社爭来獻，壺漿各自擎。","鴟夷傾底寫，[粔籹]鬬成。","采石风傳柝，新林暮擊鉦。","繭綸牽撥刺，犀焰照澄泓。","露冕观原野，前驱抗斾旌。","分庭展賓主，望闕拜恩榮。","比屋惸嫠輩，連年水旱幷。","遐思常後已，下令必先庚。","远岫低屏列，支流曲带縈。","湖鱼香勝肉，官酒重於餳。","憶昔泉源变，斯須地軸傾。","雞籠爲石顆，龟眼入泥坑。","事繫人风重，官從物論轻。","江春俄澹蕩，楼月幾虧盈。","柳长千絲宛，田塍一線絣。","游鱼將婢從，野雉见媒驚。","波淨攢鳧鵲，洲香發杜蘅。","一鍾菰葑米，千里水葵羹。","受譴时方久，分憂政未成。","比瓊雖碌碌，於鐵尚錚錚。","早忝登三署，曾闻奏六英。","無能甘負弩，不慎在提衡。","口語成中遘，毛衣阻上征。","时闻关利鈍，智亦有聾盲。","昔媿山东妙，今慙海內兄。","後来登甲乙，早已在蓬瀛。","心托秦明镜，才非楚白珩。","齒衰親藥物，宦薄傲公卿。","捧日皆元老，宣风尽大彭。","好令朝集使，結束赴新正。"]', '诗', 'shi', '', NULL, '歷陽書事七十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f4450b-ab48-4dad-8d98-a1f7ae6c66e9', '和武中丞秋日寄懷簡諸僚故', '和武中丞秋日寄懷簡諸僚故', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["退朝還公府，騎吹息繁陰。","吏散秋庭寂，烏啼煙樹深。","威生奉白簡，道勝外華簪。","風物清遠目，功名懷寸陰。","雲衢念前侶，綵翰寫沖襟。","涼菊照幽徑，敗荷攢碧潯。","感時江海思，報國松筠心。","空愧壽陵步，芳塵何處尋。"]', '["退朝還公府，騎吹息繁陰。","吏散秋庭寂，烏啼煙樹深。","威生奉白簡，道勝外华簪。","风物清远目，功名懷寸陰。","云衢念前侶，綵翰寫沖襟。","涼菊照幽徑，敗荷攢碧潯。","感时江海思，報国松筠心。","空愧壽陵步，芳塵何处尋。"]', '诗', 'shi', '', NULL, '和武中丞秋日寄懷簡諸僚故 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4027d74-3867-4341-ad57-5248746e36a5', '和令狐相公春日尋花有懷白侍郎閣老', '和令狐相公春日尋花有懷白侍郎閣老', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["芳菲滿雍州，鸞鳳許同遊。","花逕須深入，時光不少留。","色鮮由樹嫩，枝亞爲房稠。","靜對仍持酒，高看特上樓。","晴宜連夜賞，雨便一年休。","共憶秋官處，餘霞曲水頭。"]', '["芳菲满雍州，鸾鳳許同游。","花逕須深入，时光不少留。","色鲜由樹嫩，枝亞爲房稠。","静对仍持酒，高看特上楼。","晴宜連夜賞，雨便一年休。","共憶秋官处，餘霞曲水头。"]', '诗', 'shi', '', NULL, '和令狐相公春日尋花有懷白侍郎閣老 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7809c5ca-acce-4065-b56e-00d6d2f04440', '荆州歌二首 一', '荆州歌二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["渚宮楊柳暗，麥城朝雉飛。","可憐踏青伴，乘暖著輕衣。"]', '["渚宮楊柳暗，麦城朝雉飞。","可怜踏青伴，乘暖著轻衣。"]', '诗', 'shi', '', NULL, '荆州歌二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3b872e-84da-4a39-9d6f-c4cedab414c3', '荆州歌二首 二', '荆州歌二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日好南風，商旅相催發。","沙頭檣竿上，始見春江闊。"]', '["今日好南风，商旅相催發。","沙头檣竿上，始见春江闊。"]', '诗', 'shi', '', NULL, '荆州歌二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5657f7fa-ec42-49fc-9d40-5adf6c2e605a', '紀南歌', '紀南歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["風煙紀南城，塵土荆門路。","天寒多獵騎，走上樊姬墓。"]', '["风煙紀南城，塵土荆门路。","天寒多獵騎，走上樊姬墓。"]', '诗', 'shi', '', NULL, '紀南歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16cf9703-0040-4bd6-8716-9b79b2da0775', '視刀環歌', '視刀环歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["常恨言語淺，不如人意深。","今朝兩相視，脈脈萬重心。"]', '["常恨言語淺，不如人意深。","今朝兩相視，脈脈万重心。"]', '诗', 'shi', '', NULL, '視刀環歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460d5f85-4d6f-4edb-8834-182b6064f711', '三閣辭四首 一', '三閣辞四首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["貴人三閣上，日晏未梳頭。","不應有恨事，嬌甚却成愁。"]', '["貴人三閣上，日晏未梳头。","不應有恨事，嬌甚却成愁。"]', '诗', 'shi', '', NULL, '三閣辭四首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f936c67-d702-4820-8731-fa25bec2f896', '三閣辭四首 二', '三閣辞四首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["珠箔曲瓊鉤，仔細見揚州。","北兵那得度，浪話判悠悠。"]', '["珠箔曲瓊鉤，仔細见揚州。","北兵那得度，浪話判悠悠。"]', '诗', 'shi', '', NULL, '三閣辭四首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd4205f-6e75-4989-bb94-12d5fc625915', '三閣辭四首 三', '三閣辞四首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["沉香帖閣柱，金縷畫門楣。","回首降旛下，已見黍[離]離。"]', '["沉香帖閣柱，金縷畫门楣。","回首降旛下，已见黍[離]離。"]', '诗', 'shi', '', NULL, '三閣辭四首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b669a85d-3a74-49db-af17-74af105c8053', '三閣辭四首 四', '三閣辞四首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三人出眢井，一身登檻車。","朱門漫臨水，不可見鱸魚。"]', '["三人出眢井，一身登檻车。","朱门漫臨水，不可见鱸鱼。"]', '诗', 'shi', '', NULL, '三閣辭四首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560ac8be-9830-400f-9569-ef31c491a116', '紇那曲二首 一', '紇那曲二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楊柳鬱青青，竹枝無限情。","周郎一回顧，聽唱紇那聲。"]', '["楊柳鬱青青，竹枝無限情。","周郎一回顧，听唱紇那声。"]', '诗', 'shi', '', NULL, '紇那曲二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62db1809-bcc5-49ae-a4b0-18e663158eba', '紇那曲二首 二', '紇那曲二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["踏曲興無窮，調同詞不同。","願郎千萬壽，長作主人翁。"]', '["踏曲兴無窮，調同词不同。","願郎千万壽，长作主人翁。"]', '诗', 'shi', '', NULL, '紇那曲二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a33d7af-ec79-4447-8c97-21a04fb462f7', '淮陰行五首 一', '淮陰行五首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["簇簇淮陰市，竹樓緣岸上。","好日起檣竿，烏飛驚五兩。"]', '["簇簇淮陰市，竹楼緣岸上。","好日起檣竿，烏飞驚五兩。"]', '诗', 'shi', '', NULL, '淮陰行五首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f862a9b7-6b53-4e96-821e-d0c2909ea2b4', '淮陰行五首 二', '淮陰行五首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日轉船頭，金烏指西北。","煙波與春草，千里同一色。"]', '["今日轉船头，金烏指西北。","煙波與春草，千里同一色。"]', '诗', 'shi', '', NULL, '淮陰行五首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdbf767-a7aa-48cf-9064-a732fe532009', '淮陰行五首 三', '淮陰行五首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["船頭大銅鐶，摩挲光陣陣。","早早使風來，沙頭一眼認。"]', '["船头大銅鐶，摩挲光陣陣。","早早使风来，沙头一眼認。"]', '诗', 'shi', '', NULL, '淮陰行五首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac4ca27-8f3a-411f-aa2b-dc2441c9706d', '淮陰行五首 四', '淮陰行五首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何物令儂羨，羨郎船尾燕。","銜泥趂檣竿，宿食長相見。"]', '["何物令儂羨，羨郎船尾燕。","銜泥趂檣竿，宿食长相见。"]', '诗', 'shi', '', NULL, '淮陰行五首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0cbaf4-8183-45e7-a67c-6f6f56c140a9', '淮陰行五首 五', '淮陰行五首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["隔浦望行船，頭昂尾幰幰。","無奈晚來時，清淮春浪軟。"]', '["隔浦望行船，头昂尾幰幰。","無奈晚来时，清淮春浪軟。"]', '诗', 'shi', '', NULL, '淮陰行五首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf3519f-97ee-4544-8518-8f8d581a2e1b', '渾侍中宅牡丹', '渾侍中宅牡丹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["徑尺千餘朵，人間有此花。","今朝見顏色，更不向諸家。"]', '["徑尺千餘朵，人间有此花。","今朝见顏色，更不向諸家。"]', '诗', 'shi', '', NULL, '渾侍中宅牡丹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44797238-71ef-49d0-a17f-7c3f49afa26b', '詠紅柿子', '詠紅柿子', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曉連星影出，晚帶日光懸。","本因遺采掇，翻自保天年。"]', '["晓連星影出，晚带日光懸。","本因遺采掇，翻自保天年。"]', '诗', 'shi', '', NULL, '詠紅柿子 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c242837e-7795-4994-a673-ddf5ea863443', '呂八見寄郡內書懷因而戲和', '呂八见寄郡內书懷因而戲和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["文苑振金聲，循良冠百城。","不知今史氏，何處列君名。"]', '["文苑振金声，循良冠百城。","不知今史氏，何处列君名。"]', '诗', 'shi', '', NULL, '呂八見寄郡內書懷因而戲和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef2d7dc-e0bb-4d6f-b683-ffb1db9f8008', '秋風引', '秋风引', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處秋風至，蕭蕭送鴈羣。","朝來入庭樹，孤客最先聞。"]', '["何处秋风至，蕭蕭送鴈羣。","朝来入庭樹，孤客最先闻。"]', '诗', 'shi', '', NULL, '秋風引 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1c466f-23d2-4a9e-9ad2-6b51fae4e6d0', '柳花詞三首 一', '柳花词三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["開從綠條上，散逐香風遠。","故取花落時，悠揚占春晚。"]', '["开從綠條上，散逐香风远。","故取花落时，悠揚占春晚。"]', '诗', 'shi', '', NULL, '柳花詞三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841d8979-3f76-460f-909c-17a768bc1c2b', '柳花詞三首 二', '柳花词三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["輕飛不假風，輕落不委地。","撩亂舞晴空，發人無限思。"]', '["轻飞不假风，轻落不委地。","撩亂舞晴空，發人無限思。"]', '诗', 'shi', '', NULL, '柳花詞三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92b4674a-85cc-41a3-adc6-e3581cfc8ae7', '柳花詞三首 三', '柳花词三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["晴天闇闇雪，來送青春暮。","無意似多情，千家萬家去。"]', '["晴天闇闇雪，来送青春暮。","無意似多情，千家万家去。"]', '诗', 'shi', '', NULL, '柳花詞三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c411b555-8584-4ff8-91da-7acd8f6b96d6', '路傍曲', '路傍曲', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南山宿雨晴，春入鳳凰城。","處處聞弦管，無非送酒聲。"]', '["南山宿雨晴，春入鳳凰城。","处处闻弦管，無非送酒声。"]', '诗', 'shi', '', NULL, '路傍曲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd3aeca-cbaf-40ed-8a0a-4efb2bcda29e', '君山懷古', '君山懷古', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["屬車八十一，此地阻長風。","千載威靈盡，赭山寒水中。"]', '["屬车八十一，此地阻长风。","千載威靈尽，赭山寒水中。"]', '诗', 'shi', '', NULL, '君山懷古 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6781768a-f26c-4073-9392-c528811002b9', '庭竹', '庭竹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["露滌鉛粉節，風搖青玉枝。","依依似君子，無地不相宜。"]', '["露滌鉛粉節，风搖青玉枝。","依依似君子，無地不相宜。"]', '诗', 'shi', '', NULL, '庭竹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f6df256-96a2-42ef-a720-59e62ad61027', '唐郎中宅與諸公同飲酒看牡丹', '唐郎中宅與諸公同饮酒看牡丹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日花前飲，甘心醉數杯。","但愁花有語，不爲老人開。"]', '["今日花前饮，甘心醉數杯。","但愁花有語，不爲老人开。"]', '诗', 'shi', '', NULL, '唐郎中宅與諸公同飲酒看牡丹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fb8df9-266a-4146-801c-3cb02776a109', '題壽安甘棠館二首 一', '題壽安甘棠館二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["公館似仙家，池清竹徑斜。","山禽忽驚起，衝落半巖花。"]', '["公館似仙家，池清竹徑斜。","山禽忽驚起，衝落半巖花。"]', '诗', 'shi', '', NULL, '題壽安甘棠館二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9168b8e-f59f-4f31-9646-6ab54280ac84', '題壽安甘棠館二首 二', '題壽安甘棠館二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["門前洛陽道，門裏桃花路。","塵土與煙霞，其間十餘步。"]', '["门前洛陽道，门裏桃花路。","塵土與煙霞，其间十餘步。"]', '诗', 'shi', '', NULL, '題壽安甘棠館二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7faf39f5-b4cf-4c5f-9888-f0b8db33d466', '古詞二首 一', '古词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["軒后初冠冕，前旒爲蔽明。","安知從複道，然後見人情。"]', '["軒后初冠冕，前旒爲蔽明。","安知從複道，然後见人情。"]', '诗', 'shi', '', NULL, '古詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea1f6f2-16f4-403c-9e25-50c5252d6799', '古詞二首 二', '古词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["簿領乃俗士，清談信古風。","吾觀蘇令綽，朱墨一何工。"]', '["簿領乃俗士，清談信古风。","吾观蘇令綽，朱墨一何工。"]', '诗', 'shi', '', NULL, '古詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d18ead-1bf2-49e3-9128-1c400e3291d0', '寓興二首 一', '寓兴二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["常談即至理，安事非常情。","寄語何平叔，無爲輕老生。"]', '["常談即至理，安事非常情。","寄語何平叔，無爲轻老生。"]', '诗', 'shi', '', NULL, '寓興二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47a8a8f-4272-404a-81e0-a367224eabd7', '寓興二首 二', '寓兴二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["世途多禮數，鵬鷃各逍遙。","何事陶彭澤，拋官爲折腰。"]', '["世途多禮數，鵬鷃各逍遙。","何事陶彭澤，拋官爲折腰。"]', '诗', 'shi', '', NULL, '寓興二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e52d595-e24c-4f7f-8ff0-cb0ce98a252d', '詠史二首 一', '詠史二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["驃騎非無勢，少卿終不去。","世道劇頹波，我心如砥柱。"]', '["驃騎非無勢，少卿終不去。","世道劇頹波，我心如砥柱。"]', '诗', 'shi', '', NULL, '詠史二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e2d87a-ef85-4415-a125-dfc4488c0efa', '詠史二首 二', '詠史二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["賈生明王道，衛綰工車戲。","同遇漢文時，何人居貴位。"]', '["賈生明王道，衛綰工车戲。","同遇漢文时，何人居貴位。"]', '诗', 'shi', '', NULL, '詠史二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf3330e-822b-42ea-8555-e4fd139c07a5', '經檀道濟故壘', '經檀道濟故壘', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["萬里長城壞，荒營野草秋。","秣陵多士女，猶唱白符鳩。"]', '["万里长城壞，荒營野草秋。","秣陵多士女，猶唱白符鳩。"]', '诗', 'shi', '', NULL, '經檀道濟故壘 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c05718f-cce1-4446-aebb-68bc3f90cfe5', '傷段右丞', '傷段右丞', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江海多豪氣，朝廷有直聲。","何言馬蹄下，一旦是佳城。"]', '["江海多豪氣，朝廷有直声。","何言马蹄下，一旦是佳城。"]', '诗', 'shi', '', NULL, '傷段右丞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107cebee-baee-4a71-935d-b838d464d10c', '傷獨孤舍人', '傷独孤舍人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔別矜年少，今悲喪國華。","遠來同社燕，不見早梅花。"]', '["昔別矜年少，今悲喪国华。","远来同社燕，不见早梅花。"]', '诗', 'shi', '', NULL, '傷獨孤舍人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc46bfaa-d280-4c0d-93b2-7c1c2631353f', '再傷龐尹', '再傷龐尹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["京兆歸何處，章臺空暮塵。","可憐鸞鏡下，哭殺畫眉人。"]', '["京兆归何处，章台空暮塵。","可怜鸾镜下，哭殺畫眉人。"]', '诗', 'shi', '', NULL, '再傷龐尹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3a2354-337e-48cc-ae99-cddb07909817', '敬酬微公見寄二首 一', '敬酬微公见寄二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淒涼沃州僧，顦顇柴桑宰。","別來二十年，唯餘兩心在。"]', '["淒涼沃州僧，顦顇柴桑宰。","別来二十年，唯餘兩心在。"]', '诗', 'shi', '', NULL, '敬酬微公見寄二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b01e36e6-a1ae-4195-842e-336276c84ca4', '敬酬微公見寄二首 二', '敬酬微公见寄二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["越江千里鏡，越嶺四時雪。","中有逍遙人，夜深觀水月。"]', '["越江千里镜，越嶺四时雪。","中有逍遙人，夜深观水月。"]', '诗', 'shi', '', NULL, '敬酬微公見寄二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8a74f1-8505-4c21-b92d-8d9abc4adb15', '鄂渚留別李二十一表臣大夫', '鄂渚留別李二十一表臣大夫', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高檣起行色，促柱動離聲。","欲問江深淺，應如遠別情。"]', '["高檣起行色，促柱动離声。","欲问江深淺，應如远別情。"]', '诗', 'shi', '', NULL, '鄂渚留別李二十一表臣大夫 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2657ae-c9f7-48ab-90ff-e44690e1dc03', '荅表臣贈別二首 一', '荅表臣贈別二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔爲瑤池侶，飛舞集蓬萊。","今作江漢別，風雪一徘徊。"]', '["昔爲瑤池侶，飞舞集蓬萊。","今作江漢別，风雪一徘徊。"]', '诗', 'shi', '', NULL, '荅表臣贈別二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d04a92-66e6-425a-83d0-c664905621b8', '荅表臣贈別二首 二', '荅表臣贈別二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["嘶馬立未還，行舟路將轉。","江頭瞑色深，揮袖依稀見。"]', '["嘶马立未還，行舟路將轉。","江头瞑色深，揮袖依稀见。"]', '诗', 'shi', '', NULL, '荅表臣贈別二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c35451-9619-43bb-8d4b-eca04c472885', '始發鄂渚寄表臣二首 一', '始發鄂渚寄表臣二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["祖帳管弦絕，客帆西風生。","回車已不見，猶聽馬嘶聲。"]', '["祖帳管弦絕，客帆西风生。","回车已不见，猶听马嘶声。"]', '诗', 'shi', '', NULL, '始發鄂渚寄表臣二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('815a908b-b7a1-493a-8e50-9ed81d896c53', '始發鄂渚寄表臣二首 二', '始發鄂渚寄表臣二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曉發柳林戍，遙城聞五鼓。","憶與故人眠，此時猶晤語。"]', '["晓發柳林戍，遙城闻五鼓。","憶與故人眠，此时猶晤語。"]', '诗', 'shi', '', NULL, '始發鄂渚寄表臣二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b47b63-2b8c-4946-8301-3bbf80a9c528', '出鄂州界懷表臣二首 一', '出鄂州界懷表臣二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["離席一揮杯，別愁今尚醉。","遲遲有情處，却恨江帆駛。"]', '["離席一揮杯，別愁今尚醉。","遲遲有情处，却恨江帆駛。"]', '诗', 'shi', '', NULL, '出鄂州界懷表臣二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5837d540-2c92-4be0-a38a-c3b161cbae8d', '出鄂州界懷表臣二首 二', '出鄂州界懷表臣二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["夢覺疑連榻，舟行忽千里。","不見黃鶴樓，寒沙雪相似。"]', '["梦覺疑連榻，舟行忽千里。","不见黄鹤楼，寒沙雪相似。"]', '诗', 'shi', '', NULL, '出鄂州界懷表臣二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bc90c29-6414-4e61-adc2-eaf5d9722231', '和遊房公舊竹亭聞琴絕句', '和游房公旧竹亭闻琴絕句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["尚有竹間路，永無綦下塵。","一聞流水曲，重憶餐霞人。"]', '["尚有竹间路，永無綦下塵。","一闻流水曲，重憶餐霞人。"]', '诗', 'shi', '', NULL, '和遊房公舊竹亭聞琴絕句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdfb9a2a-c64d-4f12-83f8-e245a5ca1955', '西州李尚書知愚與元武昌有舊遠示二篇吟之泫然因以繼和二首 一', '西州李尚书知愚與元武昌有旧远示二篇吟之泫然因以繼和二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["如何贈琴日，已是絕弦時。","無復雙金報，空餘挂劒悲。"]', '["如何贈琴日，已是絕弦时。","無复雙金報，空餘挂劒悲。"]', '诗', 'shi', '', NULL, '西州李尚書知愚與元武昌有舊遠示二篇吟之泫然因以繼和二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('496bd468-fb3a-4f4b-8dee-cc0a4d0c528d', '西州李尚書知愚與元武昌有舊遠示二篇吟之泫然因以繼和二首 二', '西州李尚书知愚與元武昌有旧远示二篇吟之泫然因以繼和二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寶匣從此閑，朱弦誰復調。","祗應隨玉樹，同向土中銷。"]', '["寶匣從此闲，朱弦誰复調。","祗應隨玉樹，同向土中銷。"]', '诗', 'shi', '', NULL, '西州李尚書知愚與元武昌有舊遠示二篇吟之泫然因以繼和二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9ead67-45c7-495c-ba4d-4829f0973a91', '別蘇州二首 一', '別蘇州二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三載爲吳郡，臨岐祖帳開。","雖非謝桀黠，且爲一裴回。"]', '["三載爲吳郡，臨岐祖帳开。","雖非謝桀黠，且爲一裴回。"]', '诗', 'shi', '', NULL, '別蘇州二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d7fc62-13a8-414a-a9e2-d29590606de0', '別蘇州二首 二', '別蘇州二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["流水閶門外，秋風吹柳條。","從來送客處，今日自魂銷。"]', '["流水閶门外，秋风吹柳條。","從来送客处，今日自魂銷。"]', '诗', 'shi', '', NULL, '別蘇州二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c032e254-9f25-4a63-94c4-843a81fec27b', '罷和州遊建康', '罷和州游建康', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["秋水清無力，寒山暮多思。","官閑不計程，徧上南朝寺。"]', '["秋水清無力，寒山暮多思。","官闲不計程，徧上南朝寺。"]', '诗', 'shi', '', NULL, '罷和州遊建康 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd0b787-05ed-4762-86a1-eb5a852451ef', '九日登高', '九日登高', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["世路山河險，君門煙霧深。","年年上高處，未省不傷心。"]', '["世路山河險，君门煙霧深。","年年上高处，未省不傷心。"]', '诗', 'shi', '', NULL, '九日登高 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b1a26d-5044-470d-ac34-62578e2ec35e', '荅柳子厚', '荅柳子厚', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["年方伯玉早，恨比四愁多。","會待休車騎，相隨出罻羅。"]', '["年方伯玉早，恨比四愁多。","會待休车騎，相隨出罻羅。"]', '诗', 'shi', '', NULL, '荅柳子厚 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6201f3f-509d-4945-8b5c-6c7b843d9f56', '館娃宮在舊郡西南硯石山前瞰姑蘇臺傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 一', '館娃宮在旧郡西南硯石山前瞰姑蘇台傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["宮館貯嬌娃，當時意大誇。","豔傾吳國盡，笑入楚王家。"]', '["宮館貯嬌娃，當时意大誇。","豔傾吳国尽，笑入楚王家。"]', '诗', 'shi', '', NULL, '館娃宮在舊郡西南硯石山前瞰姑蘇臺傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657ed90a-14af-4feb-89e5-d0d50862d0c1', '館娃宮在舊郡西南硯石山前瞰姑蘇臺傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 二', '館娃宮在旧郡西南硯石山前瞰姑蘇台傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["月殿移椒壁，天花代舜華。","唯餘采香徑，一帶繞山斜。"]', '["月殿移椒壁，天花代舜华。","唯餘采香徑，一带繞山斜。"]', '诗', 'shi', '', NULL, '館娃宮在舊郡西南硯石山前瞰姑蘇臺傍有采香徑梁天監中置佛寺曰靈巖即故宮也信爲絕境因賦二章 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0217b3cb-8e36-4be8-b84c-31cf37d4caca', '聽琴', '听琴', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["禪思何妨在玉琴，真僧不見聽時心。","秋堂境寂夜方半，雲去蒼梧湘水深。"]', '["禪思何妨在玉琴，真僧不见听时心。","秋堂境寂夜方半，云去蒼梧湘水深。"]', '诗', 'shi', '', NULL, '聽琴 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbb0c48-4a48-4310-acec-a8bda8115a3d', '魏宮詞二首 一', '魏宮词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日晚長秋簾外報，望陵歌舞在明朝。","添爐欲爇熏衣麝，憶得分時不忍燒。"]', '["日晚长秋簾外報，望陵歌舞在明朝。","添爐欲爇熏衣麝，憶得分时不忍燒。"]', '诗', 'shi', '', NULL, '魏宮詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a66ab7-6f2a-4f2a-8e39-eb84bba4ccae', '魏宮詞二首 二', '魏宮词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日映西陵松柏枝，下臺相顧一相思。","朝來樂府長歌曲，唱著君王自作詞。"]', '["日映西陵松柏枝，下台相顧一相思。","朝来乐府长歌曲，唱著君王自作词。"]', '诗', 'shi', '', NULL, '魏宮詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772f0743-399e-4eeb-b688-43cdeb5bed11', '楊枝詞二首 一', '楊枝词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["迎得春光先到來，淺黃輕綠映樓臺。","只緣嫋娜多情思，更被春風長倩猜。"]', '["迎得春光先到来，淺黄轻綠映楼台。","只緣嫋娜多情思，更被春风长倩猜。"]', '诗', 'shi', '', NULL, '楊枝詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db28284e-b9e9-4a71-90a0-b458178cba1d', '楊枝詞二首 二', '楊枝词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巫峽巫山楊柳多，朝雲暮雨遠相和。","因想陽臺無限事，爲君回唱竹枝歌。"]', '["巫峽巫山楊柳多，朝云暮雨远相和。","因想陽台無限事，爲君回唱竹枝歌。"]', '诗', 'shi', '', NULL, '楊枝詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5995f7c-d598-4602-870d-87308ab19ea9', '竹枝詞二首 一', '竹枝词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楊柳青青江水平，聞郎江上唱歌聲。","東邊日出西邊雨，道是無晴却有晴。"]', '["楊柳青青江水平，闻郎江上唱歌声。","东邊日出西邊雨，道是無晴却有晴。"]', '诗', 'shi', '', NULL, '竹枝詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14dc9401-ed9c-48dd-b406-153c71244c12', '竹枝詞二首 二', '竹枝词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚水巴山江雨多，巴人能唱本鄉歌。","今朝北客思歸去，回入紇那披綠羅。"]', '["楚水巴山江雨多，巴人能唱本乡歌。","今朝北客思归去，回入紇那披綠羅。"]', '诗', 'shi', '', NULL, '竹枝詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21ca0ee-7b69-44ed-8f63-5a56bcbccbf1', '隄上行三首 一', '隄上行三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["酒旗相望大隄頭，堤下連檣堤上樓。","日暮行人爭渡急，槳聲幽軋滿中流。"]', '["酒旗相望大隄头，堤下連檣堤上楼。","日暮行人爭渡急，槳声幽軋满中流。"]', '诗', 'shi', '', NULL, '隄上行三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8432e9c9-1cd5-4c2f-bb7a-c940bc6765e7', '隄上行三首 二', '隄上行三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江南江北望煙波，入夜行人相應歌。","桃葉傳情竹枝怨，水流無限月明多。"]', '["江南江北望煙波，入夜行人相應歌。","桃葉傳情竹枝怨，水流無限月明多。"]', '诗', 'shi', '', NULL, '隄上行三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0324b31a-b787-4a09-9f32-ba9d1ba6b128', '隄上行三首 三', '隄上行三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春堤繚繞水徘徊，酒舍旗亭次第開。","日晚上樓招估客，軻峨大艑落颿來。"]', '["春堤繚繞水徘徊，酒舍旗亭次第开。","日晚上楼招估客，軻峨大艑落颿来。"]', '诗', 'shi', '', NULL, '隄上行三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9599ff9a-84cb-4e7d-aae3-65c6737c0739', '踏歌詞四首 一', '踏歌词四首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春江月出大堤平，堤上女郎連袂行。","唱盡新詞歡不見，紅霞映樹鷓鴣鳴。"]', '["春江月出大堤平，堤上女郎連袂行。","唱尽新词歡不见，紅霞映樹鷓鴣鳴。"]', '诗', 'shi', '', NULL, '踏歌詞四首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12e9754-1480-4615-a8d9-50ba36e4e784', '踏歌詞四首 二', '踏歌词四首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["桃蹊柳陌好經過，燈下妝成月下歌。","爲是襄王故宮地，至今猶自細腰多。"]', '["桃蹊柳陌好經過，灯下妝成月下歌。","爲是襄王故宮地，至今猶自細腰多。"]', '诗', 'shi', '', NULL, '踏歌詞四首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07867c62-2fca-4339-ae72-b14304ae604d', '踏歌詞四首 三', '踏歌词四首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新詞宛轉遞相傳，振袖傾鬟風露前。","月落烏啼雲雨散，遊童陌上拾花鈿。"]', '["新词宛轉遞相傳，振袖傾鬟风露前。","月落烏啼云雨散，游童陌上拾花鈿。"]', '诗', 'shi', '', NULL, '踏歌詞四首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2aef5e7-edb2-488b-8945-3edd91645277', '踏歌詞四首 四', '踏歌词四首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日暮江頭聞竹枝，南人行樂北人悲。","自從雪裏唱新曲，直到三春花盡時。"]', '["日暮江头闻竹枝，南人行乐北人悲。","自從雪裏唱新曲，直到三春花尽时。"]', '诗', 'shi', '', NULL, '踏歌詞四首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cfe8a30-6a98-494e-914b-243ecdf09b25', '步虛詞二首 一', '步虛词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["阿母種桃雲海際，花落子成三千歲。","海風吹折最繁枝，跪捧瓊盤獻天帝。"]', '["阿母種桃云海際，花落子成三千歲。","海风吹折最繁枝，跪捧瓊盤獻天帝。"]', '诗', 'shi', '', NULL, '步虛詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd451df2-23f3-46e3-ac32-27d8e351a0d5', '步虛詞二首 二', '步虛词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["華表千年一鶴歸，凝丹爲頂雪爲衣。","星星仙語人聽盡，却向五雲翻翅飛。"]', '["华表千年一鹤归，凝丹爲頂雪爲衣。","星星仙語人听尽，却向五云翻翅飞。"]', '诗', 'shi', '', NULL, '步虛詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00086d39-16dc-44bf-9ab2-2d4d2bbf4321', '阿嬌怨', '阿嬌怨', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["望見葳蕤舉翠華，試開金屋掃庭花。","須臾宮女傳來信，言幸平陽公主家。"]', '["望见葳蕤舉翠华，試开金屋掃庭花。","須臾宮女傳来信，言幸平陽公主家。"]', '诗', 'shi', '', NULL, '阿嬌怨 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa22a168-1c3f-48e1-b7d4-1aa143d66335', '秋詞二首 一', '秋词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["自古逢秋悲寂寥，我言秋日勝春朝。","晴空一鶴排雲上，便引詩情到碧霄。"]', '["自古逢秋悲寂寥，我言秋日勝春朝。","晴空一鹤排云上，便引诗情到碧霄。"]', '诗', 'shi', '', NULL, '秋詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3613036b-9f74-4736-ba87-6418d40e1479', '秋詞二首 二', '秋词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山明水淨夜來霜，數樹深紅出淺黃。","試上高樓清入骨，豈如春色嗾人狂。"]', '["山明水淨夜来霜，數樹深紅出淺黄。","試上高楼清入骨，豈如春色嗾人狂。"]', '诗', 'shi', '', NULL, '秋詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef99e9e8-c333-447c-8d38-c4e383ee3c75', '秋扇詞', '秋扇词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["莫道恩情無重來，人間榮謝遞相催。","當時初入君懷袖，豈念寒爐有死灰。"]', '["莫道恩情無重来，人间榮謝遞相催。","當时初入君懷袖，豈念寒爐有死灰。"]', '诗', 'shi', '', NULL, '秋扇詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1d0fdac-b027-46ab-a5a5-f0afa6ffd3a0', '竹枝詞九首 一', '竹枝词九首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白帝城頭春草生，白鹽山下蜀江清。","南人上來歌一曲，北人莫上動鄉情。"]', '["白帝城头春草生，白鹽山下蜀江清。","南人上来歌一曲，北人莫上动乡情。"]', '诗', 'shi', '', NULL, '竹枝詞九首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e931e58-5115-4a4b-a376-930db9ca4650', '竹枝詞九首 二', '竹枝词九首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山桃紅花滿上頭，蜀江春水拍山流。","花紅易衰似郎意，水流無限似儂愁。"]', '["山桃紅花满上头，蜀江春水拍山流。","花紅易衰似郎意，水流無限似儂愁。"]', '诗', 'shi', '', NULL, '竹枝詞九首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f078b071-d234-4871-b020-99072ffea464', '竹枝詞九首 三', '竹枝词九首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江上朱樓新雨晴，瀼西春水縠紋生。","橋東橋西好楊柳，人來人去唱歌行。"]', '["江上朱楼新雨晴，瀼西春水縠紋生。","橋东橋西好楊柳，人来人去唱歌行。"]', '诗', 'shi', '', NULL, '竹枝詞九首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1994e0e7-dffe-4453-9257-d0863fd9fdca', '竹枝詞九首 四', '竹枝词九首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日出三竿春霧消，江頭蜀客駐蘭橈。","憑寄狂夫書一紙，家住成都萬里橋。"]', '["日出三竿春霧消，江头蜀客駐蘭橈。","憑寄狂夫书一紙，家住成都万里橋。"]', '诗', 'shi', '', NULL, '竹枝詞九首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a981fe6-17c1-4abe-82bc-738e8d837950', '竹枝詞九首 五', '竹枝词九首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["兩岸山花似雪開，家家春酒滿銀杯。","昭君坊中多女伴，永安宮外踏青來。"]', '["兩岸山花似雪开，家家春酒满銀杯。","昭君坊中多女伴，永安宮外踏青来。"]', '诗', 'shi', '', NULL, '竹枝詞九首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a372ebf-c266-4409-8e58-291550d96f48', '竹枝詞九首 六', '竹枝词九首 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城西門前灧澦堆，年年波浪不能摧。","懊惱人心不如石，少時東去復西來。"]', '["城西门前灧澦堆，年年波浪不能摧。","懊惱人心不如石，少时东去复西来。"]', '诗', 'shi', '', NULL, '竹枝詞九首 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c394eff4-c772-4664-b133-cc74792f5850', '竹枝詞九首 七', '竹枝词九首 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["瞿塘嘈嘈十二灘，人言道路古來難。","長恨人心不如水，等閑平地起波瀾。"]', '["瞿塘嘈嘈十二灘，人言道路古来难。","长恨人心不如水，等闲平地起波瀾。"]', '诗', 'shi', '', NULL, '竹枝詞九首 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af717448-7ca6-471b-891a-725e31500b31', '竹枝詞九首 八', '竹枝词九首 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巫峽蒼蒼煙雨時，清猿啼在最高枝。","個裏愁人腸自斷，由來不是此聲悲。"]', '["巫峽蒼蒼煙雨时，清猿啼在最高枝。","個裏愁人腸自斷，由来不是此声悲。"]', '诗', 'shi', '', NULL, '竹枝詞九首 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a95f05b-76be-43c6-b2b2-fcb7b01900b9', '竹枝詞九首 九', '竹枝词九首 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山上層層桃李花，雲間煙火是人家。","銀釧金釵來負水，長刀短笠去燒畬。"]', '["山上層層桃李花，云间煙火是人家。","銀釧金釵来負水，长刀短笠去燒畬。"]', '诗', 'shi', '', NULL, '竹枝詞九首 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6adb9a41-3d7b-4a83-94ce-f83484673320', '楊柳枝詞九首 一', '楊柳枝词九首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["塞北梅花羌笛吹，淮南桂樹小山詞。","請君莫奏前朝曲，聽唱新翻楊柳枝。"]', '["塞北梅花羌笛吹，淮南桂樹小山词。","請君莫奏前朝曲，听唱新翻楊柳枝。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c637de43-4919-4b35-8cec-d81725eafcc6', '楊柳枝詞九首 二', '楊柳枝词九首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南陌東城春早時，相逢何處不依依。","桃紅李白皆誇好，須得垂楊相發揮。"]', '["南陌东城春早时，相逢何处不依依。","桃紅李白皆誇好，須得垂楊相發揮。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2b5b34d-d4d1-4eea-8948-5935cb5830a5', '楊柳枝詞九首 三', '楊柳枝词九首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳闕輕遮翡翠幃，龍池遙望麴塵絲。","御溝春水相輝映，狂殺長安年少兒。"]', '["鳳闕轻遮翡翠幃，龙池遙望麴塵絲。","御溝春水相輝映，狂殺长安年少兒。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af088d67-df6f-429b-80ed-c4a4111950f2', '楊柳枝詞九首 四', '楊柳枝词九首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金谷園中鶯亂飛，銅駝陌上好風吹。","城中桃李須臾盡，爭似垂楊無限時。"]', '["金谷园中鶯亂飞，銅駝陌上好风吹。","城中桃李須臾尽，爭似垂楊無限时。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5e3cbc-9a8f-408d-8d3c-1b6abc07c418', '楊柳枝詞九首 五', '楊柳枝词九首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["花萼樓前初種時，美人樓上鬬腰肢。","如今拋擲長街裏，露葉如啼欲向誰。"]', '["花萼楼前初種时，美人楼上鬬腰肢。","如今拋擲长街裏，露葉如啼欲向誰。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c3fc91-0c64-4fb7-b2fd-a16cc02167ff', '楊柳枝詞九首 六', '楊柳枝词九首 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["煬帝行宮汴水濱，數枝楊柳不勝春。","晚來風起花如雪，飛入宮牆不見人。"]', '["煬帝行宮汴水濱，數枝楊柳不勝春。","晚来风起花如雪，飞入宮牆不见人。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda5af9d-8f84-485a-af43-f396ba111ba2', '楊柳枝詞九首 七', '楊柳枝词九首 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["御陌青門拂地垂，千條金縷萬條絲。","如今綰作同心結，將贈行人知不知。"]', '["御陌青门拂地垂，千條金縷万條絲。","如今綰作同心結，將贈行人知不知。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e510d91c-2ffa-453d-8a11-8e1589bee761', '楊柳枝詞九首 八', '楊柳枝词九首 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城外春風吹酒旗，行人揮袂日西時。","長安陌上無窮樹，唯有垂楊管別離。"]', '["城外春风吹酒旗，行人揮袂日西时。","长安陌上無窮樹，唯有垂楊管別離。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8387df-26b1-427d-802b-dc20c9095d73', '楊柳枝詞九首 九', '楊柳枝词九首 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["輕盈嫋娜占年華，舞榭妝樓處處遮。","春盡絮花留不得，隨風好去落誰家。"]', '["轻盈嫋娜占年华，舞榭妝楼处处遮。","春尽絮花留不得，隨风好去落誰家。"]', '诗', 'shi', '', NULL, '楊柳枝詞九首 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f61bf4-5c31-4875-a33f-97de1a1560d2', '浪淘沙九首 一', '浪淘沙九首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九曲黃河萬里沙，浪淘風簸自天涯。","如今直上銀河去，同到牽牛織女家。"]', '["九曲黄河万里沙，浪淘风簸自天涯。","如今直上銀河去，同到牽牛织女家。"]', '诗', 'shi', '', NULL, '浪淘沙九首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01e5b9e-7577-4eac-8b92-29963022ef7e', '浪淘沙九首 二', '浪淘沙九首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛水橋邊春日斜，碧流清淺見瓊砂。","無端陌上狂風急，驚起鴛鴦出浪花。"]', '["洛水橋邊春日斜，碧流清淺见瓊砂。","無端陌上狂风急，驚起鴛鴦出浪花。"]', '诗', 'shi', '', NULL, '浪淘沙九首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac6a6e5-66cc-4b4b-adda-65874ce18197', '浪淘沙九首 三', '浪淘沙九首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["汴水東流虎眼紋，清淮曉色鴨頭春。","君看渡口淘沙處，渡却人間多少人。"]', '["汴水东流虎眼紋，清淮晓色鴨头春。","君看渡口淘沙处，渡却人间多少人。"]', '诗', 'shi', '', NULL, '浪淘沙九首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30df2a91-7606-46b7-927a-0f1c7f2a6de1', '浪淘沙九首 四', '浪淘沙九首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鸚鵡洲頭浪颭沙，青樓春望日將斜。","銜泥燕子爭歸舍，獨自狂夫不憶家。"]', '["鸚鵡洲头浪颭沙，青楼春望日將斜。","銜泥燕子爭归舍，独自狂夫不憶家。"]', '诗', 'shi', '', NULL, '浪淘沙九首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a7db27-2e80-4973-8bfb-30430c70e147', '浪淘沙九首 五', '浪淘沙九首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["濯錦江邊兩岸花，春風吹浪正淘沙。","女郎剪下鴛鴦錦，將向中流疋晚霞。"]', '["濯錦江邊兩岸花，春风吹浪正淘沙。","女郎剪下鴛鴦錦，將向中流疋晚霞。"]', '诗', 'shi', '', NULL, '浪淘沙九首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f26fde-fc47-4c9f-b84c-0a53760dcba2', '浪淘沙九首 六', '浪淘沙九首 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日照澄洲江霧開，淘金女伴滿江隈。","美人首飾侯王印，盡是沙中浪底來。"]', '["日照澄洲江霧开，淘金女伴满江隈。","美人首飾侯王印，尽是沙中浪底来。"]', '诗', 'shi', '', NULL, '浪淘沙九首 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25cc9c38-bca2-4fcb-b3f1-4d9f7c548283', '浪淘沙九首 七', '浪淘沙九首 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["八月濤聲吼地來，頭高數丈觸山回。","須臾却入海門去，卷起沙堆似雪堆。"]', '["八月濤声吼地来，头高數丈觸山回。","須臾却入海门去，卷起沙堆似雪堆。"]', '诗', 'shi', '', NULL, '浪淘沙九首 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a05f66-355d-4cc8-9a16-50c0fd7d8aac', '浪淘沙九首 八', '浪淘沙九首 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["莫道讒言如浪深，莫言遷客似沙沉。","千淘萬漉雖辛苦，吹盡狂沙始到金。"]', '["莫道讒言如浪深，莫言遷客似沙沉。","千淘万漉雖辛苦，吹尽狂沙始到金。"]', '诗', 'shi', '', NULL, '浪淘沙九首 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4db6be-59c1-48b9-b49c-f741da35d197', '浪淘沙九首 九', '浪淘沙九首 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["流水淘沙不暫停，前波未滅後波生。","令人忽憶瀟湘渚，回唱迎神三兩聲。"]', '["流水淘沙不暫停，前波未滅後波生。","令人忽憶瀟湘渚，回唱迎神三兩声。"]', '诗', 'shi', '', NULL, '浪淘沙九首 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3861b957-d5e8-4378-b18e-b2df91f3c463', '洛中送韓七中丞之吳興口號五首 一', '洛中送韓七中丞之吳兴口號五首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔年意氣結羣英，幾度朝回一字行。","海北江南零落盡，兩人相見洛陽城。"]', '["昔年意氣結羣英，幾度朝回一字行。","海北江南零落尽，兩人相见洛陽城。"]', '诗', 'shi', '', NULL, '洛中送韓七中丞之吳興口號五首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140c0694-f46b-403b-b4f7-7d4091987d83', '洛中送韓七中丞之吳興口號五首 二', '洛中送韓七中丞之吳兴口號五首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["自從雲散各東西，每日歡娛却慘悽。","離別苦多相見少，一生心事在書題。"]', '["自從云散各东西，每日歡娛却慘悽。","離別苦多相见少，一生心事在书題。"]', '诗', 'shi', '', NULL, '洛中送韓七中丞之吳興口號五首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('addc88f8-af29-4f67-b55b-1278aa550eb1', '洛中送韓七中丞之吳興口號五首 三', '洛中送韓七中丞之吳兴口號五首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今朝無意訴離杯，何況清弦急管催。","本欲醉中輕遠別，不知翻引酒悲來。"]', '["今朝無意訴離杯，何況清弦急管催。","本欲醉中轻远別，不知翻引酒悲来。"]', '诗', 'shi', '', NULL, '洛中送韓七中丞之吳興口號五首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb347c3d-d86d-4941-9d38-ae4a8a776f97', '洛中送韓七中丞之吳興口號五首 四', '洛中送韓七中丞之吳兴口號五首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["駱駝橋上蘋風急，鸚鵡杯中箬下春。","水碧山青知好處，開顏一笑向何人。"]', '["駱駝橋上蘋风急，鸚鵡杯中箬下春。","水碧山青知好处，开顏一笑向何人。"]', '诗', 'shi', '', NULL, '洛中送韓七中丞之吳興口號五首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d171f79-2daa-4af8-af86-bf7b5512374d', '洛中送韓七中丞之吳興口號五首 五', '洛中送韓七中丞之吳兴口號五首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["溪中士女出笆籬，溪上鴛鴦避畫旗。","何處人間似仙境，春山攜妓採茶時。"]', '["溪中士女出笆籬，溪上鴛鴦避畫旗。","何处人间似仙境，春山携妓採茶时。"]', '诗', 'shi', '', NULL, '洛中送韓七中丞之吳興口號五首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f625f26-80bb-4d9c-8080-ae4e2dbd01a4', '送廖參謀東遊二首 一', '送廖參謀东游二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九陌逢君又別離，行雲別鶴本無期。","望嵩樓上忽相見，看過花開花落時。"]', '["九陌逢君又別離，行云別鹤本無期。","望嵩楼上忽相见，看過花开花落时。"]', '诗', 'shi', '', NULL, '送廖參謀東遊二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab42484-7a1a-4ffd-bfce-4c9b5cb5463e', '送廖參謀東遊二首 二', '送廖參謀东游二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["繁花落盡君辭去，綠草垂楊引征路。","東道諸侯皆故人，留連必是多情處。"]', '["繁花落尽君辞去，綠草垂楊引征路。","东道諸侯皆故人，留連必是多情处。"]', '诗', 'shi', '', NULL, '送廖參謀東遊二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92f8c8a-3448-453e-9fb1-af43970a5d52', '洛中春末送杜錄事赴蘄州', '洛中春末送杜錄事赴蘄州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["樽前花下長相見，明日忽爲千里人。","君過午橋回首望，洛城猶自有殘春。"]', '["樽前花下长相见，明日忽爲千里人。","君過午橋回首望，洛城猶自有殘春。"]', '诗', 'shi', '', NULL, '洛中春末送杜錄事赴蘄州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ce5e97-8a88-4c26-ae39-ce1ea38d1b0a', '夜燕福建盧侍郎宅因送之鎮', '夜燕福建盧侍郎宅因送之鎮', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暫駐旌旗洛水堤，綺筵紅燭醉蘭閨。","美人美酒長相逐，莫怕猿聲發建溪。"]', '["暫駐旌旗洛水堤，綺筵紅燭醉蘭閨。","美人美酒长相逐，莫怕猿声發建溪。"]', '诗', 'shi', '', NULL, '夜燕福建盧侍郎宅因送之鎮 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff7ad68-98c9-438e-95e0-2f036a635cd1', '重送鴻舉師赴江陵謁馬逢侍御', '重送鴻舉師赴江陵謁马逢侍御', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["西北秋風凋蕙蘭，洞庭波上碧雲寒。","茂陵才子江陵住，乞取新詩合掌看。"]', '["西北秋风凋蕙蘭，洞庭波上碧云寒。","茂陵才子江陵住，乞取新诗合掌看。"]', '诗', 'shi', '', NULL, '重送鴻舉師赴江陵謁馬逢侍御 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7dddb87-afac-411f-b97c-8dd277ef7df7', '贈長沙讚頭陀', '贈长沙讚头陀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["外道邪山千萬重，真言一發盡摧峰。","有時明月無人夜，獨向昭潭制惡龍。"]', '["外道邪山千万重，真言一發尽摧峰。","有时明月無人夜，独向昭潭制惡龙。"]', '诗', 'shi', '', NULL, '贈長沙讚頭陀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12186f8-919b-4f5e-9eee-beac6259aefe', '送霄韻上人遊天台', '送霄韻上人游天台', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曲江僧向松江見，又到天台看石橋。","鶴戀故巢雲戀岫，比君猶自不逍遙。"]', '["曲江僧向松江见，又到天台看石橋。","鹤戀故巢云戀岫，比君猶自不逍遙。"]', '诗', 'shi', '', NULL, '送霄韻上人遊天台 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c687d1-395c-464c-b931-51b3e77a74e8', '臺城懷古', '台城懷古', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["清江悠悠王氣沉，六朝遺事何處尋。","宮牆隱嶙圍野澤，鸛鶂夜鳴秋色深。"]', '["清江悠悠王氣沉，六朝遺事何处尋。","宮牆隐嶙圍野澤，鸛鶂夜鳴秋色深。"]', '诗', 'shi', '', NULL, '臺城懷古 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a21f2b2-07df-45f7-928c-ade985b22bea', '戲贈崔千牛', '戲贈崔千牛', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["學道深山許老人，留名萬代不關身。","勸君多買長安酒，南陌東城占取春。"]', '["学道深山許老人，留名万代不关身。","勸君多買长安酒，南陌东城占取春。"]', '诗', 'shi', '', NULL, '戲贈崔千牛 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1565ee71-07ab-4a52-8cf4-4749c9485232', '揚州春夜李端公益張侍御登段侍御平路密縣李少府畼秘書張正字復元同會於水館對酒聯句追刻燭擊銅缽故事遲輒舉觥以飲之逮夜艾羣公沾醉紛然就枕余偶獨醒因題詩於段君枕上以志其事', '揚州春夜李端公益張侍御登段侍御平路密縣李少府畼秘书張正字复元同會於水館对酒聯句追刻燭擊銅缽故事遲輒舉觥以饮之逮夜艾羣公沾醉紛然就枕余偶独醒因題诗於段君枕上以志其事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寂寂獨看金燼落，紛紛只見玉山頽。","自羞不是高陽侶，一夜星星騎馬回。"]', '["寂寂独看金燼落，紛紛只见玉山頽。","自羞不是高陽侶，一夜星星騎马回。"]', '诗', 'shi', '', NULL, '揚州春夜李端公益張侍御登段侍御平路密縣李少府畼秘書張正字復元同會於水館對酒聯句追刻燭擊銅缽故事遲輒舉觥以飲之逮夜艾羣公沾醉紛然就枕余偶獨醒因題詩於段君枕上以志其事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b694fdfc-0281-457e-9d6b-831b5e9e97ac', '逢王十二學士入翰林因以詩贈', '逢王十二学士入翰林因以诗贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["廄馬翩翩禁外逢，星槎上漢杳難從。","定知欲報淮南詔，促召王褒入九重。"]', '["廄马翩翩禁外逢，星槎上漢杳难從。","定知欲報淮南詔，促召王褒入九重。"]', '诗', 'shi', '', NULL, '逢王十二學士入翰林因以詩贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d6fe3c-1d4f-4e0d-8822-d4703adb4859', '闕下口號呈柳儀曹', '闕下口號呈柳儀曹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["綵仗神旗獵曉風，雞人一唱鼓蓬蓬。","銅壺漏水何時歇，如此相催即老翁。"]', '["綵仗神旗獵晓风，雞人一唱鼓蓬蓬。","銅壺漏水何时歇，如此相催即老翁。"]', '诗', 'shi', '', NULL, '闕下口號呈柳儀曹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad92f601-058c-42e6-88b6-05dbaa831e97', '監祠夕月壇書事', '監祠夕月壇书事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["西皥司分晝夜平，羲和停午太陰生。","鏗鏘揖讓秋光裏，觀者如雲出鳳城。"]', '["西皥司分晝夜平，羲和停午太陰生。","鏗鏘揖讓秋光裏，观者如云出鳳城。"]', '诗', 'shi', '', NULL, '監祠夕月壇書事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42d87f4-4427-4933-90d9-d25d0192f409', '元和甲午歲詔書盡徵江湘逐客余自武陵赴京宿於都亭有懷續來諸君子', '元和甲午歲詔书尽徵江湘逐客余自武陵赴京宿於都亭有懷續来諸君子', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雷雨江山起臥龍，武陵樵客躡仙蹤。","十年楚水楓林下，今夜初聞長樂鐘。"]', '["雷雨江山起臥龙，武陵樵客躡仙蹤。","十年楚水楓林下，今夜初闻长乐鐘。"]', '诗', 'shi', '', NULL, '元和甲午歲詔書盡徵江湘逐客余自武陵赴京宿於都亭有懷續來諸君子 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d444cc-e2a3-467a-a6f9-adfb9465e09e', '元和十一年自朗州召至京戲贈看花諸君子', '元和十一年自朗州召至京戲贈看花諸君子', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["紫陌紅塵拂面來，無人不道看花回。","玄都觀裏桃千樹，盡是劉郎去後栽。"]', '["紫陌紅塵拂面来，無人不道看花回。","玄都观裏桃千樹，尽是劉郎去後栽。"]', '诗', 'shi', '', NULL, '元和十一年自朗州召至京戲贈看花諸君子 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82833199-92e1-4499-8d37-92a78299f1a4', '再遊玄都觀', '再游玄都观', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["百畝庭中半是苔，桃花淨盡菜花開。","種桃道士歸何處，前度劉郎今又來。"]', '["百畝庭中半是苔，桃花淨尽菜花开。","種桃道士归何处，前度劉郎今又来。"]', '诗', 'shi', '', NULL, '再遊玄都觀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a67416-3820-4312-9cd1-a0e852a6f972', '與歌者米嘉榮', '與歌者米嘉榮', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["唱得涼州意外聲，舊人唯數米嘉榮。","近來時世輕先輩，好染髭鬚事後生。"]', '["唱得涼州意外声，旧人唯數米嘉榮。","近来时世轻先輩，好染髭鬚事後生。"]', '诗', 'shi', '', NULL, '與歌者米嘉榮 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0826a24-d535-4694-afc4-9818a327c2ab', '望夫石', '望夫石', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["終日望夫夫不歸，化爲孤石苦相思。","望來已是幾千載，只似當時初望時。"]', '["終日望夫夫不归，化爲孤石苦相思。","望来已是幾千載，只似當时初望时。"]', '诗', 'shi', '', NULL, '望夫石 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7734c93d-ef83-4857-abc1-07708e9099b3', '聽舊宮中樂人穆氏唱歌', '听旧宮中乐人穆氏唱歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曾隨織女渡天河，記得雲間第一歌。","休唱貞元供奉曲，當時朝士已無多。"]', '["曾隨织女渡天河，記得云间第一歌。","休唱貞元供奉曲，當时朝士已無多。"]', '诗', 'shi', '', NULL, '聽舊宮中樂人穆氏唱歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e03469-e857-45ba-8d0e-128339365f0f', '金陵五題 石頭城', '金陵五題 石头城', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山圍故國周遭在，潮打空城寂寞回。","淮水東邊舊時月，夜深還過女牆來。"]', '["山圍故国周遭在，潮打空城寂寞回。","淮水东邊旧时月，夜深還過女牆来。"]', '诗', 'shi', '', NULL, '金陵五題 石頭城 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa92777-9bd6-45ca-9272-bac30459cf5e', '金陵五題 烏衣巷', '金陵五題 烏衣巷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朱雀橋邊野草花，烏衣巷口夕陽斜。","舊時王謝堂前燕，飛入尋常百姓家。"]', '["朱雀橋邊野草花，烏衣巷口夕陽斜。","旧时王謝堂前燕，飞入尋常百姓家。"]', '诗', 'shi', '', NULL, '金陵五題 烏衣巷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f9f0cf-2d5f-45f0-a475-1be8b4270d7d', '金陵五題 臺城', '金陵五題 台城', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["臺城六代競豪華，結綺臨春事最奢。","萬戶千門成野草，只緣一曲後庭花。"]', '["台城六代競豪华，結綺臨春事最奢。","万戶千门成野草，只緣一曲後庭花。"]', '诗', 'shi', '', NULL, '金陵五題 臺城 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9bf148-4fb2-4367-9323-d39047e97b47', '金陵五題 生公講堂', '金陵五題 生公講堂', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["生公說法鬼神聽，身後空堂夜不扃。","高坐寂寥塵漠漠，一方明月可中庭。"]', '["生公说法鬼神听，身後空堂夜不扃。","高坐寂寥塵漠漠，一方明月可中庭。"]', '诗', 'shi', '', NULL, '金陵五題 生公講堂 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3995427-1981-4fb0-b3fc-a7af7dbccf61', '金陵五題 江令宅', '金陵五題 江令宅', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南朝詞臣北朝客，歸來唯見秦淮碧。","池臺竹樹三畝餘，至今人道江家宅。"]', '["南朝词臣北朝客，归来唯见秦淮碧。","池台竹樹三畝餘，至今人道江家宅。"]', '诗', 'shi', '', NULL, '金陵五題 江令宅 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39cc8635-f169-488d-b9b2-a43a2b976c3e', '韓信廟', '韓信廟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["將略兵機命世雄，蒼黃鍾室歎良弓。","遂令後代登壇者，每一尋思怕立功。"]', '["將略兵機命世雄，蒼黄鍾室歎良弓。","遂令後代登壇者，每一尋思怕立功。"]', '诗', 'shi', '', NULL, '韓信廟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c33491-75cd-4fd7-a342-22d945eb7d1d', '李賈二大夫諫拜命後寄楊八壽州', '李賈二大夫諫拜命後寄楊八壽州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["諫省新登二直臣，萬方驚喜捧絲綸。","則知天子明如日，肯放淮南高臥人。"]', '["諫省新登二直臣，万方驚喜捧絲綸。","則知天子明如日，肯放淮南高臥人。"]', '诗', 'shi', '', NULL, '李賈二大夫諫拜命後寄楊八壽州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d18e2c-d49b-4652-a3c7-88b99f74cb07', '美溫尚書鎮定興元以詩寄賀', '美溫尚书鎮定兴元以诗寄賀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["旌旗入境犬無聲，戮盡鯨鯢漢水清。","從此世人開耳目，始知名將出書生。"]', '["旌旗入境犬無声，戮尽鯨鯢漢水清。","從此世人开耳目，始知名將出书生。"]', '诗', 'shi', '', NULL, '美溫尚書鎮定興元以詩寄賀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1136355-7861-40d0-ade1-d0f22d2e8bd1', '酬瑞州吳大夫夜泊湘川見寄一絕', '酬瑞州吳大夫夜泊湘川见寄一絕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["夜泊湘川逐客心，月明猿苦血沾襟。","湘妃舊竹痕猶淺，從此因君染更深。"]', '["夜泊湘川逐客心，月明猿苦血沾襟。","湘妃旧竹痕猶淺，從此因君染更深。"]', '诗', 'shi', '', NULL, '酬瑞州吳大夫夜泊湘川見寄一絕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284dada0-0eaf-4dea-94a2-bb3289525ff4', '徵還京師見舊番官馮叔達', '徵還京師见旧番官馮叔達', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前者匆匆襆被行，十年憔悴到京城。","南宮舊吏來相問，何處淹留白髮生。"]', '["前者匆匆襆被行，十年憔悴到京城。","南宮旧吏来相问，何处淹留白髮生。"]', '诗', 'shi', '', NULL, '徵還京師見舊番官馮叔達 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8c5c2c-22a9-4b63-883e-1e183a57fb74', '與歌者何戡', '與歌者何戡', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["二十餘年別帝京，重聞天樂不勝情。","舊人唯有何戡在，更與殷勤唱渭城。"]', '["二十餘年別帝京，重闻天乐不勝情。","旧人唯有何戡在，更與殷勤唱渭城。"]', '诗', 'shi', '', NULL, '與歌者何戡 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5387e5-af75-4f80-98eb-e2f83e968af8', '與歌童田順郎', '與歌童田順郎', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天下能歌御史娘，花前葉底奉君王。","九重深處無人見，分付新聲與順郎。"]', '["天下能歌御史娘，花前葉底奉君王。","九重深处無人见，分付新声與順郎。"]', '诗', 'shi', '', NULL, '與歌童田順郎 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00378041-9811-47d0-84cd-73975741fd5d', '燕爾館破屏風所畫至精人多歎賞題之', '燕爾館破屏风所畫至精人多歎賞題之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["畫時應遇空亡日，賣處難逢識別人。","唯有多情往來客，強將衫袖拂埃塵。"]', '["畫时應遇空亡日，賣处难逢識別人。","唯有多情往来客，強將衫袖拂埃塵。"]', '诗', 'shi', '', NULL, '燕爾館破屏風所畫至精人多歎賞題之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9bac657-4da7-41af-ad6a-a3171a828f61', '賞牡丹', '賞牡丹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["庭前芍藥妖無格，池上芙蕖淨少情。","唯有牡丹真國色，花開時節動京城。"]', '["庭前芍藥妖無格，池上芙蕖淨少情。","唯有牡丹真国色，花开时節动京城。"]', '诗', 'shi', '', NULL, '賞牡丹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad1e0702-7843-4713-af02-f852033baf63', '題欹器圖', '題欹器圖', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["秦國功成思稅駕，晉臣名遂歎危機。","無因上蔡牽黃犬，願作丹徒一布衣。"]', '["秦国功成思稅駕，晉臣名遂歎危機。","無因上蔡牽黄犬，願作丹徒一布衣。"]', '诗', 'shi', '', NULL, '題欹器圖 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a734dd-b434-428e-ab3f-695ac637d516', '傷桃源薛道士', '傷桃源薛道士', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["壇邊松在鶴巢空，白鹿閑行舊徑中。","手植紅桃千樹發，滿山無主任春風。"]', '["壇邊松在鹤巢空，白鹿闲行旧徑中。","手植紅桃千樹發，满山無主任春风。"]', '诗', 'shi', '', NULL, '傷桃源薛道士 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091fe3c1-8d53-4ad5-b259-a3c04a701c26', '王思道碑堂下作', '王思道碑堂下作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蒼蒼宰樹起寒煙，尚有威名海內傳。","四府舊聞多故吏，幾人垂淚拜碑前。"]', '["蒼蒼宰樹起寒煙，尚有威名海內傳。","四府旧闻多故吏，幾人垂泪拜碑前。"]', '诗', 'shi', '', NULL, '王思道碑堂下作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffe9567-755d-4e51-859f-ca61f0be9195', '傷愚溪三首 一', '傷愚溪三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["溪水悠悠春自來，草堂無主燕飛回。","隔簾惟見中庭草，一樹山榴依舊開。"]', '["溪水悠悠春自来，草堂無主燕飞回。","隔簾惟见中庭草，一樹山榴依旧开。"]', '诗', 'shi', '', NULL, '傷愚溪三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e5751c-db7b-46cc-b873-1912dbf5f4d5', '傷愚溪三首 二', '傷愚溪三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["草聖數行留壞壁，木奴千樹屬鄰家。","唯見里門通德牓，殘陽寂寞出樵車。"]', '["草聖數行留壞壁，木奴千樹屬鄰家。","唯见里门通德牓，殘陽寂寞出樵车。"]', '诗', 'shi', '', NULL, '傷愚溪三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e837808-e4c9-4856-a18d-aae3b083f76f', '傷愚溪三首 三', '傷愚溪三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["柳門竹巷依依在，野草青苔日日多。","縱有鄰人解吹笛，山陽舊侶更誰過。"]', '["柳门竹巷依依在，野草青苔日日多。","縱有鄰人解吹笛，山陽旧侶更誰過。"]', '诗', 'shi', '', NULL, '傷愚溪三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2a355f-cafd-405a-bfbf-1af7434d4be0', '傷循州渾尚書', '傷循州渾尚书', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["貴人淪落路人衰，碧海連天丹旐回。","遙想長安此時節，朱門深巷百花開。"]', '["貴人淪落路人衰，碧海連天丹旐回。","遙想长安此时節，朱门深巷百花开。"]', '诗', 'shi', '', NULL, '傷循州渾尚書 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b06a18-b631-4b5d-a1af-871c804d60b2', '代靖安佳人怨二首 一', '代靖安佳人怨二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寶馬鳴珂踏曉塵，魚文匕首犯車茵。","適來行哭里門外，昨夜華堂歌舞人。"]', '["寶马鳴珂踏晓塵，鱼文匕首犯车茵。","適来行哭里门外，昨夜华堂歌舞人。"]', '诗', 'shi', '', NULL, '代靖安佳人怨二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa41a768-2562-4944-b491-a0f8e18bdcb9', '代靖安佳人怨二首 二', '代靖安佳人怨二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["秉燭朝天遂不回，路人彈指望高臺。","牆東便是傷心地，夜夜流螢飛去來。"]', '["秉燭朝天遂不回，路人彈指望高台。","牆东便是傷心地，夜夜流螢飞去来。"]', '诗', 'shi', '', NULL, '代靖安佳人怨二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa85f01-1d2b-488c-b2b4-b7b204078cb1', '碧澗寺見元九侍御和展上人詩有三生之句因以和', '碧澗寺见元九侍御和展上人诗有三生之句因以和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["廊下題詩滿壁塵，塔前松樹已皴鱗。","古來唯有王文度，重見平生竺道人。"]', '["廊下題诗满壁塵，塔前松樹已皴鱗。","古来唯有王文度，重见平生竺道人。"]', '诗', 'shi', '', NULL, '碧澗寺見元九侍御和展上人詩有三生之句因以和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7ffddc-7c9c-4ef4-b566-9f90df8ac7dc', '思黯南墅賞牡丹', '思黯南墅賞牡丹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["偶然相遇人間世，合在增城阿姥家。","有此傾城好顏色，天教晚發賽諸花。"]', '["偶然相遇人间世，合在增城阿姥家。","有此傾城好顏色，天教晚發賽諸花。"]', '诗', 'shi', '', NULL, '思黯南墅賞牡丹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58af510-727b-41ae-8524-7f361fe57916', '和浙西尚書聞常州楊給事製新樓因寄之作', '和浙西尚书闻常州楊給事製新楼因寄之作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["文昌星象盡東來，油幕朱門次第開。","且上新樓看風月，會乘雲雨一時回。"]', '["文昌星象尽东来，油幕朱门次第开。","且上新楼看风月，會乘云雨一时回。"]', '诗', 'shi', '', NULL, '和浙西尚書聞常州楊給事製新樓因寄之作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80dc947-2e79-4e9f-abb0-27b28b246b4f', '從梁宣明二帝碑堂下作', '從梁宣明二帝碑堂下作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉馬朝周從此辭，園陵寂寞對豐碑。","千行宰樹荆州道，暮雨蕭蕭聞子規。"]', '["玉马朝周從此辞，园陵寂寞对豐碑。","千行宰樹荆州道，暮雨蕭蕭闻子規。"]', '诗', 'shi', '', NULL, '從梁宣明二帝碑堂下作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc70b4c3-9de2-474c-a0b9-fe81be854dc5', '贈李司空妓', '贈李司空妓', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高髻雲鬟宮樣妝，春風一曲杜韋娘。","司空見慣渾閑事，斷盡蘇州刺史腸。"]', '["高髻云鬟宮樣妝，春风一曲杜韋娘。","司空见慣渾闲事，斷尽蘇州刺史腸。"]', '诗', 'shi', '', NULL, '贈李司空妓 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46cb238-b2e6-4182-93b4-7dcef4037347', '贈李司空妓', '贈李司空妓', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["髪鬢梳頭宫様妝，春風一曲杜韋娘。","司空見慣渾閑事，斷盡蘇州刺史腸。"]', '["髪鬢梳头宫様妝，春风一曲杜韋娘。","司空见慣渾闲事，斷尽蘇州刺史腸。"]', '诗', 'shi', '', NULL, '贈李司空妓 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e7f2d8-b0ed-4bb4-81d9-a1acba530eb9', '和西川李尚書傷孔雀及薛濤之什', '和西川李尚书傷孔雀及薛濤之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉兒已逐金鐶葬，翠羽先隨秋草萎。","唯見芙蓉含曉露，數行紅淚滴清池。"]', '["玉兒已逐金鐶葬，翠羽先隨秋草萎。","唯见芙蓉含晓露，數行紅泪滴清池。"]', '诗', 'shi', '', NULL, '和西川李尚書傷孔雀及薛濤之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22fd731-e400-4a31-baef-ec055010aabe', '同樂天登棲靈寺塔', '同乐天登棲靈寺塔', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["步步相攜不覺難，九層雲外倚闌干。","忽然笑語半天上，無限遊人舉眼看。"]', '["步步相携不覺难，九層云外倚闌干。","忽然笑語半天上，無限游人舉眼看。"]', '诗', 'shi', '', NULL, '同樂天登棲靈寺塔 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('365fea04-14ad-416f-bf79-f64d20cb9441', '同樂天登棲靈寺塔', '同乐天登棲靈寺塔', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["步步相㩦不覺難，九霄雲外倚欄杆。","忽然語笑半天上，無限游人舉眼看。"]', '["步步相㩦不覺难，九霄云外倚欄杆。","忽然語笑半天上，無限游人舉眼看。"]', '诗', 'shi', '', NULL, '同樂天登棲靈寺塔 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bd726b-3133-4ccc-81f5-286e2f7fb97c', '有所嗟二首 一', '有所嗟二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["庾令樓中初見時，武昌春柳似腰肢。","相逢相笑盡如夢，爲雨爲雲今不知。"]', '["庾令楼中初见时，武昌春柳似腰肢。","相逢相笑尽如梦，爲雨爲云今不知。"]', '诗', 'shi', '', NULL, '有所嗟二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67e75c4-48ee-4b4d-8723-477181eb3cf7', '有所嗟二首 二', '有所嗟二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鄂渚濛濛煙雨微，女郎魂逐暮雲歸。","只應長在漢陽渡，化作鴛鴦一隻飛。"]', '["鄂渚濛濛煙雨微，女郎魂逐暮云归。","只應长在漢陽渡，化作鴛鴦一隻飞。"]', '诗', 'shi', '', NULL, '有所嗟二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d9b781-8b83-4ef2-ae19-6c5623a6d7f4', '和裴相公傍水閑行', '和裴相公傍水闲行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["爲愛逍遙第一篇，時時閑步賞風煙。","看花臨水心無事，功業成來二十年。"]', '["爲愛逍遙第一篇，时时闲步賞风煙。","看花臨水心無事，功業成来二十年。"]', '诗', 'shi', '', NULL, '和裴相公傍水閑行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34cd178-ca8f-4df2-9e6c-c6462f95c165', '杏園花下酬樂天見贈', '杏园花下酬乐天见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["二十餘年作逐臣，歸來還見曲江春。","遊人莫笑白頭醉，老醉花間有幾人。"]', '["二十餘年作逐臣，归来還见曲江春。","游人莫笑白头醉，老醉花间有幾人。"]', '诗', 'shi', '', NULL, '杏園花下酬樂天見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297dd100-6aab-4685-a52d-983fb0999c7a', '和樂天春詞', '和乐天春词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新妝面面下朱樓，深鎖春光一院愁。","行到中庭數花朵，蜻蜓飛上玉搔頭。"]', '["新妝面面下朱楼，深鎖春光一院愁。","行到中庭數花朵，蜻蜓飞上玉搔头。"]', '诗', 'shi', '', NULL, '和樂天春詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f274e16-fb5c-4701-a1c3-e792595f68ee', '和嚴給事聞唐昌觀玉蘂花下有游仙二絕 一', '和嚴給事闻唐昌观玉蘂花下有游仙二絕 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉女來看玉蘂花，異香先引七香車。","攀枝弄雪時廻顧，驚怪人間日易斜。"]', '["玉女来看玉蘂花，異香先引七香车。","攀枝弄雪时廻顧，驚怪人间日易斜。"]', '诗', 'shi', '', NULL, '和嚴給事聞唐昌觀玉蘂花下有游仙二絕 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e142303-aaf5-4140-8862-185ff992ff1f', '和嚴給事聞唐昌觀玉蘂花下有游仙二絕 二', '和嚴給事闻唐昌观玉蘂花下有游仙二絕 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雪蘂瓊絲滿院春，衣輕步步不生塵。","君平簾下徒相問，長伴吹簫別有人。"]', '["雪蘂瓊絲满院春，衣轻步步不生塵。","君平簾下徒相问，长伴吹簫別有人。"]', '诗', 'shi', '', NULL, '和嚴給事聞唐昌觀玉蘂花下有游仙二絕 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('523565ac-9da4-4234-986d-0041fb103f80', '憶樂天', '憶乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["尋常相見意殷勤，別後相思夢更頻。","每遇登臨好風景，羨他天性少情人。"]', '["尋常相见意殷勤，別後相思梦更頻。","每遇登臨好风景，羨他天性少情人。"]', '诗', 'shi', '', NULL, '憶樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1cd191a-cfcb-4220-9840-bc474fad15aa', '醉答樂天', '醉答乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛城洛城何日歸，故人故人今轉稀。","莫嗟雪裏暫時別，終擬雲間相逐飛。"]', '["洛城洛城何日归，故人故人今轉稀。","莫嗟雪裏暫时別，終擬云间相逐飞。"]', '诗', 'shi', '', NULL, '醉答樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0a45d3-6074-47b7-8cee-b604d340fc39', '虎丘寺見元相公二年前題名愴然有詠', '虎丘寺见元相公二年前題名愴然有詠', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["滻水送君君不還，見君題字虎丘山。","因知早貴兼才子，不得多時在世間。"]', '["滻水送君君不還，见君題字虎丘山。","因知早貴兼才子，不得多时在世间。"]', '诗', 'shi', '', NULL, '虎丘寺見元相公二年前題名愴然有詠 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8242d05f-b07e-4a8d-ad75-710422e89030', '寄贈小樊', '寄贈小樊', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["花面丫頭十三四，春來綽約向人時。","終須買取名春草，處處將行步步隨。"]', '["花面丫头十三四，春来綽約向人时。","終須買取名春草，处处將行步步隨。"]', '诗', 'shi', '', NULL, '寄贈小樊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6abb45a-382e-4fec-8da5-4afc0d6b7095', '吟樂天自問愴然有作', '吟乐天自问愴然有作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["親友關心皆不見，風光滿眼倍傷神。","洛陽城裏多池館，幾處花開有主人。"]', '["親友关心皆不见，风光满眼倍傷神。","洛陽城裏多池館，幾处花开有主人。"]', '诗', 'shi', '', NULL, '吟樂天自問愴然有作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6786ee9a-bf68-4f46-93db-a28db6d641dc', '和令狐相公別牡丹', '和令狐相公別牡丹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["平章宅裏一欄花，臨到開時不在家。","莫道兩京非遠別，春明門外即天涯。"]', '["平章宅裏一欄花，臨到开时不在家。","莫道兩京非远別，春明门外即天涯。"]', '诗', 'shi', '', NULL, '和令狐相公別牡丹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ed2896-eee7-4a18-8792-580a028e8844', '和令狐相公聞思帝鄉有感', '和令狐相公闻思帝乡有感', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["當初造曲者爲誰，說得思鄉戀闕時。","滄海西頭舊丞相，停杯處分不須吹。"]', '["當初造曲者爲誰，说得思乡戀闕时。","滄海西头旧丞相，停杯处分不須吹。"]', '诗', 'shi', '', NULL, '和令狐相公聞思帝鄉有感 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bfa7e9-d235-4299-ac2a-739edb8aec90', '酬令狐相公見寄', '酬令狐相公见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["羣玉山頭住四年，每聞笙鶴看諸仙。","何時得把浮丘袖，白日將昇第九天。"]', '["羣玉山头住四年，每闻笙鹤看諸仙。","何时得把浮丘袖，白日將昇第九天。"]', '诗', 'shi', '', NULL, '酬令狐相公見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6077890b-6397-4828-b0d1-502a2860e925', '令狐相公春思見寄', '令狐相公春思见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一紙書封四句詩，芳晨對酒遠相思。","長吟盡日西南望，猶及殘春花落時。"]', '["一紙书封四句诗，芳晨对酒远相思。","长吟尽日西南望，猶及殘春花落时。"]', '诗', 'shi', '', NULL, '令狐相公春思見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0e1597-5f7d-4f21-85c2-d8094c84071a', '城內花園頗曾遊翫令公居守亦有素期適春霜一夕委謝書實以荅令狐相公見謔', '城內花园頗曾游翫令公居守亦有素期適春霜一夕委謝书實以荅令狐相公见謔', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["樓下芳園最占春，年年結侶採花頻。","繁霜一夜相撩治，不似佳人似老人。"]', '["楼下芳园最占春，年年結侶採花頻。","繁霜一夜相撩治，不似佳人似老人。"]', '诗', 'shi', '', NULL, '城內花園頗曾遊翫令公居守亦有素期適春霜一夕委謝書實以荅令狐相公見謔 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c2d1184-da33-4539-ad6d-2533461a9c7b', '奉和裴晉公涼風亭睡覺', '奉和裴晉公涼风亭睡覺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["驪龍睡後珠元在，仙鶴行時步又輕。","方寸瑩然無一事，水聲來似玉琴聲。"]', '["驪龙睡後珠元在，仙鹤行时步又轻。","方寸瑩然無一事，水声来似玉琴声。"]', '诗', 'shi', '', NULL, '奉和裴晉公涼風亭睡覺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247d6876-899a-4ee0-99e0-37fbcb40d56a', '荅裴令公雪中訝白二十二與諸公不相訪之什', '荅裴令公雪中訝白二十二與諸公不相訪之什', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉樹瓊樓滿眼新，的知開閤待諸賓。","遲遲未去非無意，擬作梁園坐右人。"]', '["玉樹瓊楼满眼新，的知开閤待諸賓。","遲遲未去非無意，擬作梁园坐右人。"]', '诗', 'shi', '', NULL, '荅裴令公雪中訝白二十二與諸公不相訪之什 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff2f610-cf75-436c-9a08-a5d05aa0514d', '吳方之見示聽江西故吏朱幼恭歌三篇頗有懷故林之想吟諷不足因而和之', '吳方之见示听江西故吏朱幼恭歌三篇頗有懷故林之想吟諷不足因而和之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["侯家故吏歌聲發，逸處能高怨處低。","今歲洛中無雨雪，眼前風景是江西。"]', '["侯家故吏歌声發，逸处能高怨处低。","今歲洛中無雨雪，眼前风景是江西。"]', '诗', 'shi', '', NULL, '吳方之見示聽江西故吏朱幼恭歌三篇頗有懷故林之想吟諷不足因而和之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e33e6019-5068-4775-a82c-93017558495b', '裴令公見示誚樂天寄奴買馬絕句斐言仰和且戲樂天', '裴令公见示誚乐天寄奴買马絕句斐言仰和且戲乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["常奴安得似方回，爭望追風絕足來。","若把翠娥酬騄耳，始知天下有奇才。"]', '["常奴安得似方回，爭望追风絕足来。","若把翠娥酬騄耳，始知天下有奇才。"]', '诗', 'shi', '', NULL, '裴令公見示誚樂天寄奴買馬絕句斐言仰和且戲樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07201c67-20e9-4f48-b984-270a576a9fca', '酬思黯代書見戲', '酬思黯代书见戲', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["官冷如漿病滿身，凌寒不易過天津。","少年留取多情興，請待花時作主人。"]', '["官冷如漿病满身，凌寒不易過天津。","少年留取多情兴，請待花时作主人。"]', '诗', 'shi', '', NULL, '酬思黯代書見戲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdbac9b7-a27a-42c8-bedb-058acd358421', '荅張侍御賈喜再登科後自洛赴上都贈別', '荅張侍御賈喜再登科後自洛赴上都贈別', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["又被時人寫姓名，春風引路入京城。","知君憶得前身事，分付鶯花與後生。"]', '["又被时人寫姓名，春风引路入京城。","知君憶得前身事，分付鶯花與後生。"]', '诗', 'shi', '', NULL, '荅張侍御賈喜再登科後自洛赴上都贈別 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087353c5-04ce-4b56-8ff5-53cb393316d7', '赴連州途經洛陽諸公置酒相送張員外賈以詩見贈率爾酬之', '赴連州途經洛陽諸公置酒相送張員外賈以诗见贈率爾酬之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["謫在三湘最遠州，邊鴻不到水南流。","如今暫寄罇前笑，明日辭君步步愁。"]', '["謫在三湘最远州，邊鴻不到水南流。","如今暫寄罇前笑，明日辞君步步愁。"]', '诗', 'shi', '', NULL, '赴連州途經洛陽諸公置酒相送張員外賈以詩見贈率爾酬之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36a6e25-4b16-4a1b-b233-bdb1e6e7d0c4', '贈元九侍御文石枕以詩獎之', '贈元九侍御文石枕以诗獎之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["文章似錦氣如虹，宜薦華簪綠殿中。","縱使涼飆生旦夕，猶堪拂拭愈頭風。"]', '["文章似錦氣如虹，宜薦华簪綠殿中。","縱使涼飆生旦夕，猶堪拂拭愈头风。"]', '诗', 'shi', '', NULL, '贈元九侍御文石枕以詩獎之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc66bd2e-bfd3-4f97-b7c4-1f4b2714a5ea', '酬元九院長自江陵見寄', '酬元九院长自江陵见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["無事尋花至仙境，等閑栽樹比封君。","金門通籍真多士，黃紙除書每日聞。"]', '["無事尋花至仙境，等闲栽樹比封君。","金门通籍真多士，黄紙除书每日闻。"]', '诗', 'shi', '', NULL, '酬元九院長自江陵見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2beb9853-953e-41d8-bd7e-25063ff7a2dc', '酬楊侍郎憑見寄', '酬楊侍郎憑见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["翔鸞闕底謝皇恩，纓上滄浪舊水痕。","疎傅揮金忽相憶，遠擎長句與招魂。"]', '["翔鸾闕底謝皇恩，纓上滄浪旧水痕。","疎傅揮金忽相憶，远擎长句與招魂。"]', '诗', 'shi', '', NULL, '酬楊侍郎憑見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae51f029-6b26-429a-8b37-002b0326b07d', '酬馬大夫登洭口戍見寄', '酬马大夫登洭口戍见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新辭將印拂朝纓，臨水登山四體輕。","猶念天涯未歸客，瘴雲深處守孤城。"]', '["新辞將印拂朝纓，臨水登山四體轻。","猶念天涯未归客，瘴云深处守孤城。"]', '诗', 'shi', '', NULL, '酬馬大夫登洭口戍見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606bdb0c-ec97-43a2-b996-b753278b7306', '荅楊八敬之絕句', '荅楊八敬之絕句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["飽霜孤竹聲偏切，帶火焦桐韻本悲。","今日知音一留聽，是君心事不平時。"]', '["飽霜孤竹声偏切，带火焦桐韻本悲。","今日知音一留听，是君心事不平时。"]', '诗', 'shi', '', NULL, '荅楊八敬之絕句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580191cd-73ba-4ba6-bf15-1b3c9ac7a667', '重寄表臣二首 一', '重寄表臣二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["對酒臨流奈別何，君今已醉我蹉跎。","分明記取星星鬢，他日相逢應更多。"]', '["对酒臨流奈別何，君今已醉我蹉跎。","分明記取星星鬢，他日相逢應更多。"]', '诗', 'shi', '', NULL, '重寄表臣二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61b2193-eb61-4161-ad99-2d0d0539fa83', '重寄表臣二首 二', '重寄表臣二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["世間人事有何窮，過後思量盡是空。","早晚同歸洛陽陌，卜隣須近祝雞翁。"]', '["世间人事有何窮，過後思量尽是空。","早晚同归洛陽陌，卜隣須近祝雞翁。"]', '诗', 'shi', '', NULL, '重寄表臣二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a438183d-15cb-4056-a55c-5e95c4e84630', '重寄絕句', '重寄絕句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淮西既是平安地，鴉路今無羽檄飛。","聞道唐州最清靜，戰場耕盡野花稀。"]', '["淮西既是平安地，鴉路今無羽檄飞。","闻道唐州最清静，戰場耕尽野花稀。"]', '诗', 'shi', '', NULL, '重寄絕句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb3f2a0-7987-4666-9eb4-38d04290e78a', '酬楊八副使將赴湖南途中見寄一絕', '酬楊八副使將赴湖南途中见寄一絕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["知逐征南冠楚材，遠勞書信到陽臺。","明朝若上君山上，一道巴江自此來。"]', '["知逐征南冠楚材，远勞书信到陽台。","明朝若上君山上，一道巴江自此来。"]', '诗', 'shi', '', NULL, '酬楊八副使將赴湖南途中見寄一絕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67dec81a-f8f6-4544-a14c-2d552b86124d', '遙和韓睦州元相公二君子', '遙和韓睦州元相公二君子', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["玉人紫綬相輝映，却要霜鬚一兩莖。","其奈無成空老去，每臨明鏡若爲情。"]', '["玉人紫綬相輝映，却要霜鬚一兩莖。","其奈無成空老去，每臨明镜若爲情。"]', '诗', 'shi', '', NULL, '遙和韓睦州元相公二君子 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3ca14e-2e41-419e-b30a-d58ff94c4f93', '吳興敬郎中見惠斑竹杖兼示一絕聊以謝之', '吳兴敬郎中见惠斑竹杖兼示一絕聊以謝之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一莖炯炯琅玕色，數節重重玳瑁文。","挂到高山未登處，青雲路上願逢君。"]', '["一莖炯炯琅玕色，數節重重玳瑁文。","挂到高山未登处，青云路上願逢君。"]', '诗', 'shi', '', NULL, '吳興敬郎中見惠斑竹杖兼示一絕聊以謝之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1921fb0d-1d20-418e-831e-29e91b1a3117', '奉和裴令公夜宴', '奉和裴令公夜宴', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天下蒼生望不休，東山雖有但時游。","從來海上仙桃樹，肯逐人間風露秋。"]', '["天下蒼生望不休，东山雖有但时游。","從来海上仙桃樹，肯逐人间风露秋。"]', '诗', 'shi', '', NULL, '奉和裴令公夜宴 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5543626-4658-4fca-bba0-b768fdcba4d9', '秋夜安國觀聞笙', '秋夜安国观闻笙', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["織女分明銀漢秋，桂枝梧葉共颼飀。","月露滿庭人寂寂，霓裳一曲在高樓。"]', '["织女分明銀漢秋，桂枝梧葉共颼飀。","月露满庭人寂寂，霓裳一曲在高楼。"]', '诗', 'shi', '', NULL, '秋夜安國觀聞笙 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8ac638-7b92-4579-8d9a-53c10c0d0dc4', '酬僕射牛相公晉國池上別後至甘棠館忽夢同游因成口號見寄', '酬僕射牛相公晉国池上別後至甘棠館忽梦同游因成口號见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["已嗟池上別魂驚，忽報夢中攜手行。","此夜獨歸還乞夢，老人無睡到天明。"]', '["已嗟池上別魂驚，忽報梦中携手行。","此夜独归還乞梦，老人無睡到天明。"]', '诗', 'shi', '', NULL, '酬僕射牛相公晉國池上別後至甘棠館忽夢同游因成口號見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc12da6b-c150-4fd6-9140-b33d122be8d2', '裴侍郎大尹雪中遺酒一壺兼示眼疾平一絕有閑行把酒之句斐然仰酬', '裴侍郎大尹雪中遺酒一壺兼示眼疾平一絕有闲行把酒之句斐然仰酬', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["卷盡輕雲月更明，金箆不用且閑行。","若傾家釀招來客，何必池塘春草生。"]', '["卷尽轻云月更明，金箆不用且闲行。","若傾家釀招来客，何必池塘春草生。"]', '诗', 'shi', '', NULL, '裴侍郎大尹雪中遺酒一壺兼示眼疾平一絕有閑行把酒之句斐然仰酬 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a95c24-a37e-4308-a30a-c61a1d4ea1c3', '和滑州李尚書上巳憶江南禊事', '和滑州李尚书上巳憶江南禊事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白馬津頭春日遲，沙州歸鴈拂旌旗。","柳營唯有軍中戲，不似江南三月時。"]', '["白马津头春日遲，沙州归鴈拂旌旗。","柳營唯有軍中戲，不似江南三月时。"]', '诗', 'shi', '', NULL, '和滑州李尚書上巳憶江南禊事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3baef3db-7066-4b26-8732-e3756c6fa05b', '酬柳柳州家雞之贈', '酬柳柳州家雞之贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日日臨池弄小雛，還思寫論付官奴。","柳家新樣元和脚，且盡畺芽歛手徒。"]', '["日日臨池弄小雛，還思寫論付官奴。","柳家新樣元和脚，且尽畺芽歛手徒。"]', '诗', 'shi', '', NULL, '酬柳柳州家雞之贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0fbd8da-2fab-4130-8ee1-d38436a12db8', '荅前篇', '荅前篇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["小兒弄筆不能嗔，涴壁書窗且當勤。","聞彼夢熊猶未兆，女中誰是衛夫人。"]', '["小兒弄笔不能嗔，涴壁书窗且當勤。","闻彼梦熊猶未兆，女中誰是衛夫人。"]', '诗', 'shi', '', NULL, '荅前篇 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7bb766e-56a6-4911-ab96-cb0370840034', '荅後篇', '荅後篇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔日慵工記姓名，遠勞辛苦寫西京。","近來漸有臨池興，爲報元常欲抗行。"]', '["昔日慵工記姓名，远勞辛苦寫西京。","近来漸有臨池兴，爲報元常欲抗行。"]', '诗', 'shi', '', NULL, '荅後篇 劉禹錫 shi');
